window.__D("text/shaarei-orah/c001",{"p":[[2201340074,"האור הנמשך מלמעלה למטה (וכמו בדלי\"ת רבתי שמכוין להמליכו בשמים וארץ וד' רוחות העולם) וכן לפעמים א' מלך יחיד שנקרא מלך מרומם לבדו נמשך להיות חי העולמים כו' וכמו\"כ הוא בבחי' העלאה מלמטה למעלה שירומם לאלקי המלך כמו שהוא מלך יחיד מרומם לבדו שיומשך אח\"כ כמו שהוא בעצמותו גם בעולמות וזהו ואברכה שמך לעולם ועד כמו ענין בשכמל\"ו כידוע שבחי' המל' נק' שם כמו ויעש דוד שם ויתברך שם כבוד מלכותו למטה גם בעולמות הנפרדים בבחי' נצחיות דא\"ס וזהו ועד נצחיות בחילוף אותיות דאחד ובמה ירומם לאלקי המלך כו' היינו ע\"י שירות ותשבחות שאומר איך שכל העולמות ומלאכים בטלים ממציאותם לגמרי מיש לאין ע\"י שיר ורינה כו' שעי\"ז מעלים לבחי' המל' למעלה לקבל מבחי' כתר מל' וזהו כתר יתנו לך כו' כידוע (וזהו משובח ומפואר בלשון חסידיו ועבדיו נשמות ומלאכים דבי\"ע ובשירי דוד עבדך נהללך כו' עד ונמליכך מלכינו אלקינו להיות יחיד חי העולמים מלך גם למטה כמו למעלה להיות משובח ומפואר עדי עד בבחי' נצחיות דא\"ס שהוא מל' דא\"ס עצמו שנקרא שמו הגדול כידוע) וזהו להודיע לבנ\"א שהן הנשמות גבורותיו בחי' ריבוי הכח של הצמצומים כדי להיות הדר כבוד מלכותו העצמיות בעולמות לאין שיעור למטה כמו שאין שיעור למעלה בהתנשאות שמצד עצמו ממש כו' וראי' לזה הוא מה שמתפשט גם בכח האלקי המצומצם להיות מקור להתהוות העולמות ג\"כ בבחי' התחלקות לאין שיעור כלל וכלל וכמ\"ש גדול אדונינו ורב כח לאין שיעור (וכמ\"ש בס\"י דשיעור קומ' של יוצר בראשית רל\"ו רבבות אלפים פרסאות כו' בגימ' דורב כח כמ\"ש ביאורו במ\"א) וכמ\"ש ועלמות אין מספר א\"ת עלמות אלא עולמות וכתיב היש מספר לגדודיו כו' (ואעפ\"י שנאמר המוציא במספר צבאם הן הן גבורותיו לצמצם כו' ועכ\"ז אין שיעור להתפשטות זו כמ\"ש בס\"י ה' אבנים בונות ק\"ך בתים כמו ק\"ך צירופים דשם אלקים מכאן ואילך צא וחשוב עד אין שיעור כו' וכמ\"ש ביאור זה במ\"א) וזהו להודיע לבנ\"א גבורותיו ואחר כך אמר מלכותך מל' כ\"ע וד\"ל (וזהו מ\"ש בזהר ע\"פ אלקים אל דמי לך דנה\"ת קארי תדיר לנה\"ע ולא שכיך לעלמין והוא מ\"ש למען יזמרך כבוד התחתון דמל' בבי\"ע לכבוד עליון דבחי' כתר מל' כנ\"ל:\n(ה) <b>והנה</b> כאשר האדם יתבונן בעומק דעתו ולבו בבחי' יח\"ת דמל' בעולמות בחי' ממלא כ\"ע שהוא בכח האור האלקי המהווה כל העולמות מאין ליש כנ\"ל (בבשכמל\"ו) יתפעל בלבו באהבה אלקית לאהוב את ה' בכל לבבו והיינו בשני יצריך כמ\"ש ואהבת בכל לבבך והוא שע\"י השגה אלקית הזאת הנקלטת היטב במוח ולב יתפעל גם בלב בשר הטבעי להיות בו כליון ותשוקה נפלאה ברשפי אש שלהבת י\"ה עד שימאס ויהפוך כל רצון זר ורע דחום הטבעי להיות לו רק לב אחד לאביו שבשמים כו' כמו שהנשמה בעצמה תכסוף בתשוקה האלקי' היפך טבע הגוף החומרי שנקרא רוח הבהמה שיורדת למטה כו' בהתפעלות אמתית מקרב ולב עמוק בכל כוחות הנה\"ט כו' לפי שהתבוננות זאת דכח האלקי בעולמות קרובה לנפש האדם לראות גם בעיני בשר כמ\"ש שאו מרום עיניכם וראו מי ברא אלה פי' וראו כמו בראי' חושיות ממש כו' עד שיכול להיות התהפכות הרצונות זרות לגמרי דהיינו להיות מתהפכים בהתפעלות רשפי אש התשוקה לה' לבדו ונמצא גם החום הטבעי שמלא רע נהפך לקדושה האלקית ממש (ונקרא בר לבב ממש אשר לא נשא לשוא נפשו ורצונו כלל רק לה' לבדו כמו מי לי בשמים ועמך לא חפצתי בארץ כלה שארי ולבבי כו') עד שנעשה לבו לב טהור לגמרי באותה שעה עכ\"פ בבחי' ביטול היש לאין האלקי באמת"],[2201340075,"לאמתו (מפני ששורה עליו בחי' אור האלקי דמל' בעולמות כמו שמאיר למעלה במלאכים עליונים כשבטלים במציאות כו') וזהו ממש כדמיון הפתילה שדולקת בשלהבת אש הנדלק בה שנהפכת למהות אש ואור כו' כך נהפך הגוף שהוא אש וחום הטבעי של תאוה רעה עצמה למהות התשוקה האלקי' שנקרא רשפי אש שלהבת י\"ה דנשמה האלקית כנ\"ל להיות רק לה' לבדו כמ\"ש בכל לבבך בשני יצריך שגם היצה\"ר שבחלל השמאלי יאהוב את ה' בהתפעלות רשפי אש שלהבת י\"ה האלקי ממש וכמו שאנו רואים שיש התפעלות אלקות ממש בלב בשר דוקא וכמו לבי ובשרי ירננו כו' רק שאינו נמשך זמן רב מטעם שאין בחי' השמן דכח מ\"ה הנ\"ל נמשך אחר הפתיל' כנ\"ל ומבואר למעלה שזהו הנק' נהורא אוכמא אש השחור השורף ומכלה לפתילה מעט מעט כו' כך אור האלקי שבהתפעלות הנשמה מהשגה דממלא כ\"ע הנ\"ל שורף ומכלה ללב הטבעי להפכו לאור הקדושה (וכמו כן למעלה במל' דאצילות בהתלבשותה בעולמות שזהו ג\"כ כמו התלבשות הנשמה בגוף ונק' נשמת כל חי כו' שנק' ממלא כ\"ע נק' ג\"כ נהורא אוכמא כנ\"ל לפי שמהפך להיות ביטול היש לאין בכל העולמות עד גם הע' שרים דנוגה דעשיה שגם הם בטלים ונכללים באלקים חיים בשירה כמ\"ש מלך אלקים על גוים וכתיב הללו את ה' כל גוים כו' וכן הבו לה' משפחות עמים כו' וכה\"ג רבות בכתובים כמו יראו מה' כל הארץ כו' הריעו לה' כל הארץ כו' וזהו כמו התהפכות ז' מדות רעות דנה\"ט ממש באדם התחתון כידוע) (ומ\"ש ונר רשעים ידעך היינו גם כשמבטשים אותם ידעך ויקפץ נרם יותר כשהן בבחי' פירוד גמור מבחי' הרע גמור דגקה\"ט לגמרי כו' ובצדיקים כתיב ואור צדיקים כו' וגופא דלא סליק ביה נהורא דנשמתא מבטשין ליה וסליק ביה כו' כאעא דלא סליק ביה נהורא כו' וכנראה בחוש שע\"י ביטוש בבני חיי ומזוני בגוף יאיר בו אור הנשמה לעשות בו הרהור תשובה בלב נשבר מאד ולהכנע באמת לה' ולהתפעל באוי\"ר בתשוקת רשפי אש שלהבת י\"ה דנשמה ובזה הוא ההפרש בין נוגה דמעורב טו\"ר לגקה\"ט דרע גמור וכמ\"ש ושבתם וראיתם בין צדיק לרשע בין עובד אלקי' כו' אך גם ברשעים כתיב ויתלבנו ויתבררו כו' וכמ\"ש ובאו האובדים כו' כי לא ידח ממנו נדח וגם באוה\"ע כתיב אז אהפוך אל עמים כו' והנה כל זה הוא בחי' נהורא אוכמא שנדלק בפתילה כנ\"ל אבל בחי' נהורא חיוורא הנ\"ל שנק' אור המאיר הוא בא מבחי' התבוננות השניה דבחי' סובב כ\"ע דוקא והוא בשם הוי\"ה דאצילות ביח\"ע דשמע ישראל כנ\"ל וכידוע שזהו בע\"ס דאצילות שמיוחדים בעצמות א\"ס ב\"ה דאיהו וחיוהי חד ממש כמ\"ש ה' אלקינו ה' אחד ממש באח\"פ דא\"ס עצמו שהוא למעלה מעלה מבחי' המל' שנעשה מקור לעולמות וכמ\"ש כי עמך מקור חיים כו' כידוע וכך הוא למעלה מעלה גם מעולם האצילות שהרי א' אנת הוא חד ולא בחושבן פי' לא בחושבן י\"ס דלפני אחד מה אתה סופר ונק' ע\"ס בלי מ\"ה בלי מהות כלל משום דלאו מכל אינון מדות כלל כו' והיינו עצמות א\"ס ב\"ה ממש שגם מה שמצמצם א\"ע להיות מקור לע\"ס דאצילות זהו רק הארה בעלמא הנק' קו\"ח שנמשך ממל' דא\"ס עצמו ע\"י צמצום הראשון כידוע כמו מאצילות לבי\"ע ממש כנ\"ל וע\"ז אמר כי עמך מקור כל חיי העולמות דאבי\"ע כו' והוא הנקרא סובב כ\"ע הכללי שמקיף לד' עולמות דאבי\"ע בשוה ממש וזהו מלך יחיד חי העולמים בכללות הכל כו' או יחיד חי העולמים מלך וכן מל' מלכות כ\"ע בכללות ע\"ד הנ\"ל בב' מדריגות במל' דאצי' כו' וד\"ל ולמעלה גם מזה הוא למעל' גם מהיות בבחי' מקיף וסובב כללי לאבי\"ע כו' רק כמו שהוא במהו\"ע ממש (שנק' טה\"ע שמי השמים כו' ועיקר מס\"נ באחד היינו למהו\"ע ממש דוקא כמ\"ש אליך ה' נפשי אשא אליך ממש כידוע וד\"ל):"],[2201340076,"(ו) <b>והנה</b> ע\"י העמקת המוח והלב היטב בהתבוננות זאת השני' דבחי' סובב כ\"ע בכללות והוא למס\"נ באח\"פ ממש כנ\"ל אז עי\"ז ודאי יומשך מבחי' סובב כ\"ע שהוא שם הוי\"ה בכלל בחי' אור העליון דבחי' אור הזרוע לצדיק עליון שנקרא נהורא חיוורא על נשמת האדם גם בניצוץ קטן שבישראל והוא מ\"ש כי אתה נרי הוי\"ה ממש וכן כי אתה תאיר נרי וכמ\"ש בהלו נרו עלי ראשי דקאי הכל על בחי' אור העליון הזה שהוא בבחי' שם הוי\"ה דאצילות ממש שמשם יאיר אור האלקי על כאו\"א במס\"נ שלו באח\"פ ע\"י התבוננות הזאת דוקא ביח\"ע דשמע ישראל כו' והוא הנקרא אור המאיר שהוא בחי' אלקות ממש וע\"ז אמר ואהבת את הוי\"ה אלקיך בכל נפשך ממש כו' וכמו לאהבה את הוי\"ה אלקיך כי הוא חייך ממש לפי שמשם מקור מחצב כל חיי אור העצמות דנשמת כל חי כו' אך איך יוכל אדם להעמיק דעתו ולבו בהתבוננות דסוכ\"ע הכללי שהוא עצמות א\"ס ב\"ה ממש מאחר שהוא למעלה מעלה גם ממקור כל חיי העולמות כנ\"ל והרי א' דאנת עילאה על כל עילאין וסדכ\"ס דלמת\"ב כלל (אפי' מח' הקדומה דא\"ק כו') הענין ידוע דבמח' והשגה אין תפיסה והשגה כלל וכלל במהו\"ע ית' ממש אבל ברצון הפשוט ועצמי הוא שנתפס להיות בו דביקות והתכללות ממש כמ\"ש לדבקה בו בו ממש והוא מ\"ש בכל נפשך וכמו כלתה נפשי כו' אליך ה' נפשי אשא ממש וד\"ל ועוד יש דבר שעל ידו יהיה כל או\"א דבוק במהו\"ע ית' אחר שיתפעל במס\"נ בנקודת הרצון הפשוט כנ\"ל והוא במ\"ש והיו הדברים האלה אשר אנכי מצוך היום פי' אנכי הוא מי שאנכי דהיינו בחי' סובב כ\"ע הכללי הנ\"ל ולמעלה מזה שהוא מוה\"ע ית' ממש הוא אשר אנכי מצוך היום דוקא והענין הוא לפי שאין בחי' עצמות א\"ס ב\"ה ממש בא לידי גילוי למטה ממש כ\"א ע\"י מצות מעשיות בעוה\"ז דוקא שהוא סוף כל המדרגות העליונות לפי שנעוץ תחלתן בסופן דוקא דהיינו תחלת כל התחלות בסוף הכל שהוא המעשה דמצוה בפ\"מ שזהו הנקרא ארחות הוי\"ה ממש כמ\"ש סוף דבר כו' ואת מצותיו שמור כי זה כל האדם דלעילא (וכידוע בענין אל יתהלל חכם כו' כ\"א בזאת יתהלל המתהלל השכל וידוע אותי ממש לעשות חסד ומשפט וצדקה בארץ דוקא כי באלה חפצתי בחפץ ורצון הקדום ממש כו') וזהו אשר אנכי ממש בחי' מוה\"ע מצוך היום במצות בפ\"מ הוא מתגלה דוקא והיום בעוה\"ז דוקא כמ\"ש ז\"ל היום לעשותם כו' ולא כמו שהן ברוחניות ביח\"ע בעולמות עליונים אלא בסוף מעשה בפ\"מ בגשמיות דוקא והוא לפי שעולמות עליונים הרי הן באים בסדר ההשתלשלות עו\"ע מאור א\"ס ב\"ה ע\"י ריבוי צימצומים כידוע שמפני זה ודאי אי אפשר שיתגלה בהם מבחינת מהו\"ע ית' ממש בגילוי דלמת\"ב כלל כנ\"ל רק שלא בדרך השתלשלות עו\"ע אלא בדרך ירידה והתלבשות לבד כמו במעשה המצות בפ\"מ בגשמיות דוקא הוא שיכול לבא למטה בגלוי כי לעצם רוממות ערך האור דא\"ס עצמו לא יבא בדרך השתלשלות כלל כ\"א בדרך התלבשות למטה דוקא שלא בהדרגה כלל וכידוע הכלל בכל מקום שכל הגבוה גבוה יותר יותר יוכל לבא בירידה במקום היותר נמוך דוקא וכמ\"ש המגביהי לשבת המשפילי כו' וכתיב אני מרום כו' וכן א' איזה בית אשר כו' כי השמים ושה\"ש לא יכלכלוהו ועכ\"ז צמצם שכינתו בין בדי הארון בהיכל ומקום גשמי וכך הוא בענין התלבשות אור א\"ס ממש בכל מצוה בפ\"מ וז\"ש אשר אנכי מצוך היום דוקא ולא למחר בעוה\"ב כו' (וזהו ענין דבר החמישי הנוסף על ד' דברים שבאור הנר והוא כלי הנר עצמו המחזיק הכל וכמ\"ש כי נר מצוה ותורה אור הרי הנר מחזיק לכל עיקר ומקור דאור תורה שזהו בחי' אור המאיר שהוא גלוי אור הוי\"ה ממש כנ\"ל לפי שנתב\"ס דוקא שהוא הכלי שנק' נר מצוה דוקא וד\"ל) והנה בחי' המעשה בתו\"מ שבכחם יש להמשיך גילוי"],[2201340077,"מהו\"ע ית' להאיר אור דשם הוי\"ה ממש כנ\"ל הוא בחי' השמן שנמשך אחר הפתילה שמחמתו דוקא יבא גלוי אור העליון דאור המאיר שנק' נה\"ח שהוא לפ\"ע צלילת השמן כנ\"ל לפי שנשאב בפתילה ומושך את האור כו' וכנ\"ל דמן השמן בא לגלוי ב' גווני אור הללו דנ\"ח ונה\"א כו' והיינו מ\"ש והיו הדברי' האלה דוקא שהוא דברי התורה אשר אנכי מצוך היום שיבואו בפ\"מ כו' (וכמ\"ש ושננתם כו' וקשרתם כו' שהוא כולל כל מעשה המצות דוקא כידוע):\n(ז) <b>וזהו</b> קרוב ה' לכל קוראיו לכל אשר יקראוהו באמת פי' קרוב שהוא קרוב לכל בשוה לקטן כגדול בלי חילוק מדרגות כלל וזהו לכל קוראיו יהי' מי שיהי' והיינו לכל אשר יקראוהו באמת דוקא שזהו כמו שהוא באמתת עצמותו שהוא בחי' סובב כ\"ע הנ\"ל שאינו בא בדרך השתלשלות עו\"ע כלל רק בא בדרך בחי' התלבשות בתו\"מ בסוף מעשה דוקא כנ\"ל בזה הרי הוא קרוב לכל קוראיו והוא הקורא בתורה כמ\"ש והיו הדברים האלה כו' ודברת בם כו' שקורא לבחי' מוה\"ע ית' ממש שלמעלה מעלה מכל ההשתלשלות דאבי\"ע כנ\"ל וזהו באמת אין אמת אלא תור' שהוא אמתת עצמותו ית' ששוה לפניו קטן וגדול וקרוב הוא לכולם בשוה ממש משא\"כ הקריא' והצעקה בתפל' שאע\"פ שנא' מי כה' אלקינו בכל קראינו אליו דוקא כמו אליך ה' נפשי אשא כו' לבחי' מוה\"ע ממש כנ\"ל אבל אינו בא לכלל קירוב גמור לכל בשוה אלא לכל א' כפום שיעורא דילי' בהכנת לבו ודעתו ורצונו כו' כמ\"ש אם ישים אליו לבו כו' וגם זה מרחוק ה' נראה לי ולא בקירוב גמור וכל זה מפני שגם זה האור העליון דבחי' סובב כ\"ע הבא ע\"י התבוננות דשמע ישראל כו' והתפעלות דואהבת בכל לבבך ונפשך כו' צריך לבא בדרך השפעה מלמעלה למטה שהוא בא בדרך ההשתלשלות עד כל א' בשרשו בע\"ס דבי\"ע בחילוק המדריגו' דנר\"נ ששרשם בחיצוניות הכלים דאצילות כידוע ושורה על כאו\"א בבחי' מקיף מרחוק וז\"ש מרחוק ה' נראה לי כו' שזהו בכל אור גם היותר עליון כאשר בא בירידות המדריגות עכ\"פ כו' שנק' השתלשלות משא\"כ האור העליון זה עצמו כשבא בבחי' התלבשות בתו\"מ קרוב הוא ממש לכל כקטון כגדול ממש בשוה וכמ\"ש קראוהו בהיותו קרוב ע\"י תו\"מ וכמ\"ש כי קרוב אליך הדבר מאד בפיך ובלבבך לעשותו דוקא ולא בשמים היא כו' והוא הדבר אשר אנכי מצוך כו' מטעם הנ\"ל בפי' אנכי מצוך כנ\"ל וזהו ענין נעשה אדם בצלמנו כדמותינו כו' וקאי הכל בתו\"מ דוקא כידוע בענין נר מצוה ותורה אור ששרש התור' הוא באור והמצוה בכלי וכמ\"ש בכמה מקומות התורה והמצוה כו' שזהו ענין צלם ודמות וכידוע שצלם בדכורא ודמות בנוק' שהוא בחי' סובב וממלא בענין ההשתלשלות כנ\"ל כמו שהצלם הוא בחי' צורה העצמית כך כל ע\"ס דאצילות באו\"כ כמו חסד דרועא כו' חכמ' מוחא כו' זהו בצלמנו ממש דהיינו בשם הוי\"ה דאצילות והוא ע\"י בחי' אור דתורה כמ\"ש והיו הדברים האלה כו' שנא' וזאת תורת האדם ממש בבחי' פנימית דאו\"כ דאדם העליון וע\"כ נק' תורת הוי\"ה ממש ודמותינו בנוק' הוא בבחי' מל' שנק' מראה דמות כבוד הוי\"ה דא\"ס כמו ה' במראה אליו אתוודע וכן ביד הנביאים אדמה כו' והוא כמו הדמות שנחקק בו צורה העצמית הנק' צלם והן הנה המצות מעשיות שבאים למטה שנק' מצות המלך שמקבלים כנ\"ל שנק' נר מצוה אעפ\"י שנק' ג\"כ מצות הוי\"ה אבל הוא בא בכלים מכלים שוני' ונק' נר מצוה כו' ועכ\"ז ה\"ז בדמות כבוד הוי\"ה דאצילות עצמו ממש שזהו ענין אדם אדמה לעליון ממש וכמ\"ש כדמותינו כו' וזהו וקשרתם לאות כו' שכולל כל המצות כו' שבא בדרך התלבשות ממש בסוף מעשה כנ\"ל שבזה קרוב ה' לכל בשוה לפי שיקראוהו באמת באמתת פנימית עצמותו כמו שהוא דרמ\"ח פקודין רמ\"ח אברים"],[2201340078,"כו' ונעוץ תב\"ס דוקא וראיה לזה ממה שהעוה\"ב אינו רק ממצות בפ\"מ בגשמיו' דוקא (וכנ\"ל בפי' נר מצו' שהוא המחזיק האור והשמן והפתיל' כו'):\n(ח) <b>והנה</b> ארז\"ל דיפה שעה א' בתשובה ומע\"ט בעוה\"ז דוקא מכל חיי העוה\"ב הרי הזכיר תשובה קודם למע\"ט ומאחר שהמעשה עיקר מטעם הנ\"ל דנתב\"ס דוקא למה צריך לתשובה קודם כו' אך הנה אעפ\"י שבודאי נמשך מאמתת אור מוה\"ע א\"ס ב\"ה בתו\"מ כנ\"ל הרי צריך להיות זה ע\"י התגברות גדולה מרב חסד העליון שבעצמות ממש שיהי' בא בגלוי כמו שהוא בהעלם עצמותו ממש דלמת\"ב כלל כנ\"ל וכמ\"ש כי גבר עלינו חסדו העצמי בהתגברות גדולה הרבה יתר מכפי המדה הקצובה הבא בסדר השתלשלות דקו\"ח כו' ולבא עד למטה ממש בדרך התלבשות עכ\"פ כנ\"ל כדי להיות ואמת ה' לעולם אמתית העצמיו' דהוי\"ה יבא לגלוי לעולם למטה כמו למעלה כו' והנה בחי' התגברות רב חסד זה א\"א לבא גם בתו\"מ כ\"א ע\"י הקדמת ענין התשובה דוקא שהוא היפוך הרע עצמו לטוב שזה עולה למעלה מתו\"מ שאינו אלא להבדיל בין טו\"ר כו' ולכך א' דבע\"ת גדולים מצ\"ג שצ\"ג בתו\"מ א\"י לעמוד במקום שבע\"ת עומדים כו' וזהו דמשיח אתא לאתבא צ\"ג בתשובה להעלותם יותר מטעם שא' בזהר דכד אתכפייא סט\"א אסתלק יקרא דקוב\"ה כו' אעפ\"י שאין שרשם רק מאחוריים דשם אלקים במ\"ח צירופי' האחרונים כו' וזהו הללו את ה' כל גוים כו' שהן ביטול היש הנפרד מיש דק\"נ בע' שרים כמו שיהיה לע\"ל שיהפוך אל עמים כו' והוא כמו ענין התשובה ממש שגם הרע עצמו נהפך לטוב כו' אז דוקא יגבר עלינו כנ\"י חסדו העצמי' להיות אמת ה' אמתית פנימית עצמותו בתו\"מ בא לידי גלוי למטה כמו למעלה ממש שז\"ש ואמת ה' לעולם ממש והוא העוה\"ב שיבא אמת ה' לעוה\"ז כמו שא' ואמ' ביום ההוא הנה אלקינו זה ממש כו' וזהו שהקדים תשובה למע\"ט בעוה\"ז דעי\"ז יבא שכר חיי העוה\"ב מן המצות שהן מע\"ט ובלא תשובה אין המע\"ט מועילים שאינן רק בחי' כלים לבד להשראת עצמותו ית' וד\"ל:\n(ט) <b>ובכל</b> זה יובן ענין השמן שבנר שיש בו בהעלם ב' גווני אור דנה\"ח ונה\"א כנ\"ל כאשר נשאב ונמשך אחר הפתילה והאור כנ\"ל דהנה יש להבין תחילה מה שצריך שיהי' השמן נמשך אחר הפתילה דוקא כדי שיהי' חיבור האור בפתיל' ואיך השמן שהוא גבוה יומשך אחר הפתילה ואין האור דולק רק בפתיל' ולא בשמן מזה מוכרח שיש מעלה יתירה בפתיל' יותר מן השמן עד שהשמן אינו אלא אמצעי לחבר האור בפתילה הענין הוא כידוע שיש שרש לנה\"ט שהוא הגוף למעלה הרבה מן הנשמה לפי שנה\"ט נלקחה מק\"נ שנפלו בשבה\"כ מז' מלכים דתהו דכתיב ואלה המלכים כו' לפני מלוך מלך לבנ\"י כו' דבחי' אורות דתהו קדמו לבחי' התיקון דשם מ\"ה דאדם וע\"כ יש שרש לחיות ובהמות דפני ארי' ופני שור דמרכבה למעלה מבחי' אדם וע\"כ נושאות את הכסא כו' וכמו למטה מטה בירידתן עוד האדם ניזון מן החי וצומח ויתחזק כח שכלו כו' וכך למעלה נאמר בקרבן בהמה לחמי לאשי ריח ניחוח להוי\"ה דתיקון וכמ\"ש במ\"א כמו שעל הלחם יחי' האדם ולא יתקיים בלעדו והצומח וחי יתקיימו בלא אדם לפי ששרש הצו\"ח בשרשו גבוה משרש האדם וע\"כ ע\"י כליון הפתילה שהוא הגוף הוא עיקר הגורם המשכת האור העליון להאיר את הנשמה מבחי' סובב כ\"ע הכללי הנ\"ל שז\"ש כי אתה נרי הוי\"ה כו' כי הגם שהשמן הוא הסיבה לחיבור האור בפתילה כנ\"ל ה\"ז רק ממוצע אבל עיקר הסיבה הוא כליון הפתילה דוקא רק שע\"י השמן הוא סיבה שיאחז בו האור וגם מה שהשמן נשאב בפתילה ונכלה ונמשך ונשאב באור גם הוא ע\"י הפתילה והוא הטעם שהשמן נמשך אחר הפתילה דוקא ליכלל באור כו' לפי שהשמן הוא בבחי' חכמה דתו\"מ כנ\"ל ושרש הפתיל' שהוא הנה\"ט הוא"],[2201340079,"למעלה מעלה מבחי' מ\"ה דחכ' דתקון כנ\"ל וראי' לזה מענין הנ\"ל בשעה א' בתשובה ומע\"ט שע\"י תשובה דוקא שהוא היפוך הרע עצמו לטוב עי\"ז דוקא יגבר חסדו עלינו להיות אמת ה' לעולם שהוא העוה\"ב שבא מן התו\"מ כנ\"ל וד\"ל וזהו שאחר ואהבת בכל לבבך בשני יצריך ובכל נפשך כו' שזהו כליון הפתיל' הוא שא' אח\"ז והיו הדברים כו' אשר אנכי מצוך כו' שמתגלה עי\"ז מבחי' אור העליון ביותר שהוא סובב הכללי שמלובש בתו\"מ כנ\"ל וד\"ל ונמצא שבחי' נהורא אוכמא השורף ומכלה לפתילה עי\"ז גורם ממילא גלוי האור העליון דנה\"ח ממקורו שהוא בעצמות א\"ס ב\"ה כמ\"ש כי אתה תאיר נרי כו' אך הנה עכ\"ז ב' גווני אור הללו שמתגלים בפתילה הוא ע\"י השמן שהוא הסיבה לחיבור האור בפתילה בב' גוונין הללו שהרי בלא שמן הי' הפתילה כלה ונשרפת לגמרי במהרה או שהי' האור קופץ מעליה מיד כנ\"ל וכך יובן למעלה דהנה ענין השמן הוא בחי' העלם דאור ח\"ע שמלובש בתו\"מ שא\"א לבא בדרך השתלשלות כלל כ\"א דרך התלבשות וכמו עוטה אור כשלמה שהוא אור דתורה ונק' משל הקדמוני וכמאמר נובלות חש\"מ תורה כו' שזהו ענין עוצם ירידה והתלבשות דח\"ע העצמי' שלתבונתו אין מספר כלל בענינים גשמיים בהלכות ודינין דתשב\"כ ושבע\"פ כו' ברמ\"ח מ\"ע ושס\"ה ל\"ת וזהו כמו טבע השמן שהוא נמשך ויורד ומתעלם בכל דבר (כמשי\"ת) ע\"כ נמשך השמן גם אחר הפתילה לחברו באור והוא ענין הנ\"ל בב' מדריגות דחכמ' א' לעשות בחי' ביטול היש לאין והוא מה שיתעורר גם בגוף הרהור תשובה בהכנעה עצומ' ולב נשבר כו' ועי\"ז יבא ענין כליון הפתילה באשא אוכמא שזהו ענין הצעקה והעלאה בתפיל' בשפיכת נפש להפוך המדות רעות שבלב כו' כנ\"ל וזה נעשה בסיבת השמן שנמשך בפתילה:\n(י) <b>ואמנם</b> אחר בחי' ההעלאה דנה\"ט בבחי' רצוא כמו אם ישים אליו לבו כו' הרי רוח אייתי רוח ואמשיך רוח שממילא יבא עי\"ז בחי' המשכה וירידת האור שבא בהתלבשות למטה בכלי דוקא שהוא הנק' בחי' שוב שהוא מ\"ש והיו הדברים כו' אחר בכל נפשך כו' והיינו בחי' סובב כ\"ע שבתו\"מ כנ\"ל שנק' שמן כי הרי כליון הפתילה גורם עיקר המשכת האור שיומשך ויכלה גם השמן כנ\"ל ואמנם במה שהשמן נשאב באור הוא הגורם צלילת ובהירות האור העליון בנשמ' מבחי' סובב כ\"ע שנק' נה\"ח כנ\"ל והוא מדרגה הב' דחכמה כח מ\"ה ממש כמו שהיא בבחי' אין ממש והוא ענין השפלות והענוה שנק' ביטול עצמי שנפשו כעפר לכל בעצם מפני העדר הרגשת עצמו מכל וכל כנ\"ל ונמצא דשמן זה יש בו מב' הגוונים דנה\"ח ונה\"א בהעלם ויצאו לגלוי באור הפתילה במה שנמשך בפתילה ונשאב באור שהרי בהירות אור העליון תלוי בצלילת השמן דוקא כנ\"ל ועכ\"ז הרי העיקר הוא כליון הפתילה שהוא הגורם המשכת האור העליון מטעם הנ\"ל רק שבהירתו תלוי בצלילת השמן לבד וגם הוא הסיבה להמשכת השמן וכלותו באור כנ\"ל הטעם ששרש הפתילה שהוא הנה\"ט למעלה מבחי' חכמה וע\"כ בלא בחי' רצוא דתפילה א\"א להיות בחי' שוב דתו\"מ כנ\"ל וכן תשובה ואח\"כ מע\"ט וראי' לזה ממה שא' האומר אין לי אלא תורה אפי' תורה אין לו כמו שבלא כליון הפתילה אין השמן נמשך באור כלל אבל גם זה אמת דע\"י השמן דתורה הוא הסיבה לחיבור האור בפתילה ובלעדו אין קיום לאור בפתילה כלל אפי' רגע כנ\"ל וכך הוא העלאה דרצוא בתפילה בלא תורה שאינו מתקיים כלל כידוע וד\"ל:\n<b>(ונמצא</b> שהשמן מחבר האור בפתילה והפתילה מחבר השמן באור וזה כמו אדם שמעלה את הצומח ואח\"כ הצו\"ח מעלהו מטעם הנ\"ל והאור מורכב משניהם בין בגוון השחור שכלה בו הפתילה והשמן בין בגוון העליון שנמשך אחר השחור המכלה לפתילה ושמן רק שבהירתו הוא לפי זכות השמן וצלילתו (וגם לפ\"ע כליון הפתילה בגוון השחור כו'):"],[2201340080,"(יא) <b>והנה</b> א' בזהר ושמן על ראשך אל יחסר דא הוא עובדן טבאן כו' הרי עיקר ענין השמן שעל הראש להיות גורם חיבור אור ה' בנשמת אדם הן המע\"ט בפ\"מ ולמעלה מבואר דעיקר השמן הוא בחי' חכמה שבתורה שנק' תורה אור הענין הוא דשרש השמן הוא בבחי' פנימיות ומקור דח\"ע דתורה אור ואמנם בירידתו למטה במצות מעשיות בענינים גשמיים כמו בציצית ותפילין גשמיים וכה\"ג בדינין והלכות דשבת בהוצאה מרה\"י לרה\"ר וכה\"ג בכל דיני או\"ה וטומאה וטהרה כו' הנה זהו בחי' ירידה והתלבשות זאת למטה כ\"כ נק' בשם שמן משחת קדש העליון דפנימית חכמה דתורה כו' כי מטבע החכמ' להתמשך למטה בכל הדברים גם בדבר היותר תחתון דוקא כמו משלים וחידות (כטבע השמן שיורד ומפעפע בכל דבר ונבלע בו כו') והטעם הוא כמו שאנו מוצאים בס' הטבע שנמצא טבעיות השמן בכל הנמצאי' שבעולם בכל חלקי דצח\"ם דעשיה וד\"י ארמ\"ע המורכבי' בהם מכולם יוכלו להוציא שמן גם בחלק הדומם כמו ושמן מחלמיש צור הרי מחלמיש צור יוציאו שמן הגם שהצור קשה כו' והוא מפני שיש בכל מציאת בריאה בחי' התמצית חומר ההיולי שבו שהוא נהפך לשמן וגם בחלק המדבר כמו גופו של אדם מת שמורכב מד\"י אחר הבירור היטב ישאר רק כמו שמן (שנק' אלים) והיינו בחי' החכמ' שהיא בחי' התמצית ההיולי שנמצ' בכל מציאת מורכב כו' שמזה עיקר מציאותו כידוע לפי שנא' כולם בחכמ' עשית בחכמ' דוקא וע\"כ בכל עולם ועולם נמצא עיקר קיומו מבחי' החכמ' והוא לפי שבחכמה שורה בחי' כח ואי\"ן האלקי ממש המהווה למציאת זה העולם עד כל בריאה בפרטות שבו וכמ\"ש מה רבו מעשיך ה' כולם בחכמ' עשית כו' רק שיורדת החכמ' בהשתלשלות מעולם לעולם כמו מחכמה דמל' דאצילות בעולם הבריאה ומחכמ' דמל' דבריאה ביצי' כו' עד בחי' חכמ' שבמל' דמל' דעשיה בגלגלים וכל דצח\"ם וארמ\"ע כו' שנמצא כח החכמה בכל פרט כו' הרי טבע החכמ' לירד מטה מטה דוקא עד היותר תחתון מכל כו' וכך יובן באור החכמ' שבתורה הקדומה כידוע דשרש התורה הוא בחכמ' דא\"ס עצמו וירדה בבחי' השתלשלות והתלבשות בד' עולמות באצילות ונק' תור' דאצילות ותורה דבריאה ויצירה שהוא הכל בבחי' הרוחניות עדיין (כמו שא\"א קיים כל התורה ברוחניות כמו שהיא למעלה ביצי' ובריאה ואצי' כו' עד תורה הנגלית לנו בעולם העשי' בפ\"מ בדברים גשמיים דנוגה דעשי' בעה\"ד טו\"ר להבדיל בין טו\"ר בפ\"מ (וכך אנו מוצאים בחכמת שלמה שנמשך מח\"ע ובאה בנשמתו בהתלבשו' במשלי' וחידות כמ\"ש וידבר ג\"א משל כו' וכה\"ג):\n(יב) <b>ואמנם</b> בחי' ח\"ע דתורה הגם שבאה ג\"כ בהשתלשלות בעולמות ה\"ז בחי' פנימית ומקור לחיות העולמות שנמצאים מבחי' החכמ' דאצילו' וכמ\"ש אם לא בריתי יומם ולילה חוקו' כו' וכתיב ואשים דברי בפיך לנטוע שמים כו' וכה\"ג לפי שנאמר בה ואהי' אצלו אמון אצלו ממש דאסתכל באורייתא וברא עלמא כו' וכן הת\"ח נק' בונים שעוסקים בבנינו ש\"ע וגם אפי' תשב\"ר שהעולם מתקיים ע\"י הבל ד\"ת שלהם כידוע וזהו והיו הדברים האלה אשר אנכי מצוך היום ששרש דברים האלה מבחי' אנכי ממש רק שירדו למטה מטה במה שאנכי מצוך היום בדברים גשמי' דוקא מטעם הנ\"ל וד\"ל וז\"ש ושמן על ראשך כו' זהו מע\"ט בפ\"מ שזהו שרש בחי' מקור האור דתורה כמו שהיא למעלה בעצמותו ית' טרם שירדה למטה בעולמות דאבי\"ע לפי שנעוץ תב\"ס דוקא כנ\"ל וזהו הנק' שמן שעל ידו דוקא יבא בחי' הבהקת האור העליון דנשמה ממקור האור דחכמ' שז\"ש בהלו נרו כו' כי אתה תאיר נרי וכה\"ג לפ\"ע צלילת השמן דוקא מטעם זה וע\"כ הזהיר ושמן על ראשך אל יחסר שהן המע\"ט דוקא שמזה דוקא"],[2201340081,"יבא שרש הבהקת האור תמיד ממקורו שאם יחסר השמן יכבה האור ואין לו קיום כלל כנ\"ל וד\"ל ומובן מזה שהשמן נמשך גם בכל דברים התחתונים ביותר שיש בכח החכמה כח מ\"ה להשיב בתשובה שלימה גם להיותר תחתון שנפל בשאול תחתית כו' (ואמנם הבהקת אור הנשמה מן התשובה יותר גדול מהבהקת אור דמצוה וראיה מנתן דצוציתא שראהו ר\"ע שהיה אור נשמתו מאיר בהבהקה נפלאה ביותר מאור נשמות הצ\"ג וכמו בתשובה דראב\"ד שא' רבי יש קונה עולמו בשעה א' כו' מטעם הנ\"ל דכח התשובה מגיע למעלה מתורה ומצות והוא ענין משיח דאתא לאתבא צ\"ג בתשובה דכתיב ביה ישכיל עבדי ירום כו' וגבה מאד למעלה מבחי' אדם דתו\"מ כו' (וזהו שאז\"ל דמשה לא זכה לתשובה רק קודם מותו כו') אך זהו דוקא כאשר צ\"ג נעשים בע\"ת שיש כאן תשובה ומע\"ט אבל תשובה בלא מע\"ט הרי אין כאן בחי' שמן כלל רק כליון הפתילה וכנ\"ל בענין תפלה בלא תורה כו' וז\"ש דאתא לאתבא צדיקייא דוקא בתיובתא כו' וכמ\"ש במ\"א בענין ראה ריח בני כריח שדה אשר כו' דזה היא התלבשות יעקב צ\"ג בבגדי עשו להיות בע\"ת כו' שעולה למעלה מתו\"מ להוסיף אור גדול בתו\"מ אבל לא רצה שיתעלה עשו לבדו ע\"י תשובה בלא תו\"מ דיעקב כו' וד\"ל):\n(יג) <b>ובכל</b> זה יובן הטעם שהחכמה נק' בשם ראי' כמו וירא ראשית לו שהחכמה שנק' ראשית נק' בבחי' ראיה וע\"כ החכמים נק' בשם עיני העדה כידוע וכמאמר איזהו חכם הרואה את הנולד שרואה מה שיהיה לעתיד שנעלם מהכל כמו שרואין לאור הנר ממש כל דבר הנעלם מן העין כך החכמה נק' אור שיראה החכם בחכמתו כל הנעלם לפי שבשרשה החכמה מאין תמצא לגלוי אור לראות כל דבר הנעלם ונק' עין השכל שרואה כמו לפני האור בהבהקתו וכך הוא בבחי' חכמה בחי' כח מ\"ה שבנשמה שהוא בבחי' ראי' עין השכל לאמיתת אור אלקי כמו שהוא למעלה מן השגת והבנת השכל שנק' בינה וכמאמר אינו דומה שמיעה לראיה כידוע שהשמיעה הוא בבינה והשגה שמרחוק והראיה הוא בחכמה בעין השכל מקרוב כמו שאינו דומה שמיעה לראיה בגשמיות כו' (וכנ\"ל בענין השמן שלפי ערך צלילתו כך יראה אור זך בהיר כו') והנה כתיב הן יראת ה' היא חכמה הרי החכמה היא היראה וכן ראשית חכמה יראת ה' כו' דראיה אותיות יראה וכמאמר אם אין חכמה אין יראה כו' ולכאורה מה שייך היראה עם החכמה כו' אך הנה ידוע בזהר ור\"מ שיש ד' מדריגות דחילו ורחימו רחימו ודחילו הרי יש ב' מיני יראה יראה הקודמת לאהבה ויראה שאחר האהבה והן ב' מדרגות דיראה תתאה ויראה עילאה וב' מיני רחימו באמצע רחימו תתאה שאחר יראה תתאה ורחימו עילאה שקודם ליראה עילאה ויראה עילאה היא העולה על הכל שזהו בחי' יו\"ד דחכמה שז\"ש הן יראת ה' היא חכמה כח מ\"ה בחי' ביטול במציאות ממש וז\"ש אם אין חכמה אין יראה ויראה תתאה היא האחרונה מכולן כידוע וביאור כל זה הנה ידוע בד' מדריגות הללו דדחילו ורחימו רחימו ודחילו שהן ד' אותיות דשם הוי\"ה שבנשמת אדם היו\"ד הוא בחי' דחילו עילאה שהוא בחי' ראיה דחכמה מקרוב דוקא לראות בעין השכל לאור אמתת אלקות כמו שהוא מחיה את כל העולמות מאין ליש וכה\"ג שעי\"ז בא לכלל ביטול עצמי שניזוז ממקומו לגמרי בהעדר הרגשת עצמו לגמרי שנק' ביטול במציאות לאלקים חיים למעלה מן הטעם ודעת כלל ואין זו מדרגה גבוה כי ישנה בכאו\"א גם בניצוץ קטן מישראל ביוד דשם הוי\"ה שבנשמתו גם שהיא רק נפש דעשי' אם לא פגם באו' יו\"ד ע\"י עון וחטא ששייך לאות יו\"ד כמו בעוונות שחייב סקילה כחילול שבת וכה\"ג וגם בביטול ת\"ת שהיא ביו\"ד דחכמה כו' והוא מה שאנו רואים בחוש שגם באיש פשוט וע\"ה יש בו ביטול כל עצמותו ממש בנקודת יהדותו בזכרו"],[2201340082,"על ה' אחד כמו למס\"נ על קדה\"ש או לשוב בתשובה שלימה וכה\"ג ובכאו\"א לפום שיעורא דיליה מאיר אור דכח מ\"ה זה דראיה בביטול המציאות בעצם למעלה מן הטעם וההשגה דוקא:\n(יד) <b>והמדרגה</b> הב' למטה הימנה הוא בחי' רחימו עילאה שהוא אות הה\"א ראשונה דשם הוי\"ה והיינו בחי' התפעלות האה\"ר שהיא מתאחדת במושכל האלקי מצד עצמו ממש ואינה נפרדת כלל והוא הנק' אהבה בתענוגים שמתענג על ה' כפי עומק ההשגה ודעת בהתבוננות דסובב כ\"ע ביח\"ע וכה\"ג והוא התענוג האלקי המורכב בשכל והשגה האלקי' ונק' התפעלות העונג שבשכל כנשמות בג\"ע שנהנין כו' כאו\"א לפי השגתו כך התפעלות התענוג באהבה וזהו נק' רחימו עילאה שמתאחדת בעומק המושג דפנימית בינה ונק' אהבה בתענוגים להתענג על ה' בהתפעלות רשפי אש התענוג (בל\"א קווע\"ל) לפ\"ע פנימית השכלה שלו (ולפ\"ע מעלת שרש נשמתו בבחי' בינה דמל') והתפעלות רחימו עילאה זו שבבינה והשגה היא למטה הרבה מבחי' ראיה דחכמה הנ\"ל כמו שאינו דומה שמיעה לראיה כי השמיעה באזן היא מגיע בעומק המושג לבד שהיא עכ\"פ בבחי' השגת שכל אלקי שהוא בבחי' יש וטעם ודעת ע\"כ ההתפעלות ממנה גם באה\"ר בתענוגים היא בבחי' יש שהרי יש מי שמתפעל ומרגיש בעצמו שהוא המתפעל כו' אבל התפעלו' הביטול במציאו' הנ\"ל שע\"י בחי' ראיה דחכמה הוא מקרוב למעלה מבחי' השגה לגמרי שהוא באמתת אור האלקי כמו שהוא ולא כמו שמושג בהשגת שכל לבד שאין זה אמתת עצמותו וכמ\"ש דלית מחשבה תפיסא ביה כלל וכאשר נתפס במח' והשגה אין זה אמתתו כו' גם בהשגות הנשמות בג\"ע שאינו אלא בבחי' בינה שנק' יש ואור א\"ס אינו מאיר רק בבחי' אין שהוא כח מ\"ה דחכמה שלמעלה מן ההשגה לגמרי כידוע וע\"כ התפעלות דחכמה רק בחי' ביטול והעדר הרגשת עצמו מכל וכל כנ\"ל כמו הבא לפני המלך מקרוב ממש שרואהו בעיניו מתבטל לגמרי ואינו מרגיש כלל א\"ע גם במה שנתבטל כו' שנק' הזזה ממקומו לגמרי כידוע וזהו מצד בחי' שגלוי אור האלקי בא מקרוב ממש בראי' דחכמ' כנ\"ל ע\"כ הוא למעל' הרב' מהתפעלו' האהב' גם מרחימו עילאה הנ\"ל וזהו שהחכמה הוא בבחי' יראה עילאה דוקא אותיות ראי' דאינו דומה שמיעה לראיה שהשמיעה גם שמשיג ומבין היטב בעומק הדבר אינו מכוין לאמתית הדבר כמו שהוא ממש רק כשרואה בעיניו דוקא כך הוא גם בהשגות אלקות דנביאים שנאמר ה' במראה כו' וביד הנביאים אדמה שאין זה כראי' במהות אלקות ממש שהוא מפני שמאיר בתוך כלי השגתם שההשג' עצמה הוא לבוש המכסה ונק' דמיון כמ\"ש אדמה וכן במראה אליו כו' וכמ\"ש מראה דמות כבוד הוי\"ה שהוא בחי' בינה שבמל' משא\"כ שם הוי\"ה עצמו ולא דמות כבוד ה' שאינו בא לפ\"ע כלי ההשגה כלל הרי הוא בבחי' ראי' מקרוב כמו במשה שהי' נבואתו פא\"פ כו' וכמאמר כל הנביאים נתנבאו בכה שהוא בחי' המל' ומשה נתנבא בזה כו' ומזה יובן בפרט בכל ניצוץ קטן הפרש כזה בין שמיעה לראיה דראי' מקרוב הוא בחי' גילוי אלקות ממש כמו כי אתה נרי ה' כו' ובשמיעה דהשגה כתיב מרחוק ה' נראה לי מרחוק ולא מקרוב כנ\"ל בענין מראה דמות כבוד ה' לפ\"ע ההשגה ולא אמתת עצמותו כו' וד\"ל:\n(טו) <b>ומדריגה</b> הג' הוא רחימו הב' שנקרא רחימו תתאה שלמטה הרבה מהתפעלות אה\"ר בתענוגים הנ\"ל הנקרא רחימו עילאה וביאור הענין ידוע שנקרא אהבה זוטא כו' והוא כידוע בפי' ואהבת ב\"פ אור או\"י וא\"ח שהן ב' אהבות הנ\"ל האמצעיים רחימו עילאה הנ\"ל היא בבחי' או\"י הבא ונמשך ממילא ומאלי' מלמעלה למטה דוקא והענין הוא כידוע שהתפעלות"],[2201340083,"העונג אלקי הבא בהשגה אלקי' בא' ממילא מלמעלה בלתי הכנה כלל כמו השיר וניגון שנעשה מאליו בעונג המושג לפי אופן ההשגה דוקא כשיר הלויים דכתיב ועבד הלוי כו' (שזהו התגלות התענוג בבינה ובמורגש דוק' כידוע) וזהו בחי' או\"י שנקרא נהורא חיוורא שהוא זך ובהיר אור המאיר הנ\"ל שבאור הנר שתלוי לפי ערך צלילת השמן דהיינו מבחי' עונג הנעלם שבחכמה כח מ\"ה הנ\"ל הנקרא עדן שהוא פנימית ועצם התענוג האלקי שלמעלה מן ההשגה לגמרי כנ\"ל בבחי' הביטול דחכמה כו' וכמ\"ש ונהר יוצא מעדן שהוא התפעלות עונג המורגש שבבינה שנקרא נהר שיוצא מהעלם התענוג שבחכמה שנקרא עדן סתימאה כו' כמו בנשמות בג\"ע בעדן עצמו טרם שבא לגילוי אור עונג מורגש בהשגות הנשמות וכן ענין העוה\"ב שנברא בי' דחכמה ובא מן ההעלם העונג דחכמה לגילוי השגה כמ\"ש להנחיל אוהבי יש ממש כו' אבל בחי' אהב' הב' היא הבאה בבחי' או\"ח מלמטה למעלה ונקרא נהורא אוכמא כו' והוא התפעלות האהבה שנולדה מן ההשגה דחיצוניות בינה שבאה בהסבר ולא מעומק המושג דפנימית בינה ונפרדת מן השכל וכאשר באה ללב בהשתנות מהות התפעלות האהבה בלב נתקצר אור השכל והשגה לגמרי כידוע זהו התפעלות אהבה ותשוקה מורגשת במוח ולב בצמאון הנפש שביסוד האש שבלב והוא בחי' אהבה דאו\"ח שבואהבת בכל לבבך מלמטה למעלה לצאת וליכלל למעלה באלקות ברשפי אש התשוקה או כאהבה הנמשכת כמים כו' והוא ענין שלהבת י\"ה דהיינו הנמשך מבינה ללב דבינה לבא שיש בכחה להיות עושה התפעלות רשפי אש דלב הטבעי להיות גם הוא בהתלהבות שלהבת התשוקה אלקי' כמו צמאה לך נפשי כמה לך בשרי ממש כו' עד שנהפך אש זרה דחום התאוה לתשוקה האלקית וכנ\"ל שזהו אש השחור השורף ומכלה שמשתנה גוונו לפי אופן דבר הנכלה בו והוא הפתילה שהיא חום הטבעי דנה\"ט להיות שגם היא דולקת בשלהבת י\"ה בצמאון גשמי שבה ונכללת בצמאון רוחני דנשמה והיו לאחדים ממש כו' וע\"כ נקרא אהבה זוטא זו בחי' או\"ח וד\"ל ומדרגה הד' הוא דחילו תתאה יראה תתאה שקודמת לאהבה דאו\"ח הנ\"ל והוא ה\"א אחרונה דשם הוי\"ה שאחר הוי\"ו דאהבה זוטא הנ\"ל (שנקרא בן יה שנולד מחו\"ב כו') והיינו ענין קבלת עמ\"ש ביראה ופחד בביטול רצון במעשה ומו\"ד ומקבל מרושם אהבה שבלב להיות מקבל העמ\"ש ברצון ולא בע\"כ כמו ומלכותו ברצון קבלו כו' כענין שום תשים עליך מלך כו' שנקרא קבלת עמ\"ש באוי\"ר כו' והיא סוף כל המדריגות מלמעלה למטה כמ\"ש סוף דבר כו' האלקים ירא כו' והיא הראשית מלמטה למעלה כמ\"ש אם אין יראה שהיא יראה תתאה אין חכמה וכתיב ראשית חכמה כו' והן ד' אותיות דשם הוי\"ה שכלולים באור הנר יו\"ד בחכמה דחילו עילאה וה\"א ראשונה רחימו עילאה דפנימית בינה הנ\"ל והן נק' דו\"ר עילאי' שכליים בכלל מטעם הנ\"ל ודו\"ר תתאין טבעיים הן יראה תתאה ואהבה זוטא רחימו תתאה הנ\"ל שנקרא נהורא אוכמא והן ו\"ה דשם הוי\"ה ונמצא שסדרן באור הנר הב' גוונין שבאור נה\"ח ונה\"א הן ב' רחימות הנ\"ל דאו\"י ואו\"ח והפתילה הוא בחי' יראה תתאה והשמן הוא בחי' יראה עילאה דחכמה שבא ממנו גילוי אור העליון נה\"ח ואור התחתון שנאחז בפתילה הוא רחימו הב' שמדליק הפתילה להיות בו כליון שהוא קבלת עמ\"ש בביטול הרצון במעשה כו' והן ד' דברים הכוללים לאור הנר שמן ופתילה וב' גווני אור כנ\"ל וכללותם הוא בשמן דחכמה שהוא חכמה דתורה שהיא ביראה עילאה כמו מה להלן באימה ביטול במציאות ממש כמו כן עתה יש יראה כזו בכל אומר דבר ה' זו הלכה כו' וכמ\"ש ואשים דברי בפיך כו' (וכמו שא' המגיד להרב\"י אני המשנה המדברת בפיך כו') וכמו רבא דיתיב באימתא ופתח בשמעתא כו' אבל אין זה"],[2201340084,"רק ע\"י כליון הפתילה שהוא יראה תתאה דקבלת עמ\"ש ע\"י האור השחור שמכלה כו' שהוא התפעלות אהבה אלקית בבחי' רצוא בתפלה להפוך גם להרע דנה\"ט כנ\"ל משום דנעוץ תחב\"ס דוקא וז\"ש ועתה ישראל מה כו' כ\"א ליראה דאע\"פ שהיא סוף הכל נעוץ בה תחלת הכל שהיא דחילו עילאה שע\"ז אמר הן יראת ה' היא חכמה שגם דלגבי משה שהוא בחכמה בראש נקרא יראה מלתא זוטרתא זהו מלמעלה למטה אבל מלמטה למעלה היראה תתאה הנ\"ל נק' פתח ושער כו' וכמ\"ש זה השער כו' וכמאמר ז\"ל בת\"ח שאין בו י\"ש דומה לגזבר שמסרו לו מפתחות הפנימיות ולא מסרו לו מפתחות החצוניות בהי עייל כו' וכך הוא בסדר התפילה בתחילה קבלת עומ\"ש בכובד ראש והכנעת הלב ואח\"כ בהתפעלות אהבה זוטא להפוך הרע וחשך לאור האלקי שזהו כליון הפתילה בשלהבת י\"ה כענין רוממות אל כו' כידוע וזהו בחי' נהורא אוכמא בבחי' או\"ח בפסוד\"ז ויוצר כו' עד ואהבת ב\"פ אור בבחי' או\"י ג\"כ דנהורא חוורא דרחימו עילאה הנ\"ל ואח\"כ בש\"ע הוא בחי' ביטול עצמי דיראה עילאה הנ\"ל שבהעדר הרגשת עצמו לגמרי והוא צלותא בלחש כמ\"ש אד' שפתי תפתח כו' כי אין מלה בלשוני כו' וע\"כ התפילה בעמידה דוקא שהוא הביטול במציאות כדומם וזהו כמו בעמדם תרפינ' כנפיהם שהן או\"י מפני שמתבטלים לגמרי ואין מי שמתפעל כו' כמ\"ש במ\"א וד\"ל:\n(טז) <b>וזהו</b> כי אתה נרי הוי\"ה וה' יגיה חשכי פי' כי אתה אתה ממש והוא בחי' מוה\"ע א\"ס ב\"ה ממש שלמעלה מעלה משם הוי\"ה בד' אותיות דיו\"ד ה\"א כו' דשם הוי\"ה הוא באור הנמשך ובא בבחי' השתלשלות בקו\"ח כו' להיות בבחי' סובב וממלא בכלל ובפרט כו' שאז צריך להיות נקודה די' שהוא בחי' הצמצום והה\"א הוא בחי' ההתפשטות וכמ\"ש כי בי\"ה ה' צור עולמים כו' ואח\"כ וא\"ו ה\"א המשכה והתפשטות כו' אבל אתה ממש הוא עצמות א\"ס ב\"ה כמו שהוא קודם הצמצום הראשון שהי' הוא ושמו בלבד כידוע ע\"כ אתה דוקא נרי הוי\"ה כמו כי אתה תאיר נרי שתאיר ותמשיך מעצמך להיות מקור לנרי להיות בחי' נר הוי\"ה בד' אותיות די' כו' והיינו ע\"י אתעדל\"ת בכנ\"י כשנקרא נר הוי\"ה בד' דברים הנ\"ל שמן ופתילה וב' גווני אור הנ\"ל שיש בכאו\"א מישראל בנשמה וגוף שהוא האור והפתילה כנ\"ל והשמן דתורה ומצות שממשיך מן ההעלם לגלוי ב' גווני אור הנ\"ל דנה\"ח ונה\"א בחי' צ\"ע וצ\"ת כמ\"ש ועמך כולם צדיקים כו' עי\"ז נעשה אתעדל\"ע ממהו\"ע ית' להאיר אור העצמות בד' אותיות דהוי\"ה למעלה שהן יו\"ד דח\"ע שנקרא שמן משחת קדש דתורה למעלה להאיר בב' גווני אור דסובב וממלא כנ\"ל להאיר משם בפתילה הדולקת בנהורא אוכמא שהוא ו\"ה בכלל וכל זה אתה ממש תאיר למעלה ומשם יאיר בנר הוי\"ה שבכל אחד וזהו כי אתה נרי הוי\"ה וכמו בהלו נרו עלי ראשי כו' וכמו ששרש נש\"י למעלה דבוקים בשם הוי\"ה ממש כמ\"ש כי חלק הוי\"ה עמו כו' ע\"ז א' כי אתה נרי הוי\"ה ממש גם בלא בחי' העלאת מ\"ן כו' וכאשר מאיר מאצילות לבי\"ע עד נשמות שבגופים למטה כי אתה תאיר נרי כו' ע\"י אתדל\"ת דוקא וכמו בהעלותך את הנרות כו' וד\"ל ובכל זה יובן ענין הנס דחנוכה בדרך כלל דהנה מבואר למעלה במ\"ש כי אתה תאיר נרי כו' שתלוי באתדל\"ת בבחי' העלאה דנר ה' נשמת אדם בד' דברים הנ\"ל וזה הי' ענין הדלקות הנרות במקדש דכתיב בהעלותך את הנרות שהן כללות נש\"י שנקרא נרות ה' והן ז' נרות נגד ז' מדות דקדושה והן ע' נפש דיעקב שכל מדה כלולה מי' כו' כידוע וזהו שארז\"ל על נרות המנורה במקדש וכי לאורה הוא צריך אלא עדות הוא שהשכינה שורה בישראל שהוא שם הוי\"ה העליון דאצילות כנ\"ל אך זה תלוי לפ\"ע ההעלאה באתדל\"ת בקרבנות הציבור ובקטרת דאז כתיב שמן וקטרת ישמח לב האדם העליון שמן"],[2201340085,"המנורה וקטרת דהיינו נרות וקטרת שאחר הקרבת דם התמיד כו' ועכשיו התפילה במקום קרבן כידוע וכנ\"ל דאחר בכל לבבך בשני יצריך דוקא א' והיו הדברים כו' שהוא השמן לחבר האור בפתילה כו' אבל ענין נר חנוכה בכלל הוא למעלה ממדרגות הדלקות הנרות במקדש (שהרי הי' עיקר הנס במה שהדליקו נרות בחצרות קדשיך בחוץ) והוא מה שהי' אתדל\"ע מצד עצמו להאיר אור דשם הוי\"ה בנש\"י שלא ע\"י אתדל\"ת בהכנת ד' דברים הנ\"ל הכוללים באור הנר שהוא שמן ופתיל' כו' שהרי טמאו העכו\"ם כל השמנים שבהיכל כו' (כמשי\"ת) וע\"ז א' כי אתה נרי הוי\"ה מצד עצמותך וע\"כ וה' יגיה חשכי כו' (וראיה לזה מהפטרה דמנורת זכריה בחנוכה שלא הי' שם הדלקת אור כלל רק שמן מוצק מעצמו בגולה שעל ראשה ומן הגולה בז' וז' מוצקות כו' וזה מדבר בזמן הגלות שנק' חשך שהכל בהעלם ומקור האור דחכמה והוא השמן כמ\"ש במ\"א באריכות ע\"פ כי עמך מקור חיים כו' וע\"כ מתחיל מרני ושמחי כו' הנני בא ושכנתי מעצמי בתוכך כו' שממילא יבא הרינה ושמחה רננה בלילה ושמחה בצפרא והוא נה\"ח ונה\"א הנ\"ל וד\"ל) ומעתה יש להבין בפרטות ענין הנס דחנוכה והוא כמה שאמרו שטמאו העכו\"ם כל השמנים שבהיכל ולא נשאר רק פך א' שמן טהור חתום בחותמו של כה\"ג כו' ונעשה נס והדליקו ממנו ח' ימים אף שלא הי' בפך זה רק כדי הדלקת יום א' וידוע הקושיא דא\"כ יום הא' אינו נחשב מן הנס והנס הי' עיקרו ביום א' שהדליקו כו' דהנה ידוע ענין מה שטמאו העכו\"ם השמנים היינו בחי' חכמה דקליפת עכו\"ם שהוא חכמה הפלסופיא שמנגדת ומסתרת לאור החכמה האלקי' דקדושה שנק' שמן קדש כו' והיינו בחי' ראיה דחכמה הנ\"ל באמתת עצמות האלקות שלמעלה מן ההשגת שכל כו' וחכמת הפלסופיא היא לבא על החקירה בשכל אנושי הכוזב ומכחיש ומסתיר אור האמת שזהו בחי' פירוד היש וגסות השכל אנושי לעשות משכלו יש וגסות גמור היפך בחי' הביטול מעצמותו לגמרי כשהוא בבחי' ראי' דחכמה דקדושה הנ\"ל וזהו שטמאו כל השמנים דח\"ע דקדושה שבהיכל דבינה שהוא בחי' ההשגה והבנת שכל האלקי' שנק' היכל ובית להקיף ולכסות על נקודה די' דחכמ' כידוע בענין נקודא בהיכלי' וכענין ס\"ת בהיכל כו' כמ\"ש במ\"א וד\"ל (וזהו פי' היכל ה\"י כ\"ל נש\"ב דנק' כ\"ל שנמשכו מי' דחכמ' ונעשה בחי' בית והיכל להקיף ליו\"ד וע\"כ ה\"א קודם לי' שהי' בהעלם בה\"א ונגלה אח\"כ כמו היכל ה' המה כו' והוא בחי' נה\"ח דרחימו עילאה הנ\"ל שנמשך מי' דחכמה כנ\"ל) והשמן הי' גנוז ונעלם בהיכל ועכ\"ז טמאו העכו\"ם בחכמ' דקליפה אעפ\"י שבחכמה לא הי' שבירה כלל וכמ\"ש ימותו ולא בחכמה זהו בפנימיות חכמה אבל מה שמאיר מחכמ' לבינה יכולים להחשיך האור וזהו שהי' עיקר מגמתם רק להכחישם תורתם כו' שלא יאיר אור דתורה בגילוי):\n(יז) <b>והנה</b> זה היה עיקר הנס שמצאו פך א' שמן טהור חתום כו' ויש להבין למה כל השמנים שבהיכל טמאו העכו\"ם ופך א' זה שהי' חתום בחותם של כה\"ג לא טמאו כו' הענין הוא כידוע בשרש ענין כה\"ג וכהן סתם דכהן סתם הוא בבחי' החסד שלמטה מן החכמ' ושרש כה\"ג הוא בחסד שלמעלה מן החכמה שנק' רב חסד כמ\"ש בזהר וזהו ענין כה\"ג נוטל חלק בראש דחכמ' כו' ובחי' רב חסד זה הוא בי\"ג מדה\"ר שנמשך מעצמות א\"ס ב\"ה ע\"י כה\"ג דוקא כמ\"ש כשמן הטוב על הראש דכה\"ג יורד על הזקן דיקנא דכה\"ר כו' שהן שרש י\"ג מדה\"ר העליונים שיורדים ונמשכים למטה מטה כמ\"ש שיורד ע\"פ מדותיו והענין הוא לפי שיש בחי' חסד שבעצמות א\"ס ב\"ה שאין אתדל\"ת מגיע לשם כלל ונק' חפץ חסד והוא בחי' אה\"ר העצמית ממש כמו שאנו אומרים אה\"ר אהבתנו כו' אהבת עולם נצחיות דא\"ס ממש שהוא מעולם דא\"ס וכמ\"ש זכור רחמיך ה'"],[2201340086,"וחסדיך כי מעולם המה מעולם דא\"ס וכמ\"ש מעון אתה היית לנו כו' ומעולם ועד עולם כו' ובחי' רב חסד זה שבעצמות ממש הנה היא באה מאלי' וממילא מצד עצמה דוקא שלא ע\"י אתדל\"ת כלל רק שהיא כלולה בהעלם בבחי' שמן הטוב על הראש דכ\"ג שנק' שמן משחת קדש והוא בחי' התענוג הנעלם שבתעלומות חכמה שלמעלה מן אור החכמה ובאה לידי גלוי בי\"ג מדה\"ר בדיקנא דכה\"ר כו' וזהו יורד על הזקן כו' לסליחת העונו' ולעמוד נגד המקטריגים כו' שנק' ישועות כו' וזהו שמצאו פך א' שמן טהור חתום בחותמו של כה\"ג דוקא שבזה אין החצוני' יכולים ליגע שם כלל כי חותם זה דכה\"ג הוא חתום בבחי' העלם אחר העלם שבעצמות המאציל שלמעלה מכל ההשתלשלו' לגמרי והוא בחי' שמן הטוב שחתום הי' בחותמו של כה\"ג כו' מטעם הנ\"ל וד\"ל וזהו עיקר ענין הנס דחנוכה שהדליקו מפך זה ח' ימים והענין הוא כידוע דז' ימים הן ז' מדו' דבינה דאצילו' שכלולים בחכמה שמהם שרש כללות נ\"י שכלולים בז' נרות דמנורה ובהיות שבימי חשמונאי היו כנ\"י בגלות עכו\"ם בחשך גמור עד שרצו להשכיחם תורתך כנ\"ל לא הי' אתדל\"ת מועיל להאיר שרש נשמתם בז' ימים העליונים דחו\"ב שנק' או\"א כמו כי אתה אבינו כו' כ\"א ע\"י אתדל\"ע שמצד עצמות המאציל בבחי' רב חסד הנ\"ל שהוא בבחי' שמן הטוב כו' שהוא בהעלם ומקור דאור החכמה להיות משם גלוי האור העליון בז' נרות דנש\"י מעצמו כו' והוא הנק' אור ז' הימים אור כללי שכולל ז' ימים כא' והוא אור הגנוז לצדיקים מזימ\"ב והוא בבחי' העלם עצמות התענוג טרם שבא לגלוי בחכמה שנק' שמן הטוב שכל התפעלות המדות שברצון ותענוג (שנק' ז\"ת דע\"י וא\"א) כלולים כא' (עד\"מ התענוג עצמי והיולי שבעת שמחת לב אדם בעשותו משתה או ע\"י בשורה טובה מאד שיבא לכלל התפעלות מדות דחסד ורחמים בלי גבול ובלי התחלקות בפרט עדיין רק אח\"כ מתחלק לבא בגלוי בדרך פרט והוא בחי' ז' מדות דחכמה בבינה) וכך הי' בנס דחנוכה שהאיר בחי' רב חסד העליון שכולל התחלקות ז' המדות כא' ונתחלק לז' נרות הן כללות נש\"י להאירם בחשך כו' שלא ע\"י אתדל\"ת כלל ונמצא שעיקר הנס הי' ביום הא' דוקא שנק' אור ז' הימים שכלולים ביום זה (שנק' יום שכולו טוב) והז' ימים הן כפרט היוצא מן הכלל לבד וד\"ל. וזהו כי אתה נרי הוי\"ה וקאי על נס דחנוכה שהדליקו משמן טהור שהי' חתום כו' ח' ימים שהוא אור ז' הימים שהי' גנוז ונעלם ויצא לגלוי מעצמות א\"ס ב\"ה וז\"ש כי אתה ממש נרי ה' כו' וכן גם מ\"ש כי אתה תאיר נרי ה' אלקי יגיה חשכי קאי על העלאת נש\"י מכח עצמותו ית' שתאיר נרם כמו בהעלותך את הנרות שהוא ע\"י אהרן כה\"ר שנק' שושבינא דמט' כו' אך זהו ע\"י גלוי אה\"ר העליונה שמעורר לכנ\"י ומושך לבם לאביהם שבשמים כמו משכני כו' השיבנו כו' ואמנם בחנוכה הי' זה מבחי' העלם עצמות אור האה\"ר קודם שיצא לאור דחכמ' והוא מבחי' שמן הטוב שגנוז וסתום לע\"ל והוא עצמות פנימית חסד דע\"י שנק' אה\"ר בתענוג הפשוט כנ\"ל שגנוז בגלגלתא דא\"א וזהו כשמן הטוב על הראש דא\"א כו') והוא שבימי חשמונאי נתגלה זה האור הגנוז והדליקו ממנו ח' ימים והיינו לפי שמסרו נפשם ממש על התו\"מ כמ\"ש להשכיחם תורתך כו' ואתה עמדת להם בעת צרתם רבת כו' עד וזדים ביד עוסקי תורתך כו' ע\"כ זכו שיתגלה להם ממקור האור דתורה ומצות מעצמו שאין אתדל\"ת מגיע לשם כלל רק כי אתה כו' וזהו ולך עשית שם גדול כמ\"ש טוב שם משמן הטוב שעל הראש וכמ\"ש במשיח ישכיל עבדי כו' שהוא כתר שם טוב שלמעלה מכתר כהונה וכתר מל' שע\"י שמן הטוב על הראש הנ\"ל כו' וד\"ל:\n(יח) <b>וזהו</b> וה' יגיה חשכי פי' וה' בתוספ' וי\"ו מפני שהוא כפל הדבר להזכיר"],[2201340087,"שם הוי\"ה בפ\"ע על מה שיגיה חשכי וכל וי\"ו הוא מחבר כידוע והיינו לחבר ב' הויו' הללו כא' בלי הפסק ביניהן כלל והענין הוא משום דבי\"ג מדה\"ר נז' ב\"פ הוי\"ה בפסיק טעמא בגוייהו כמ\"ש ויקרא ה' ה' אל רחום וחנון ופסיק טעמא בין ב' הויות הללו כידוע וע\"כ אמר כאן וה' בוי\"ו המחבר לחבר ב' ההויות יחד היפך פסיק טעמא שבין ב' הויות די\"ג מדה\"ר כו' וביאור זה הנה יש להקדים ענין מה שלפעמים מקדים חנון ורחום לה' כמ\"ש דוד חנון ורחום ה' ולפעמים מקדים ה' לרחום וחנון כמו בי\"ג מדה\"ר שא' ה' אל רחום וחנון כו' כי הנה ידוע דעצמות אא\"ס ממש למעלה מכל מדה וספי' וכמ\"ש ולאו מכל אינון מדות כלל גם למעלה מרצון ותענוג וכמו שאו' יהי רצון כו' וא\"כ כדי שיבא לכלל מדות דרחום וחנון גם במדות עליונות שברצון ותענוג הוצרך להיות ע\"י שם הוי\"ה תחילה שהן ד' אותיות י' צמצום וה' התפשטות ויו המשכה וה\"א התפשטות שע\"י ד' אותיות אלה בא דילוג האור להיות בבחי' מקור למדות שברצון כמו להיות רחום וחנון וארך אפים וכה\"ג והוא שם הוי\"ה הב' שבי\"ג מדה\"ר שלפני אל רחום כו' ומה שא' חנון ורחום ה' היינו כדי שיבא לכלל צמצום והתפשטות כו' שהוא שם הוי\"ה הנה לזה עצמו צריך שיתעורר תחלה בעצמות רק מצד עצמו כי חפץ חסד הוא בעצמותו ונק' רחום וחנון בעצם שמחמת זה יבא לכלל שם הוי\"ה בצמצום והתפשטות כו' להיות מקור למדות דרחום וחנון שברצון ותענוג (כמו שאנו או' יהי רצון מלפניך כו' הרי צריך לבקש שיומשך א\"ס ברצון וזהו ויהי רצון לפניו והיינו ממדות דרחום וחנון שבעצמות א\"ס ממש שעי\"ז יבא להיות גם בחי' אל רחום וחנון ברצון וה\"ז דילוג האור ביותר כידוע וד\"ל) וזהו שמקדים לפעמים רחום וחנון לה' להיות שם הוי\"ה גם ברצון העליון שהוא בחי' א\"א דאצילות מקור לע\"ס דאצילות (וכידוע שבחי' הכתר נק' ממוצע בין עצמות המאציל לנאצלים וכל ממוצע כלול מבחי' האחרונה שבמאציל וכתר וראש לנאצלים וכפי הכלל הידוע בכל השפעה מעליון לתחתון הרי מבחי' מל' שבעליון נעשה כתר לתחתון ואמצעי זה כולל בעצמו מבחי' מל' שבעליון וכתר לתחתון והיינו ענין ב\"פ הוי\"ה שבי\"ג מדה\"ר הא' בחי' אחרונה שבעצמות והב' כתר וראש לנאצלים והוא בחי' א\"א וע\"י שפנימי' ע\"י וא\"א מאיר שם ממל' דא\"ס בכלל והוא ג\"ר דע\"י בכלל ובחי' ז\"ת דע\"י שמלוב' בג\"ר דא\"א כמו חו\"ג דע\"י שבגלגלתא דא\"א וח\"ס כו' הוא שרש וראש לנאצלים כו') וזהו דפסיק טעמא בין ב' הויות די\"ג מדה\"ר לפי שאין ערוך כלל בין כתר דאצילות למל' דא\"ס שבפנימית ע\"י וא\"א בכללות ששם אין אתדל\"ת מגיע כלל לפי שהוא ית' עצמו נק' מלך מרומם לבד בחי' יחיד שמתנשא מימות עולם דהיינו נשגב ומתנשא מז\"ת דע\"י כו' הנק' ימ\"ע דאצילות כו' אעפ\"י שאינו רק בחי' האחרונה שבעצמות א\"ס ב\"ה שנק' מלך אבל זהו מל' דא\"ס עצמו קודם הצמצום דקו\"ח כו' וזהו מלך יחיד חי העולמים שכדי שיהי' חי העולמים דאבי\"ע בבחי' קו\"ח כו' הוא מלך יחיד תחילה ולפעמים אומר יחיד חי העולמים מלך שכדי שיאיר מל' דא\"ס בנאצלים הוצרך להיות באתדל\"ע מצד עצמו להיות משפיל א\"ע להיות מלך כמו ה' מלך גאות לבש כו' שאינו רק לבוש חיצוני לפי שאין ערוך כלל להתנשאות דמלך על כל העולמות דאבי\"ע לגבי בחי' התנשאות שמצד עצמו ממש ועכ\"ז א' מלכותך ממש מל' כ\"ע וכמו לע\"ל שאנו אומרים גלה כבוד מלכותך עלינו כו' וזהו ויקרא ה' ה' כו' שקרא והמשיך מהוי' הא' שבהעלם עצמות המאציל שיבא לכלל גילוי שם הוי\"ה הב' להיות מקור לנאצלים והיינו להיות אל רחום וחנון ברצון וחכמה כנ\"ל וקריאה והמשכה זו היה מצד אתדל\"ע שמצד עצמו בלבד כי אין אתדל\"ת גם יח\"ע דע\"ס דאצילות מגיע לשם כלל מטעם הנ\"ל שהוא מלך מרומם לבדו מתנשא מימ\"ע"],[2201340088,"דאצילות כו' ולכך פסיק טעמא בגווייהו כנ\"ל אך כאן א' וה' יגיה חשכי וי\"ו זה הוא המחבר ב' הויות הללו בלי הפסק ביניהן כלל כנ\"ל והענין הוא דמ\"ש כי אתה נרי הוי\"ה היינו בחי' הוי\"ה הב' די\"ג מדה\"ר שהוא מקור הי\"ג מדות הרחמים שהרי מה שא' אתה נרי הוי\"ה היינו להיות מקור האור העליון להאיר בז' נרות דכנ\"י עד שיוכל לבא האור למטה בנש\"י בגופים ממש וכמ\"ש כי אתה תאיר נרי ה' כו' כנ\"ל שבהכרח שיבא האור ע\"י בחי' ההשתלשלות באבי\"ע עד עוה\"ז השפל להאיר גם בחשך דק\"נ כו' שנק' נה\"א שהוא חיבור האור בפתיל' ממש כנ\"ל:\n(יט) <b>והנה</b> גוון האור הנאחז בפתילה שחור הוא ואינו נק' אור המאיר כלל אדרבה הוא נק' אשא אוכמא נהורא אוכמא לפי שמשתנה גוונו לפי מהות דבר המכלה ושורף כנ\"ל אך הנה מבואר למעלה בשרש כליון הפתילה שהוא נה\"ט למעלה מאור האלקי' דנשמה כו' א\"כ גם באש שחור זה שרשו הוא למעלה מאור העליון עד שבכחו להמשיך את האור העליון הלבן הנקרא אור המאיר ממילא ומאליו וכמו שאנו רואים שאש התחתון הכבוי בפתילה כאשר יעמידוהו תחת אור הדולק ימשכהו אליו כו' לפי שיש שרש לאש זה השחור למעלה מן האור המאיר והוא בבחי' אויר דק שנק' אויר חשוך שמשם מקור מוצא מציאת האור המאיר והוא בחי' החשך שהוא ההעלם שקודם לאור כמ\"ש והארץ היתה תהו וחשך כו' ואח\"כ א' יהי אור ויבדל בין האור והחשך ויקרא לאור יום ולחשך קרא לילה כו' אבל קודם שהבדיל היה החשך קודם לאור וכמ\"ש יוצר אור ובורא חשך הרי חשך בבריאה שקודם ליצירה והוא מ\"ש ישת חשך סתרו וגם למטה כברייתו של עולם ברישא חשוכא כו' שהוא בחי' העלם העצמות שקודם לגילוי האור בקו\"ח כו' וע\"כ בהכרח שאש זה השחור שרשו בחשך והעלם מקור האור דלזה בכחו להמשיכו וזהו מטעם הנ\"ל בכליון הפתילה ששרשו בז' מלכים דתהו שנק' חשך העליון שקדם לאור החכמה דתיקון שמשם אור הוי\"ה דנשמ' וכתיב כיתרון האור מן החשך דהיינו כאשר עצם החשך עצמו יאיר יש בו יתרון אור רב הרבה בכפלי כפליים לאין שיעור מעצם בחי' אור המאיר שיצא אחר ההעלם דחשך העליון וגם אחר שהבדיל בין האור וחשך וקרא לאור יום ולחשך קרא לילה שהוא החשך גמור אבל שרש זה החשך דלילה הוא בחשך העליון (שנק' אויר דק וחשוך כנ\"ל) וההפרש הוא בין אור דחכמה שנק' אור המאיר הנ\"ל שהוא אינו מאיר בלילה שלא יוכל להאיר את החשך רק כמו שגם אור הנר שמדליק בלילה אינו מאיר רק במקומו אבל החשך במקומו עומד וכך הוא ענין נה\"ח שמאיר באור הנר דנשמה משא\"כ כאשר החשך עצמו יאיר הוא בא בוודאי ממקור האור שלמעלה מן האור דחכמה אשר ע\"כ גם בחשך דלילה יאיר כמו ביום וכמ\"ש ולילה כיום יאיר וכמו ויהי הענן והחשך ויאר את הלילה כו' שהוא מבחי' העלם העצמות שנק' מאור ששם נא' וגם חשך לא יחשיך ממך כחשכה כאורה כו' וזהו שרש אש השחור שבפתילה שהוא למעלה מנה\"ח ע\"כ בכחו להמשיכו אליו כו' וכך יובן למעלה בכללות ההשתלשלות דקו\"ח שנק' אור המאיר בכללות שנמשך בשם הוי\"ה באבי\"ע עד נשמות בגופי' בעוה\"ז להאיר את החשך שהוא חיבור האור בפתילה כנ\"ל שע\"ז אמר כי אתה נרי הוי\"ה כו' והוא הוי\"ה הב' שבי\"ג מדה\"ר שנמשך לאבי\"ע בגילוי מבחי' ההעלם דהוי\"ה הא' שע\"ז א' ויקרא ה' ה' דפסיק טעמא בגווייהו כו' מטעם שאין ערך לגילוי אור המאיר לגבי בחי' ההעלם שבעצמות אעפ\"י שהוא בחי' ה' אחרונ' שנקרא מל' דא\"ס כנ\"ל אך זהו דוקא כאשר האור דקו\"ח בא אחר הצמצום דחשך סתרו וכמו מאצי' לבריאה דברישא חשוכא כו' אבל כאשר בחי' העלם העצמות ממש מאיר שזהו גבוה הרבה"],[2201340089,"יותר מאור המאיר דקו\"ח כנ\"ל וע\"כ מאיר גם בחשך דלילה כמו ביום ממש משום דהחשך עצמו יש בו יתרון אור רב כו' כנ\"ל אז אין הפסק כלל בין ב' הויות הנ\"ל דהעלם וגלוי מאחר שההעלם עצמו בא לגילוי משום דקמי' כחשכה כאורה כו' ואז א' ולילה כיום יאיר כו' (וזהו גילוי האור דעצמות א\"ס ב\"ה ממש שלפני החשך העליון שגם החשך העליון מאיר כאור כו' לעת ערב יהי' אור כו' שזה האור שמאיר בלילה ודאי גדול מאור היום כמ\"ש שיש יתרון האור מן החשך עצמו כשמאיר מטעם הנ\"ל עד שנכלל בו אור המאיר כי יש בכלל מאתים מנה וד\"ל וזהו וה' יגיה חשכי וה' בתוס' וי\"ו לחבר ב' הויות הללו יחד ולא עוד אלא להוסיף אור גדול בהויה דאור המאיר שא' תחלה כי אתה נרי הוי\"ה כו' ע\"י וי\"ו זה המחבר כו' היפך הפסק הטעמים שבין ב' הויות די\"ג מדה\"ר הנ\"ל והענין הוא כנ\"ל דהעכו\"ם טמאו כל השמנים שבהיכל שהוא אור חכמה שבתורה הנגלית כמ\"ש להשכיחם תורתיך כו' ומצאו שמן טהור שמן הטוב שהוא פנימית ומקור האור דח\"ע כמו שהוא בעצמות א\"ס ב\"ה שנק' אור ז' הימים שנגנז לצדיקים לע\"ל וע\"כ הדליקו ממנו ח' ימים כנ\"ל והעיקר הוא מה שהדליקו נרות בחצרות קדשך כו' שזהו מה שהחשך עצמו מאיר שהוא יתרון אור גדול מאור דחכמ' ע\"כ מזה המשיכו במקור האור דתורה להיות תור' אור בגילוי רב יותר מעצם אור המאיר כו' וזהו עיקר ענין מצות נ\"ח להיות החשך דלילה מאיר מצד עצמו ששרשו בחשך העליון שלמעל' מן האור המאיר דחכמ' וכנ\"ל בשרש אש השחור כו' וד\"ל וביאור הענין לפי שבימי חשמונאי' נפלו כנ\"י בתחתית המדריגה שא\"א הי' שיאיר להם מבחי' אור המאיר דחכמ' ע\"כ גברו העכו\"ם להשכיחם תורתך כו' וכמו שאנו רואים בעקבות משיחא בדור האחרון שתערוב' טו\"ר יותר הרבה מדורות הראשונים דגם שהיו בהם רשעים גדולים אבל צדיקים שבהן היו צדיקים באמת קרובים לנבואה ורה\"ק כו' כי הטוב נבדל לגמרי מן הרע ע\"כ היו אז צד\"ג ורשעים גדולים משא\"כ בדורות האחרונים אין צד\"ג ולא רשעים גמורים כ\"כ כו' מצד שבחי' הטו\"ר מעורבים לפי שבכל דור מתברר עה\"ד טו\"ר ודורות הראשונים הי' בערך הראש לגבי הגוף וע\"כ נק' נשמות שבדור האחרון בשם עקבות משיחא כמו אשר חרפו עקבות משיחך והענין הוא דנשמות הגבוהות כחם חזק מאד לגבור על הגוף שתומ\"י שיתבונן בגדולת ה' יגבור כח הדביקות אלקי' להפוך חומריות הגוף גם הוא לה' לבדו כו' כביטול היש לאין וזהו אור המאיר שנק' נה\"ח שמדליק בפתילה כנ\"ל אבל נשמות השפלות מאד שבעקבות משיחא אעפ\"י שמתפעלים בדביקות אלקית אין בהן כח להפוך חומריות הגוף כלל וכלל גם אחר כל השגות אלקות בהתפעלות רב לא יזיזו טבעיות הגוף כלל ונשאר הגסות והחומריות במקומה בשלימות ולא יכלה באור האלקי כלל ודוד הי' מרכבה לבחי' מל' ראה בבחי' נשמות שבעקביים שהן בבחי' חשך גמור דק\"נ מובלע ברע דנה\"ט שלא יועיל להן אור האלקי דנה\"ח להאירם רק הרי יש כאן כליון פתילה באש השחור והוא התשובה שמהפך חשוכא עצמו לנהורא שזהו החשך מצד עצמו מאיר שהוא בהיפוך הרע עצמו לטוב ע\"י תשובה אמתית כו' ע\"כ א' וה' יגיה חשכי חשך גמור דקליפה הגסה יגיה אור שתאיר הרבה יותר מאור דנה\"ח שבצ\"ג שא' כי אתה נרי ה' כו' מטעם הנ\"ל באש השחור כו' וז\"ש וה' בתוס' וי\"ו המחבר להמשיך מחשך העליון תוס' אור גדול הרבה מאשר נר הוי\"ה מאיר אחר ההעלם דחשך וע\"כ אין הפסק בכאן אדרבה מחבר מאור הגדול דחשך סתרו להוסיף אור בשם הוי\"ה הראשון והוא מ\"ש יגיה חשכי עד\"מ מקשת הנראה בו ג' גוונין דשמש בהבהקה יתירה הרבה יותר מגוף הג' גווני אור הללו בשמש עצמו כו' וכמ\"ש במ\"א בענין מראה הקשת הוא מראה הנוגה"],[2201340090,"כו' והוא מ\"ש בר\"מ ואני שלשת החצים צדה אורה שהם ג' גווני קשת נהירין ביומוהי דמלכא משיחא דוקא ע\"י תשובה דוקא והיינו בחי' כתר ש\"ט שלמעלה גם מאור העליון דשמן הטוב כו' וז\"ש וגבה מאד וזהו כתנות אור בא אחר היפוך החשך דק\"נ לאור דוקא ע\"י התשובה מטעם הנ\"ל וד\"ל:\n(א) <b>כי</b> עמך מקור חיים באורך נראה אור. יש לדקדק למה א' כי עמך הל\"ל כי אתה מקור דלנוכח קא' כמו כי אתה נרי כו' ומהו לשון עמך שהוא לשון טפל ובטל היינו שבחי' מקור חיים עמך בטל כטפל לגבי העיקר ועוד מה שייך רישא דקרא עם סיפא שא' באורך נראה אור דמה ענין חיים עם אור ואם הכוונה דכמו בחיים גם המקור חיים בטל לגבי עצמותו ית' כך גם האור המתפשט בעולמות בטל לגבי אורך העצמי והיינו באורך נראה אור בחי' הארה בעלמא דכלא חשיבי ממש א\"כ מהו לשון נראה אור הל\"ל עמך החיים והאור וכמו דכתיב באור פני מלך חיים דמה שהוא ית' מחי' את כולם מאין ליש נק' אלקים חיים היינו מקור כל החיים והוא אור פני מלך חיים כו' והנה בפי' נראה אור יש ב' משמעות א' נראה אור מתוך האור לשון נפעל בחי' אור של תולדה כמו אור הנכפל או כמו המראה שרואין מתוכה שאין זה האור רק הארה דהארה ולא עצם האור כלל וכמו האור שרואין דרך מסך שהאור בא בשינוי המהות ועכ\"ז פי' נראה אור היינו שנראה ממילא לכל רואה רק שהוא בא מן האור העצמי בבחי' הארה דהארה (שהוא הנק' ווידער שיין) שהוא האור הנראה מתוך האור שזהו לשון נראה אור והוא הנק' אספקלריא דלא נהרא כידוע בענין הנבואה דכתיב ה' במראה אליו אתודע כו' והוא דמות כבוד הוי' שאינו אור העצמי שנק' אורך רק האור הנראה מתוך אורו ית' כמו במראה וע\"י מסך וכה\"ג וזהו שאמרו כל הנביאים נתנבאו בכה בכף הדמיון ומשה נתנבא בזה לנוכח שנבואת משה הי' מבחי' אור הוי\"ה העצמי שנק' אספקלריא דנהרא וכמ\"ש פא\"פ אדבר בו במראה ולא בחידות כו'. והמשמעות הב' בל' נראה אור נראה זה קאי עלינו שאנחנו נראה אור מתוך אורו ית' כמו כי עין בעין נראה בשוב כו' והיינו שא' באורך העצמי נראה גם אנחנו את האור ולפ\"ז הכונה היא דוקא על האור העצמי דבאורך העצמי נראה גם אנחנו האור הזה שבעצמו ולא עוד אלא שנראה אור גדול ביתרון אור רב וגדול והכונה כך הוא שבאמצעות אורך נראה אור ביתרון גדול שלא היה נראה כלל אור גדול כזה ולא יראה אור הגדול מתוך אורך רק אנחנו נראה אור זה וד\"ל. ולהבין זה איך אפשר שנראה אנחנו האור ממש שזהו למעלה גם מנבואת משה שראה דרך אספקלריא עכ\"פ כמ\"ש במראה ולא בחידות רק שנק' אספקלריא דנהרא כנ\"ל והנה יש להקדים לזה ענין מנורת זכרי' דכתיב בה וגולה על ראשה וז' נרותי' עליה שבעה ושבעה מוצקות לנרות אשר על ראשה כו' דהנה ידוע שכנ\"י נמשלה למנורה דוקא ויש להבין למה למנורה דוקא בהיות ידוע דנש\"י נק' נר הוי\"ה כי חלק הוי' עמו כו' ונק' ניצוץ ואור אלקי ממש והן ז' נרות המנורה שכלולים בה כללות נש\"י בבחי' ז' מדות עליונות דאצילות והטעם שנק' בשם נר כי הנר הוא בחי' הכלי לאור שבה יאיר האור כך כל נשמה ונשמה יש לה כלי להשראת אור האלקי שבה יאיר אורה ובכלל הן ז' נרות המנורה ולכך נמשלה כנ\"י למנורה של זהב כמו המנורה שהיא כלי להשראת אור וצריך להדליק האור בנרות המנורה ע\"י שמן ואור ולא תאיר אור מעצמה ובעתי' מיוחדים כך נש\"י מצד בחי' ירידתם למטה בכלי חומר גופם לא יאיר אור אלקי שבהם מעצמ' כ\"א לעתים מיוחדים שיאיר בהן אור האלקי כמו במנור' בהטיבו את הנרות בבקר וערב ומדליקן הכה\"ג כמ\"ש בהעלות אהרן את הנרות כו':\n(ב) <b>ויש</b> להבין ביאור הענין ומהו השמן והאור ולמה הן במספר ז' דוקא דהנה"],[2201340091,"אנו רואים בכל אדם מישראל שלפעמים תתתלהב נפשו האלקי' מעצמה ומאלי' לעלות אל ה' ברוח התעוררות גדולה וחזקה בהתעוררות תשובה או בהתעוררות אהבה ותשוקה גדולה לידבק בה' ולילך בדרכיו ומצותיו או בהתעוררו' יראה ופחד אלקי' בלבו להיות סור מרע בתכלית וכה\"ג ויש בזה שינויי אופנים לפעמים מתעורר ברוח טהרה לטהר לבו בתשובה ע\"י מרירות הלב ולפעמים מתעורר ברוח קדושה לידבק במצותיו בשמחה וטוב לבב ולפעמים רק בניצוח והסכם חזק מאד כו' ולפעמים רק בהודאה מרחוק כו' וכל אלה באים בלבו פתאום מצד עצם ומהות אור הנשמה שמתעוררת רק מעצמה ומאלי' מבלי שהכין לבו לזה באיזה יגיעה ועבודה כלל וכלל ובנקל באו לו התעוררו' רבות כאלה כאלו מעוררי' אותו מלמעל' שזהו רק ענין גלוי ההעל' מצד עצמו כי בהעלם ומקיף יש בכח הנשמה מצד עצמה כל אלה המצו' אוי\"ר ותשובה וכה\"ג רק שהמה בהעלם ויוצאים לגלוי אור לפרקים מאליהם שלא ע\"י יגיעה ועבודה כלל ולפעמים אנו רואים שגם ברוב יגיעה ועבודה רבה שאדם מתייגע למצוא התעוררות אוי\"ר ותשובה לא יבא בגלוי אור התפעלות בלבו כלל וכלל מפני שנשאר בהעלם בנפשו ולא יוכלו לבא לגלוי כלל והיינו מצד חומר הגופני שהוא מסך מבדיל לבלתי יאיר אור ורוח האלקי בגלוי כלל רק נשאר בהעלם גדול מאד ולא שאבד תקוה לנפשו לעולם שהרי לעתים רחוקים יתעורר בתשובה אמתי' ויבא ההעלם לגלוי כמו בעי\"ת שכל איש מישראל מתעורר בתשובה שלימה וגם הקלי קלים ההולכים בשרירות לבבם רק רע באין פחד אלקים בלבם כלל יתעוררו בעי\"ת בבכי' רבה שלא ע\"י הכנה ולא לפי ערך מעשיהם כלל כידוע וגם אנו רואים שיש בכח כל איש מישראל גם קל שבקלים למסה\"נ על קדה\"ש כאשר יכריחו אותו לעבור על דתו מפני שאז יצא כח הקדושה האלקי' שבנפשו מן ההעלם לגלוי מפני שהיא כמו טבע בנפשו האלקי' ממש רק שהוא בבחי' מקיף והעלם גדול ויוצא לגלוי לעתים רחוקים או לפעמים ע\"י מצוה גדולה שעשה להחיות נפש עני ומדוכא וכה\"ג עבור זה יזכו אותו להאיר אור נשמתו מן ההעלם לגלוי בכל מעשה הטוב ובהתעוררות אוי\"ר ותשובה כי ב\"ק מכרזת בכ\"י שובו בנים שובבים רק שאין איש מתעורר מרוח ב\"ק זה המעורר למעלה מפני מחיצה של ברזל המפסקת והוא מ\"ש עונותיכם מבדילים כו' כידוע ועכ\"פ מזה מובן שבבחי' מקיף ובהעלם ודאי יש בכח בכל נשמה האלקי' כל אור האלקי השורה בתמידות עלי' בלי גרעון כלל וכלל וד\"ל (וכמ\"ש במ\"א שז\"ש כולך יפה רעייתי ומום אין בך ומ\"ש מכף רגל ועד ראש אין בו מתום היינו באמצעות חבור אור הנשמה בחומר הגוף שהטומאה בעוונות המבדילים בראש ורגל כו') וזהו שארז\"ל דאכל עשרה שכינתא שריא ומשמע גם על עשרה רשעים שעוונותיהם מבדילים כו' מ\"מ שכינה שורה בתפלתם שנק' עדה משא\"כ ביחיד אפי' הוא צדיק גמור לפי שנש\"י בצלם אדם העליון שכלול מע\"ס וכשהן עשרה שכינה עליונה שורה עליהם בבחי' מקיף עכ\"פ מטעם הנ\"ל שבבחי' מקיף דנשמתם אור האלקי שורה עליהם בתמידות וזהו אכל עשרה שזה על כל בבחי' מקיף דוקא וד\"ל:\n(ג) <b>והנה</b> סיבת המונעים לבא גלוי אור מן ההעלם ומקיף שבנש\"י שאינו מאיר את המדות אוי\"ר ותשובה כ\"כ לעתים קרובים וגם לא יועיל היגיעה ועבודה לפעמי' כנ\"ל היינו מפני העדר השמן והאור כמו במשל המנורה שאעפ\"י שהנרות מוכנים ועומדים אם אין שמן ואור לא יאירו כלל היינו שלא יאירו אור המדות הטובות שבנשמה האלקית שבלתי יתעוררו מעצמם בלי שמן וזהו ושמן על ראשך אל יחסר וקאי על אור המקיף דנשמה שעל ראשו שלא יחסר בו שמן כדי להאיר מן ההעלם לגלוי והיינו בחי' כח מ\"ה דחכמ' שבנשמה"],[2201340092,"בחי' הביטול לאין האלקי בעצם שכאשר מאיר מן ההעלם לגלוי הוא הכח ועוז שיש בכאו\"א מישראל למס\"נ על קדה\"ש ולשוב בתשובה שלימה כידוע ובחי' שמן זה הוא המביא וממשיך לבחי' האור האלקי שיאיר בכל נשמה ונצוץ האלקי וכמ\"ש במ\"א ע\"פ ויקחו אליך שמן למאור מאור דוקא שממשיך כל אור כו' וד\"ל והנה הטעם שהי' המנורה של זהב דוקא כי הנה ידוע שהזהב מורה על בחי' הגבור' שהוא בחי' רשפי אש התשוק' בחמימות ההתפעלו' והענין הוא דהגם שז' הנרות הן ז' מדות הטובות שיהיו מאירין בכי טוב מן ההעלם כנ\"ל ואמנם גם לשמן ואור א\"א להביאם לגלוי אור מן ההעלם כ\"א בהקדים תחלה קצת התעוררות בנפש שיהי' חפץ ומשתוקק להיות לו קרבת אלקי' בדביקות ואוי\"ר שזהו הכנת לבו וחפצו ותשוקתו לזה להתקרב אל ה' באוי\"ר ולא ילך אחר ההבל כו' הגם שאין בלבו התפעלות אוי\"ר עדיין כלל אך גודל תשוקתו בלבו שיגיע קירוב ודיבוק זה באלקי' חיים שאנו רואים שיש תשוקה זו בכל איש מישראל יהי' מי שיהי' שיהי' קרוב אל ה' תמיד ונק' רצון לרצון היינו שרוצה שיהי' לו רצון ואהבה אמתית לה' כו' וזהו שאנו מבקשים ויחד לבבינו לאהבה וליראה את שמך פי' יחוד הלב היינו שיהי' הלב חושק ומתאוה לחפוץ בקרבת אלקים באוי\"ר הרי ודאי יש בזה תשוקה ברשפי אש ממש ובלתי זה לא יתפעל באוי\"ר כי תשוקה זו היא דרך כלל רק שחושק ומתאוה לקרבת אלקים חיים וכמו ואותי יום יום ידרשון וקרבת אלקים יחפצון שנק' דרישה וחפיצה וכמו הכין לבבו לדרוש אלקי' שהכונה שיחפוץ ויחשוק בזה בכלל עכ\"פ ואז יבא ויגיע לאור התפעלות אוי\"ר בלב בדביקות והתקשרו' עוז ואנו רואים בחוש שבלתי זה לא יעלה ויבא לשום התפעלו' בלב כלל אפילו לאהבה הנמשך כמים שבאה בבחי' הקרירות שהוא רק שנמשך בהמשכת הלב לבד (הנקרא קלעפ) דהנה גם באהבה זו הנמשכת כמים בקרירות אם אין קודם לה החשק והתשוקה לזה אין בה אור וחיות כלל ומיד יפול מזה לגמרי והוא בחי' הקרירות העצומה בלא חיות כלל עד שכמת יחשב (הנק' קאלטקייט וטוטקייט) וע\"ז נאמר לא המתים יהללו יה כי ההלל ליה הוא הארת האור כמו יהל אור בהלו נרו וכאשר הוא בקרירות גדולה רק מן השפה לחוץ בפיו ושפתו לבד יכבד בשבח והילול זה בהעדר אור וחיות לגמרי נק' נשמה זו בשם מתים כמו מיתת הגוף בלא חיות וד\"ל וכ\"ש וק\"ו בהתפעלות האהבה שהיא באה ברשפי אש כמ\"ש רשפי' רשפי אש שלהבת יה שלהובי דרחימותא בחמימות ההתפעלות בצמאון הלב מאד כמ\"ש צמאה לך נפשי כו' וכן נכספה וגם כלתה נפשי כו' הנה ודאי לא תבא כ\"א בהקדים תחלה בחי' התשוקה וחשק לחפוץ בזה כנ\"ל וכך הוא בכל מדה ומדה מז' המדות הטובות א\"א שיתעוררו כ\"א בהקדים התעוררות בנפש מבחי' הגבורות שהוא קצת התלהבות וחשק שיחשוק בלב להיות לו אוי\"ר וכל מדה טובה וכמו גם למדת הניצוח והסכם החזק בעבודת ה' צריך שיהי' חושק ומתאוה לזה שיהיה לבו חזק בעבודת ה' ודרך כלל נק' התעוררות זו בחי' הגבורות שהוא בחי' העלאה כללית ובלעדה לא תעלה הנשמה ולא תבא לכלל התפעלות המדות כלל עד שגם לאהבה הנמשך כמים שהיא מבחי' החסדים מוכרח שיהיה בה קצת תשוקה וחשק לזה וזהו אשר קרך בדרך ויזנב בך כל הנחשלים שבלתי העלאה הנ\"ל נק' קרירות בהעדר כל חיות אלקי שכמת יחשב ברוחניות:\n(ד) <b>וזהו</b> ענין המנורה בכללה שהיתה של זהב טהור כי הז' נרות הן ז' מדות הטובות העולות לה' באור וחיות גדול כמו התפעלות אוי\"ר וכה\"ג אך התעוררות וחשק לקרבת אלקים כנ\"ל צריך להיות תחילה ע\"כ היתה המנורה של זהב בכללותה כדי שיוכלו הז' מדות בז' נרות להאיר וע\"כ היו הז' נרות של"],[2201340093,"זהב דוקא ואעפ\"י שבתוך הז' מדות יש מדות החסד שהיא האהבה הנמשך כמים בקרירות גם היא היתה של זהב מטעם הנ\"ל שגם בה מוכרח שיהיה קצת חשק ותשוקה ברשפי אש ואם לאו לא תתקיים כלל וכך הוא בכל המדות שבלתי תערובות של בחי' הזהב בהם כנ\"ל הרי אין בהם אור וחיות כלל ויכבו אורם מיד עד שכמתים יחשבו כנ\"ל ולא יועיל להם בחי' השמן והאור כלל וכמ\"ש לא המתים יהללו י\"ה הן אותן נשמות וניצוצות שנק' מתים מצד עוצם הקרירות בלתי התעוררות ותשוקה לקרבת אלקים כלל וד\"ל וזהו מקשה תעשה המנורה כו' שכללות נש\"י הרי המה כלולים בז' נרות המנורה שהיא בחי' הכלי לאור האלקי המאיר בכללות נש\"י בתמידות למעלה בבחי' ההעלם ומקיף וכמ\"ש כי אתה נרי הוי\"ה כו' וצריך שיהיה עיקר בנינה מבחי' הגבורות שהוא מעלת הזהב על הכסף והוא בחי' רשפי אש התשוקה בכלל בקרבת אלקים ולהיות כי כל ישראל ערבים זה בזה ע\"כ מקשה אחת היתה ובה כלולים כל הנשמות מיריכה עד נרותיה והן פרטי כל הכלים לאורות שנעשים בסדר והדרגה מיריכה עד פרחה כו' וכמ\"ש ככר זהב טהור יעשה אותה את כל הכלים האלה וד\"ל:\n(ה) <b>והנה</b> המנורה שבבהמ\"ק היה כה\"ג מדליק נרותי' בקר וערב וכמ\"ש בהעלותך את הנרות והיינו בחי' אה\"ר עליונה שמעורר לנש\"י ומדליק אורם ומעלה אותם לשרשם אל מול פני כו' אבל בזמן הגלות אין אור אה\"ר דכה\"ג העליון מגיע ונמשך למטה מטה כ\"כ במקום נפילת ניצוצות הקדושה דנש\"י שנק' סוכת דוד הנופלת לשון הוה שנופלת בירידה אחר ירידה כו' וכמו שנראה בעליל שאין הכרוז דב\"ק מעורר לשום נשמה מישראל לשוב בתשובה שלימה בכל יום ואם האור דאה\"ר היה נמשך גם למטה מטה הרי א' משכני אחריך נרוצה וכן השיבנו ה' אליך ואשובה כידוע המשל במי שבאה\"ר שלו לחבירו או לבנו יעורר וימשוך את לבבו אליו בהתעוררות רבה כו' שזהו עיקר ענין הדלקת נרות הנשמות כמ\"ש במ\"א וד\"ל אך מנורת זכריה הוא שראה בזמן הגלות דאעפ\"י שנאמר לא יכבה בלילה נרה כו' וקאי בכנ\"י בזמן הגלות שנק' לילה אור האלקי מאיר בנש\"י שנק' מנורת זהב בכל ז' נרותיה אבל הרי זה רק בבחי' העלם ומקיף על הנשמות ולא בגילוי אור ממש בתוך תוכם כמו בזמן בהמ\"ק וזהו שראה גולה על ראשה וז' מוצקות להציק השמן לז' הנרות היינו שיש בחי' אתדל\"ע מצד עצמות אלקות להאיר ולהמשיך בנש\"י הנק' ז' נרות גם בזמן הגלות והוא ענין הגולה והז' וז' מוצקות וכמשי\"ת ב\"ה וד\"ל:\n(ו) <b>אך</b> הנה יש להקדים מ\"ש המגביהי לשבת המשפילי לראות בשמים ובארץ. ויש להבין בלשון מגביהי ומשפילי דמשמע מזה שיש לפניו ית' בחי' מעלה ומטה דמגביהי לשבת היינו בחי' מעלה ומשפילי לראות הוא בחי' מטה וא\"א לומר שזהו מעלה ומטה גשמיים שנופל בגדר מקום שהרי הוא ית' למעלה מגדר מקום לגמרי כמו שארז\"ל הוא מקומו ש\"ע ואין העולם מקומו וכמ\"ש הנה מקום אתי כו' וא\"א לומר בו ית' שיושב למעל' ומשפיל א\"ע למטה כי הרי הוא שורה בעליונים ותחתונים בשוה ממש וסיפא דקרא מוכיח שא' משפילי לראות בשמים וארץ ושמים למעלה וארץ למטה כמ\"ש שמים לרום וארץ לעומק ומשפיל לראות בשמים וארץ בשוה וכמ\"ש הלא את השמים ואת הארץ אני מלא בשו' אלא צריך לומר דמגביהי ומשפילי זה אין זה בבחי' מעלה ומטה בגשמיות אלא בבחי' מעלה ומטה ברוחניות (ולא ברוחניות דהשתלשלות העולמות כמו ד' עולמות אצילות בי\"ע שהאצילות נק' מעלה ברוחניות ובי\"ע מטה ברוחניות שזהו ענין שמים וארץ ברוחניות הרי א' דשמים וארץ אני מלא בהשוואה א' ממש ועוד דהיינו בחי' מעלה ומטה עכ\"פ אלא גם בשרש ומקור כל העולמות שזהו"],[2201340094,"בחי' הקו\"ח שהוא נמשך רק בשביל שיהיה בחי' מעלה ומטה מראשית הקו\"ח עד סופו בעשי' הנה גם זה יקרא בחי' מעלה ומטה עכ\"פ אלא בחי' מעלה ומטה ברוחניות היינו בעצמות אא\"ס ממש גם קודם שעלה ברצונו להאציל כו' שמה שהוא בבחי' עילוי אחר עילוי בעצמותו עד אין שיעור למעלה מעלה הנה זהו הנק' בחי' מעלה וזהו פי' המגביהי לשבת פי' מגביהי ביוד שמוגבה ומרומם לבדו בעילוי והסתלקות האור בעצמותו באין שיעור לעילוי אחר עילוי ברום המעלות עד שאין כל צמצום דקו\"ח עד סוף העשי' תופס מקום כלל וכלל עד שנופל לשון שכחה על כל ההשתלשלות ונצרך לזכרון שיזכירוהו ע\"ז כמו בי\"פ דזכרונות כידוע ומבואר במ\"א שזהו כמשל המתעסק בעלמא באיזה ציור שאעפ\"י שרושם פעולתו ניתן בו מ\"מ אין זה רק חצונית דחצוניות כח התנועה שבידו וגם זה הרי היה כמתעסק בידו בעלמא שלא היה בו כונת לבו כלל מפני טרדתו העמוקה וכה\"ג שבודאי יפול בזה הציור שכחה לגמרי מכל וכל עד שיזכירוהו כו' וכך הוא בחי' הצמצום הראשון שנק' מק\"פ שהוא כמו הרושם בעלמא כמא' בריש הורמנא דמלכא גליף גליפו בטה\"ע שחקיקה וגליפה זו היא רק כמו רושם בעלמא ביד המתעסק בידיו וכה\"ג וד\"ל:\n(ז) <b>וזהו</b> המגביהי לשבת כשמגביהי לשבת במכון שבתו בעצמותו ממש שזהו בבחי' הסתלקות בעילוי אחר עילוי לאין שיעור למעלה מעל' וכידוע דעצמות אא\"ס ממש למעלה מעלה עד אין שיעור ולמטה מטה עד אין תכלית כו' והיינו בחי' מעלה ומטה הרוחניי' שבבחי' העצמות ממש וזהו המגביהי לשבת למעלה מעלה עד אין שיעור כלל ומשפילי לראות למטה מטה עד אין תכלית כלל וב' הענינים דמעלה ומטה מגביהי ומשפילי כו' הכל בא מכח העצמות ממש רק שזהו בבחי' העליה וההסתלקות בעצמותו וזה בבחי' הירידה והתפשטות למט' מטה עד אין תכלית וע\"כ אמר המשפילי לראות בשמים וארץ בשוה לפי שכח זה של הירידה וההתפשטות באה מכח העצמות ג\"כ ע\"כ משפילי לראות בשמים וארץ בשוה ממש וד\"ל. ובזה יתורץ דאין הסיפא סותר לרישא דקרא דאדרבה מוסיף טעם וביאור דהנה באמת הכונה הפשוטה במקרא זה דמגביהי ומשפילי היינו גם בשעה שמגביהי לשבת למעלה מעלה בעצמותו ממש אז הוא משפילי לראות בשמים וארץ ואין זה שפלות ויריד' כלל כי לגבי עצמותו ממש אין זה בחי' מעלה ומטה כלל וכלל מאחר שאין כל מקור של ההשתלשלות מראשו לסופו תופס מקום כלל וכלל כנ\"ל וגם מצד עצם אמתתו הרי מה שמגביהי לשבת באין שיעור למעלה וגם מה שמתפשט למטה מטה עד כו' שוין לפניו ממש כו' כי הכל מכח א' באו והוא ית' כל יכול לסבול ב' המדרגות דמעלה ומטה הללו שבבחי' הרוחניות הנמשכים מעצמותו ממש שניהם כא' ממש מטעם שגם מה שמגביהי לשבת ומשפילי לראות שזהו ממש אא\"ס למעלה עד כו' ולמטה כו' אין זה ערך כלל וכלל לגבי אמיתת עצמותו ממש שלמעלה מבחי' העלי' והיריד' כמ\"ש במ\"א וד\"ל וזשארז\"ל במקו' גדולתו שם דוקא אתה מוצא ענותנותו דגדולה הוא בחי' ההתנשאות שבעצמותו עד אין שיעור למעלה וענוה הוא בחי' ירידת אא\"ס למטה כו' ובמקום גדולתו כמ\"ש המגביהי לשבת משם דוקא הוא משפילי לראות בשמים וארץ משום דהיינו הך והכל מכח אחדות הפשוט' בא רק שזה כחו בעלי' וזה כחו בירידה כנ\"ל וד\"ל:\n(ח) <b>והנה</b> יש עוד פי' במגביהי לשבת המשפילי לראות כו' דלראות היינו להתגלו' ולהתראו' כחו וגדולתו בשמי' וארץ והיינו בחי' ההשתלשלות דע\"ס דאבי\"ע כו' והיינו פי' המשפילי לראות דכל זה הגילוי אור שמתגלה בע\"ס דאבי\"ע הוא בחי' שפלות וירידה גדולה אצלו ומהיכן הוא משפילי לראות דוקא"],[2201340095,"כאשר מגביהי לשבת כו' ויובן זה בהקדים תחלה בשרש ענין הע\"ס דאבי\"ע שהן נקראים בשם שמים וארץ בכלל דהנה פי' שמים מים הוא בחי' החכמה עצמה והשין הוא ג' גוונין דחכמה וביאור הענין ידוע שזהו ענין ג' מדרגות שבחכמה שנקרא אמ\"ר אור מים רקיע כי כאשר החכמה מאין באה היינו מ\"ש יהי אור וכאשר נמשך האור דחכמה מאין נקרא מים שזהו בחי' חסדים והוא בחי' התפשטות החכמה בגילוי להיות במציאת שכל וחכמה ונקרא חכמה בה\"א וכאשר החכמה נתפס בבחי' יש גמור כמים שנגלדו ונקרא רקיע הוא כשמתפשט במדות דוקא והוא השי\"ן שמורה ג' קוין דחכמה חג\"ת כנ\"ל בענין נטיות שבשכל לחו\"ג כו' משא\"כ בעוד החכמה בבחי' עיון שכלי בלתי נוטה עדיין לפסק דין או חסד וכו' וזהו פי' שמים שי\"ן מים ג' גוונין שבחכמה כו' וזהו בראשית בחכמה ברא השמים הוא בחי' ירידות אור החכמה במדות ג' גוונין חג\"ת דחכמה ואח\"כ את הארץ שהוא בחי' המל' דכתיב והוכן בחסד כסא (וכמ\"ש חסד ה' מלאה הארץ וא' באתרה שקיע רחמי כו' וחסד זה לברוא הארץ הוא סוף ירידת השפע מן החכמה שהוא מאמר דבראשית וכמ\"ש ה' בחכמה יסד ארץ דאבא יסד ברתא אך כל זה שנמשך וירד אור החכמה והחסד בשפלות וירידה גדולה כזו שהן ע\"ס דאבי\"ע בכלל היינו מ\"ש המשפילי לראות בשמים וארץ ששפלות זו באה מצד שהוא מגביהי לשבת דוקא שבמקום גדולתו כו' כנ\"ל וכמ\"ש אנת חכים ולא בחכמה ידיעא דמה שנקרא חכים הוא ע\"י צמצום העצמות להקרות בשם חכים להיות מקור למקור למציאת חכמה בבי\"ע וכן חסדן ורחמן כו' רק לאחזאה לאתנהגא בהון עלמין אבל מצד עצמו לאו מכל אינון מדות כלל וגם מה שנתצמצם להיות בבחי' מקור לחכמה וחסד באבי\"ע אין ערוך כלל לחסד הנאצל והנברא כו' לגבי עצמות המאציל עד שנחשב כערך דומם דדומם לגבי השכל וזהו עושה בראשית דמאמר דבראשית דחכמה נק' בחי' עשיה ממש:\n(ט) <b>ויובן</b> זה ממה שאנו רואים גם בסדר השתלשלות דאבי\"ע איך שאין ערך לחסד דבריאה לגבי חסד דאצילות כמו שמצינו במדרגת חסד דאברהם אע\"ה שהי' מרכבה לבחי' חסד דאצילות כידוע ע\"פ ואנכי עפר ואפר שזה אמ' על שרש ומקור מדרגתו למעלה שהי' מרכבה לשם להיות שהי' בחי' אהבה דאברהם כלא חשיב ממש ואינה עולה בשם כלל לגבי אור אהבה עליונה שבמדת חסד דאצילות שהיה מרכבה לשם וגם כי רוח אייתי רוח ואמשיך רוח ומאחר שהי' נקרא אברהם אוהבי רחימא דמלכא הרי בבחי' העלאת מ\"ן שלו באהבתו הנפלא' ועוצם דביקות שבנפשו לאלקים חיים שהוא בחי' המל' ודאי היה ממשיך אור העליון מאצי' לבריאה כמים הפנים לפנים מבחי' אהבה עליונה אליו כמו אהבת איש לרעהו דאהבת רעהו נמשך אליו כמים הפנים לפנים כן לב האדם לאדם מ\"מ מפני שאין ערוך כלל בין בריאה לאצילות לא שייך לומר כך ואעפ\"י שנקרא אוהבי רחימא דמלכא זהו רק כמו בחי' מרכב' לגבי הרוכב וכפני אריה אל הימין למעלה לגבי האדם שעל הכסא כו' וזהו בבחי' מל' דאצילות שנקרא מרכבה תתאה אבל בעלות נשמתו בהעלאת מ\"ן בהתעוררות רוחו באה\"ר למעל' יותר היינו בבחי' חסד דז\"א דאצילות אז אמ' ע\"ע ואנכי עפר ואפר שהוא עד\"מ הידוע מעץ הנשרף שד' יסודות ארמ\"ע שבו כלין והולכים והיינו בחי' הרוחניות דיסודות שכלי' והולכים בעשן היוצא שכלול מארמ\"ע כו' ולאחר כלות השריפה נשאר האפר שהוא גשמי והוא יסוד העפר הגשמי שנשאר מיסוד העפר הרוחני שבעץ שהי' רוחני וכערך הגשם אל הרוחני כך ערך האפר הגשמי אל היסוד העפר הרוחני שהי' כלול בעץ קודם שנשרף והי' לאפר וכך יובן הנמשל שאור אהבה דאברהם שנשמתו מעולם הבריאה בבחי' יש מאין הי' בערך אפר גשמי"],[2201340096,"שנשאר מיסוד עפר שבעץ הרוחני אחר שנשרף כך מה שנשאר אחר צמצום כל אור האצילות ולא נשאר רק התכלית הנמוך שבמדריגת אהבה דשם שנבדל להיות בבחי' דומם כאפר הוא שרש נשמת אברהם וע\"כ קרא עצמו בב' שמות אלה עפר ואפר לגבי אור חסד דאצילות וד\"ל (ובאמת עפר ואפר ב' הפכים הן עפר ביסוד המים ואפר ביסוד האש מ\"מ נכללים בשם א' להיותן בחי' דומם עכ\"פ ואפר הנשאר מעפר שבעץ נקרא דומם שבדומם ויובן זה בעבודת ה' באהבה שבלב שהיא בקרירות ונמשך כמים עד שלא נשאר רק ההסכם מזה למעשה שהוא בחי' דומם כעפר בבחי' שפלות ובלא חיות כלל ובאהבה כרשפי אש כשנסתלק האור וחיות ונשאר רק בחי' דומם כאפר הנשאר מעץ הנשרף כו' וידוע שהמדות נקרא בשם צומח ובחי' דומם שבו היינו עפר ואפר כו':\n(י) <b>והנה</b> עד\"ז יובן למעלה באור חסד עליון שאין ערוך כלל לחסד דבריאה לגבי אור חסד דאצילות עד שנחשב רק כמו בחי' דומם עפר שבעץ דצומח כשנשרף והי' לאפר כנ\"ל שנקרא דומם שבדומם כו' וע\"ד דוגמא הנה מה שאנו רואים ההפרש בין אור חסד עליון שבא ברוחניות בג\"ע העליון דבריאה לנשמות ומלאכים דבריאה בין חסד גשמי שבא ונמשך למטה מטה כמו בעוה\"ז השפל שזן את העולם כולו בחסד כו' שהוא פרנסה גשמיית שבודאי אין ערוך כלל וכלל בין זה לזה שזה תכלית הרוחני וזה תכלית הגשמי ומ\"מ עפ\"י ריבוי ההשתלשלות יומשך מחסד עליון הרוחני להיות מציאת חסד הגשמי בפ\"מ וכמ\"ש נותן לחם לכל בשר כל\"ח הרי חסדו העליון הרוחני נמשך מאצילות לבריאה לג\"ע ויורד ונמשך עד חסד דעשיה בפ\"מ וכן בהיפוך כאשר מדת הדין גובר נמשך מאצילות לבי\"ע כמו בר\"ה וכה\"ג וכמ\"ש בזהר דאית יומין ידיען לעילא שנק' יומין דטוב כו' ואמנם כ\"ז נמשך בדילוג הערך מאד מחסד עליון דאצילות כו' והוא כמו משל הנ\"ל מבחי' דומם שבדומם דאפר שנשאר מן העץ הנשרף כמ\"ש אברהם על שרש נשמתו ואנכי כו' ואעפ\"כ הרי באתדל\"ת אתעדל\"ע שבמעשה החסד וצדקה שעושין למטה איש עם רעהו מעוררים למעלה בחי' אור ח\"ע דאצילות שיומשך לבי\"ע כמ\"ש יהי חסדך כו' וכתיב לך אדני החסד כי אתה תשלם לאיש כמעשהו דוקא ולהיפוך במדת הדין מעוררים למעלה מדה\"ד וראי' מאנשי סדום ולהיפוך מאנשי נינוה וכו' וכן באברהם איש החסד בפ\"מ שעשה עם הכל גם עם ערביים ולרעים כמו לטובים הי' מרכבה לעורר למעלה בחי' אור ח\"ע דאצילות להיות נמשך מאצילות לבריאה כו' והטעם הוא מצד שעצמות המאציל גם שמושלל מכל בחי' תואר מדה וספי' כמ\"ש לאו מכל אינון מדות כלל מ\"מ צמצם עצמו להיות נקרא חכים כו' כנ\"ל וכן במדת החסד כמ\"ש כי אמרתי עולם חסד יבנה והוא באור ח\"ע דאצי' שמלובש בכלי שנקרא תקונא דרועא ימינא וכמ\"ש אף ידי יסדה ארץ וימיני כו' רק בשביל להשפיע לעולמות כמ\"ש לאחזאה לאתנהגא בהון עלמין סתימין כו' וכמו שאין ערוך בין חכמה וחסד דבריאה לגבי חכמה וחסד דאצילות יותר אין ערוך כלל בין חכמה וחסד דאצילות לגבי עצמות המאציל עד שגם בחי' חכמה או חסד דאצילות נקרא בחי' עשי' בחי' דומם שבדומם לגבי עצמות המאציל כנ\"ל בפי' עושה בראשית כו' רק שאין לצייר ולהבין איכות ההבדלה בערך בזה לפי שהאצילות בכלל נאצל מעצם אורו ואיהו וחיוהי חד ממש וגם איהו וגרמוהי חד ממש כמו שלהבת הקשורה בגחלת כו' ועכ\"ז נקרא ע\"ס בלי מה בלי מהות כלל משום דמצד עצמו לאו מכל אינון מדות כלל וכלל וכמ\"ש אנת חכים ולא בחכ' ידיעא כו' ולאו מכל כו' וכמ\"ש במ\"א שצמצום הראשון הנק' מק\"פ וחלל כו' הוא יותר בבחי' ההעלם שנק' חשך סתרו מבחי' הצמצום האחרון שבין אצילות לבריאה שנק' מסך כו' ועכ\"ז הרי"],[2201340097,"או' ראו כי אני אני הוא אני ראשון בבחי' הצמצום הראשון ואני אחרון בבחי' צמצום האחרון כו' וד\"ל משום דכל זה הגילוי אור שבאבי\"ע הוא בא בבחי' שפלות וירידה גדולה באין הפרש כלל לגבי העצמות ממש וד\"ל:\n(יא) <b>וזהו</b> המשפילי לראות בשמים כו' כי כאשר מגביהי לשבת בעילוי אחר עילוי בעצמותו ית' הוא הגבה למעלה מהיות מקור לחכ' וחסד דאצי' ע\"כ נקרא צמצום זה להיות נקרא חכים כו' בשם שפלות ויריד' גדולה וזהו המשפילי לראות בשמים ששמים שין מים חכמה וג' קוין וזהו פי' הפשוט במשפילי שיורד ונשפל לברוא ולהאציל שמים עליונים שהוא בחי' חכמה עילאה וכו' אך לפי זה לא יתכן מה שאמר לראות בשמים ויש בתיבת לראות שני פי' א' לראות בהשגחה פרטי' כפשוטו וכמו משמים הביט ה' ראה כו' שזהו השגחה מן השמים בכל הארץ אבל לפעמים א' השמים שמים לה' והארץ כו' ע\"ז או' גם בשמים הוא משגיח כמו בארץ וזהו לראות בשמים ובארץ בהשגחה כללית בשמים ובארץ בשוה שזהו בחי' שפלות וירידה ג\"כ כו' והענין הוא כידוע בבחי' ב' דעות ד\"ע וד\"ת שכמו דקמי' כלא כלא חשיבא יבא אור ההשגחה לכל ההשתלשלות דאבי\"ע שהן שמים וארץ בכלל בדרך שפלות וצמצום גדול וזהו נק' מחשב' אחת שצופה ומביט הכל בסקירה א' כידוע וזהו בחי' ד\"ע ובחי' ד\"ת היינו בחי' ההשגחה פרטי' בכל אשר בשמים ובארץ וכל צבאם בדרך פרט דוקא כמ\"ש ממכון שבתו השגיח כו' וכן עיניך פקוחות כו' ועיני ה' משוטטות בכל הארץ וכה\"ג בשמים העליונים יורד ונשפל לראות ולהשגיח כמו שיורד בארץ כי שניהם שוין לפניו וז\"ש המשפילי לראות בשמים וארץ אע\"פ שמגביה לשבת כו' וד\"ל (ומ\"ש השקיפה ממעון קדשך מן השמים וברך כו' השקפה זו בבחי' פנימי' ועצמית היא שזהו ע\"י התגלות פנימית שלו ע\"י השמים עצמן כמשי\"ת) והנה יש עוד פי' בלראות זה שהוא להראות ולהתגלות ע\"י השמים שהשמים העליונים הן בחי' כלי ומסך שעי\"ז יוכל לירד ולהשפיל להתגלות אורו גם למטה מטה בארץ ביתרון אור הרבה יותר וזהו לראות בשמים ע\"י השמים שהן כמו המראה שנקרא אספקלריא דנהרא שהדבר הנרא' במראה נראה יותר בגודל והתפשטות רב ויותר מובהק לעין הרואה וכן המים הנראים בזכוכית בהירה נראי' יותר מובהקים (וכך השמים העליונים נק' טהירו עילאה כמו כעצם השמים לטהר כו') לפי שהרואה במראה מכוון ומצמצם את אור הראי' ע\"כ תרחיב ותתפשט אור הראי' לראות את דבר הנראה לעין בגלוי רב ביותר התרחבות ויותר בהבהקה (וראי' לזה מכלי האצטרלוב שרואים בו הכוכבים הרחוקים והגבוהים ביותר לפי שמקרב את דבר הרחוק להגדילו בעין הרואה בכפלי כפליים לאין שיעור כמ\"ש בס' החקירה) וכל זה משל אמתי לענין השמים העליונים שעל ידם דוקא יהי' סיבה גדולה ליתרון גלוי האור העליון שהוא גלוי אלקות ביותר שבא יבא למטה מטה שז\"ש המשפילי לראות בשפלות גדולה ע\"י שמים דוקא:\n(יב) <b>וביאור</b> הענין הנה יש להקדים לזה ענין א' והוא במ\"ש רם על כל גוים ה' שהוא רם ומתנשא עליהם בעילוי רב וגדול עד שאינם תופסים מקום כלל וכלל לפי ששרש הע' שרים של מעלה מקבלים רק מבחי' אחוריים וחיצוניות דשם אלקי' שהוא במ\"ח צירופים האחרונים לבד שנק' אדמת בני חם כמ\"ש ומופתים בארץ חם כידוע וגם שם נא' מלך אלקי' על גוים שבחי' מלכותו בכל משלה ונק' שם בשם מלך הגוים וכמ\"ש מי לא יראך מלך הגוים כו' וכתיב יראו מה' כל הארץ ולפעמי' הע' שרים בתכלית הביטול ואו' שירה וכמ\"ש הללו את ה' כל גוים כו' וכתיב כל העמים תקעו כף הריעו לאלקי' וכן הבו לה' משפחות עמים וכה\"ג אך לפעמים הן בבחי' הפירוד ויש ודבר בפ\"ע"],[2201340098,"עד שלפרקים יכולים למרוד כו' וזהו מבחי' התערובות טו\"ר שבק\"נ למטה וכמו שר של מצרים שא' לי יאורי כו' וכמ\"ש פרעה מי ה' כו' וכן סנחרב וכה\"ג ולהיות ידוע ששרש היניקה דע' שרים הן רק מבחי' הפסולת דאופנים שנק' שמרי האופני' כידוע ע\"כ אין תופסי' מקום כלל וכלל (וראי' מי' מכות שבמצרים ממה דכתי' ויסר את אופן מרכבותיו כו' כמ\"ש במ\"א) וכמ\"ש יפקוד ה' על צבא המרום במרום ועל מלכי האדמה כו' והן הכו\"מ שמרומם ומשפיל כרצונו וכמ\"ש וכמצביי' עביד בחיל שמיא כו' וזהו דוקא כאשר יורד ומתצמצ' להשגיח על כל פרטי פרטיות שביושבי הארץ כמ\"ש ממכון שבתו השגיח על כל יושבי הארץ וכמהפכת סדום ועמורה וכמו כי לא שלם עון האמורי כו' וכן במצרים שא' וידע אלקים אבל מה שא' רם על כל גוים ה' היינו כאשר הוא ית' בבחי' ההתנשאות והרוממו' בעצמותו בעילוי אחר עילוי שאז אין העולם מקומו כלל כו' וכמו אלכה אשובה אל מקומי העצמי כי אין הארץ וכל אשר בה רק בחי' הדום רגלי השכינה וכמ\"ש השמים כסאי והארץ הדום רגלי כו' וכמו שא' מי כה' אלקינו המגביהי לשבת כו' שאין כל ההשתלשלות תופס מקום כלל כנ\"ל ואז גם כשהע' שרים הן בבחי' פירוד גמור והשכינה בגלות עם ישראל כמו בגלות מצרים וגם בהיות גוים מרקדים בהיכלו כששרפו הבהמ\"ק ושלחו יד במקדשו אין כל זה תופס מקום כלל וכלל להיות לו לפגם כבודו מצד העדר תפיסת מקום לגמרי וכמשל השממית וקורי עכביש שבהיכל מלך שאם תגביה ותרחיב מכון שבתה בקרקעית רצפת היכל המלך הרי ודאי לא ישים לב איש ממשרתי המלך ע\"ז כלל וכלל וכמ\"ש שממית בידים תתפש והיא בהיכלי מלך כו' שהשממית נתפס ביד לזורקה חוץ בקל ועכ\"ז הולכת בהיכל מלך ומגבהת רום ישיבתה בקורה ובקרקע וגם לפעמי' תלך על מטת משכב המלך ולא ירגיש בזה שום העדר כבוד או צער מצד העדר תפיסת מקום לגמרי וכך הנמשל מזה הרבה יותר בערך נבדל שאין לשער הכל כפי הידוע באמת בסדר ההשתלשלו' דאבי\"ע מה תופס מקום כל שרש יניקת הע' שרים שהוא רק בבחי' אחוריים דשם אלקי' דמל' דמל' דעשי' הנופל בבחי' פסולת דפסולת למטה כו' וכמו ששחק ר\"ע על כרך גדול של רומי שמלא תענוגי עוה\"ז שאין זה רק פסולת דפסולת שנופל מעונג האלקי שבחיצוניות דחיצוניות דג\"ע דעשיה ע\"כ אם לעוברי רצונו כך כו' וגם על מה שראו שועל יוצא מהיכל ק\"ק כו' והיינו מה שארז\"ל על אנשי כה\"ג שאמרו הגבור הן הן גבורותיו שגוים מרקדי' בהיכלו והוא שותק וכן מ\"ש אין כמוך באלמים כו' פי' הן הן גבורותיו דוקא דהיינו מצד בחי' עוצם ההתנשאו' והסתלקות בעילוי אחר עלוי בעצמותו שאז כל ההשתלשלות אינו תופס מקום כלל וכלל אז גם מה שגוים מרקדים בהיכלו הוא שותק ויושב בשמים ישחק להם כי כלא חשיבא ממש וכמשל שממית הנ\"ל והרבה יותר מזה וע\"כ מזה מופת וראי' לעוצם גבורותיו וכמ\"ש מי כה' אלקינו המגביהי לשבת כו' וד\"ל:\n(יג) <b>אך</b> הנה עכ\"ז אומר המגביהי לשבת משפילי לראות דגם בשעה שמגביהי לשבת במכון שבתו בעילוי אחר עילוי לאין שיעור בעצמותו ממש מ\"מ גם אז הוא ית' יורד מעוצם בחי' הרוממות שלו ומשפילי לראות בירידה ושפלות גדולה בירידה אחר ירידה עד אין שיעור למטה מטה בכל פרטי השגח' גם בדצ\"ח הגשמיי' גם למצוא טרף למזונם וכמ\"ש נותן לחם לכ\"ב כל\"ח וחס ומרחם על כל מעשיו וכמו על נינוה העיר הגדולה כאשר נתכסו בשקים האדם והבהמה חס עליהם מאד וא' ליונה הנביא איך לא אחוס על י\"ב רבוא אדם ובהמה רבה הרי חסים על הבהמה וכן מצינו בקי\"ס שגם שמצרים טבעו בים חס עליהם וא' מעשה ידי טובעים בים ואתם אומרים שירה לפני וכה\"ג ומקרא"],[2201340099,"מפורש ורחמיו על כל מעשיו אין זאת כ\"א מצד שכאשר הוא ית' המרומם על כל ההשתלשלות כאשר משפיל עצמו גם זה בא ונמשך עד אין תכלית למטה מטה להיות יודע ומרגיש בצער ברואיו מפני שהן כח מעשיו עכ\"פ הגם שזהו רק מחיצוניות דחיצוניות כח הפועל אלקי שבמל' דמל' דעשי' בצירופי' היותר אחרונים וכו' וזהו שארז\"ל שי\"ב שעות הוי היום עד שג\"ש האחרונים יושב וזן כל העולם כו' וד\"ל והנה לפי המשל הנ\"ל בשממית וכה\"ג גם בזה יש להבין שיש בזה ב' אופנים הא' כאשר המלך הוא טרוד ברוממות עצמותו בעניינים רמים לא ירגיש בדברים קטני הערך מאד מאד כמו בהילוך שממית ומעשה קורי עכביש בהיכלו וכה\"ג ולא ירגיש במעשים מכוערים של פחותי הערך מעבדיו הקטנים כשפחה ועבד שאחר הרחיים וכה\"ג אבל כאשר לב המלך פנוי מכל עסקיו הרוממי' ומשים לבו ודעתו להשכיל גם בענינים קטנים שבחיצוניות דחיצוניות להשגיח גם עליהם מפני שמשפיל א\"ע ביותר כאיש פשוט רש ונקלה כו' הנה אז ודאי נהפוך הוא שמדקדק ביותר גם על אשר כלא חשיבא ממש כמו השממית והזבוב ומצוה לזרוק אותם חוץ וירגז על כל אשר אין כדאי לדבר בזה ויקפיד ביותר על כל מכעיסיו גם בדבר קטן שבקטני' כו' וכללו' ענין זה הוא כמו המשל באדם בשינה והקצה דבשינה ודאי כשאדם ישן שכלו ומחשבתו מסתלקי' בעצמו' נפשו וגם לבו ומדותיו וגם כל כחות חיצוניו' שבגופו ולא נשאר בגופו רק המעט חיות המתצמצם מפנימיות הכחות והוא חיצוניות החיות הנשאר בלב מרוח החיים לצורך כחות החיצוניות שהן תנועה והרגשה בלבד כידוע ואז ודאי לא ירגיש בשום דבר המנגד לרצונו ושכלו ומדותיו וגם כאשר זבוב ושממית יהלכון בגופו לא ירגיש כלל ומכ\"ש כאשר נמצאו בביתו והיכלו שלא כפי רצונו כו' אך בהקיצו משינתו נהפוך הוא לגמרי מפני שכל כחות נפשו הפנימיי' כמו הרצון והשכל ומדות ירדו מן העצמות להאיר בכלי מוחו ולבו כו' הנה אז ירגיש דוקא בכל אשר נגד רצונו ושכלו ומדותיו וגם ירגיש בכל דברים קטנים כמו הזבוב והשממית להבריחם ויקפיד על כל אשר בקצה ביתו כמו במעש' העבד ושפחה שאחר הרחיים וכה\"ג ונמצא מובן מכל אלה המשלים עכ\"פ מכוון א' כי בעת רוממות העצמות לא ירגיש כלל גם בדבר גדול שבגדולים ובעת ירידתו ושפלותו מן העצמות ירגיש גם בדבר קטן שבקטנים וכמו במשל השינה שעולה הכל בעצמות או במשל הטרדה בעמקות רוממות עצמותו אז יהיה בהעדר ההרגשה מכל וכל רק בדבר הנוגע לעצמותו ממש אבל בעת ירידתו בשפלות מעצמותו כמו בהקיצו מן השינה שיורדי' כחות העצמיים בכלי גופו ישגיח גם בכל פחותי הענינים ולהרגיש גם בדקות ההרגשה בפעולות פרטי פרטיות ולעיין היטב בכל פרט גם בענין פחות הערך מאד וד\"ל:\n(יד) <b>והנמשל</b> מכל זה יובן למעלה בענין הנ\"ל במגביהי לשבת המשפילי לראות כו' שיש בזה ב' מדרגות הא' כאשר הוא ית' מרומם ונשגב לבדו בעילוי העצמות שע\"ז א' הן הן גבורותיו כנ\"ל וכן אמרו אין כמוך באלמים ל' אלם הרי הוא כמו השותק כאילו א\"י לדבר ובאמת אין שתיקתו רק מצד עוצם הגבורה שבלבו ודעתו שכובש רוחו ומתאפק ושותק לשונאו כו' וכל מה שהוא גבור יותר יותר יוכל לשתוק ולסבול מעשה השונא משא\"כ כשאינו גבור בלבו ודעתו כ\"כ לא יוכל לסבול ולמשול ברוחו וישלם לשונאו אל פניו כו' וכך הוא מה שאמרו להודיע כמה ארך אפים לפניו שמאריך אף לרשעים וכמ\"ש טוב ארך אפים מגבור שהארך אפי' אין זה רק רוב גבורת הלב להאריך אפו ולשתוק שאין זה בכח הגבור בגבורתו כלל וכמ\"כ למעלה כמה ארך אפים לפניו ברוב גבורותיו שהוא בבחי' א\"ס ע\"כ מאריך אפו כ\"כ וכמו דורו של אנוש עד"],[2201340100,"כל הדורות שניזונין בחסדו והן עוברי רצונו וכו' והיינו אין כמוך באלמים והוא ענין א' עם משלים הנ\"ל בשינה או טרדא עמוקה כו' שכל זה היינו רק מצד עוצם העילוי בעצמותו שאין כל ההשתלשלות תופס מקום כלל כנ\"ל ע\"כ נק' ארך אפים להאריך אף כ\"כ שגם שגוים מרקדים בהיכלו הוא שותק וסובל והן הן גבורותיו וד\"ל ואמנם הגם שהן הן גבורותיו מצד עצם הרוממות שאין לו שיעור למעלה וכמ\"ש המגביהי לשבת כנ\"ל אבל יש אופן שני שבהיפוך ממש שמשפילי לראות בשמים כו' והיינו כמו שאו' עורה למה תישן ה' כו' וכן ויקץ כישן ה' שהוא עד\"מ אדם המקיץ מן השינה שיורד שכלו במוחו ומדותיו בלבו אזי ירגיש בכל אשר יעשו נגד רצונו גם בדבר הקטן שבקטנים כמו גם בזבוב ושממית שבבית לבלתי תלך בשולחנו ומטתו וכה\"ג ידקדק גם עם עבדו ושפחתו כחוט השערה גם בדקות כו' והנמשל מזה יובן למעלה דהגלות נק' שינה וכאשר נתעורר מן השינה כמ\"ש עורה למה תישן ה' אז יורד ונשפל מן עצמותו להאיר בחכמ' ומדות דאצילות בבי\"ע עד סוף העשי' להיות מרגיש ומשגיח גם במעש' הע' שרים דנוגה דעשי' לדקדק עמהם כחוט השערה כמ\"ש המבין אל כל מעשיהם ואינו רם ומתנשא על הגוים אדרבה יורד ומתצמצם ביריד' ושפלות גדולה להשגיח על כל אשר עושים לנגד רצונו ובפרט במה שמצירים לישראל עמו חבל נחלתו שזהו כאלו נוגעי' בבבת עינו כבי' כמ\"ש יצרנהו כאישון עינו כו' היפך השתיקה והסבלנות מטעם הנ\"ל וד\"ל:\n(טו) <b>אך</b> הנה סיבת הירידה והשפלות הנ\"ל היינו רק ע\"י אתדל\"ת דכנ\"י בתו\"מ שנק' בשם רמ\"ח אברים דמלכא כמו שאברי הגוף הכל כלים מכלים שונים לגלוי אור וחיות הנפש באופני' שונים כמו השפעת החסד ביד שהחסד הוא אור וחיות מדה שנטועה בעצם הנפש ובאה לגלוי אור בכלי היד דוקא וע\"י הצדקה וחסד שעושין ישראל למטה באתדל\"ת זו נעשה אתדל\"ע להיות מאיר אור חסד עליון שבעצמות המאציל לבא בבחי' כלי והוא כמ\"ש אתקריאת בתיקונא דא חסד דרועא ימינא כו' להיות זן את העולם בחסד בעולמות הרוחניים עד עוה\"ז השפל שזן ומפרנס לכל והיינו רק ע\"י אמצעי' ריבוי הכלים דחסד עליון וכה\"ג בכל המצות מעשיות הן רק בחי' כלים לעורר אתעדל\"ע להיות נמשך האורות דע\"ס בכלים מכלים שונים וע\"כ נק' המצות רמ\"ח אברים דמלכא כידוע וז\"ש אשר קדשנו במצותיו מצותיו דוקא מצות שלו כמו שידוע שהקב\"ה מניח תפילין ומתעטף בציצית וכו' וכמ\"ש אם במצותי תשמעו וכן באברהם א' וישמור מצותי כו' היינו ג\"כ ע\"ד הנ\"ל שאור העצמות יורד ונמשך בחכמה ובינה דאצילות ע\"י התפילין שמניח כידוע דד' בתים דתפילין הן ד' מוחי' במקיפים ופנימי' וכן בל\"ב חוטין דציצית נמשך בחי' ל\"ב נ\"ח במקיף ופנימי וכך הוא ענין כל המצות עליונות שנק' מצותי וזהו אשר קדשנו ג\"כ במצותיו להיות יחוד וחיבור או\"כ ע\"י מצות שלנו כמו במצותיו ממש וד\"ל (ולפ\"ז לכאורה נהפוך הוא שלא ע\"י אתדל\"ת נעשה אתדל\"ע אלא קדשנו במצותיו שנק' רמ\"ח אברים דמלכא דהיינו בחי' או\"כ מקיפים ופנימים שכבר נאצלו מעצמות המאציל וכמו אברהם קיים כל המצות עליונות היינו כל היח\"ע באו\"כ ע\"י העובדות שלו וכמו יעקב במקלות עשה יח\"ע שבמצות תפילין כידוע ועכ\"ז א' ושמי הוי\"ה לא נודעתי להם רק ע\"י מ\"ת ומצות מעשיות שישראל עושין בגשמיות דוקא הענין הוא כידוע שכל השתלשלות דע\"ס או\"כ מקיפים ופנימי' הכל נמשך ע\"י מאמ' קו המדה במדה וקצבה בקו\"ח שהוא מקור כל האו\"פ ומקיפים וגם ע\"י ריבוי מסכים והעלמות שבין עליון לתחתון שאם הי' מאיר אור מעליון לתחתון ביתר מכפי המדה דקו המדה הנ\"ל הי' כל עלול מתבטל בעילתו ומכ\"ש אופני היחודים והתכללות זע\"ז"],[2201340101,"כחו\"ג וחו\"ב כו' הכל בא במדה דוקא כמו מי מדד בשעלו מים כו' כמ\"ש במ\"א וזה הי' עפ\"י העלאת מ\"ן דאבות הן המרכבה להיות תוס' אור באו\"כ מבחי' קו המדה הנ\"ל כמו ע\"י החסד שהיה אברהם עושה המשיך תוס' אור בכלי החסד דאצילות ויצחק המשיך תוס' אור בכלי הגבורה דאצילות ויעקב בכלי הת\"ת ויוסף ביסוד וכה\"ג בכל י\"ב שבטים אך כל תוס' אור זה אינו רק מבחי' קו המדה הנ\"ל שהוא בא מן העצמות רק בבחי' צמצום והעלם כידוע וז\"ש ושמי הוי\"ה בחי' אור העצמות ממש לא נודעתי לאבות גם שהיו מרכבה לכל יח\"ע דע\"ס או\"כ כו' רק ע\"י מ\"ת בי' הדברות ובמצות מעשיות דוקא שם בא גילוי האור מבחי' העצמות ממש להיות בחי' תוס' אור העצמות מאיר בקו\"ח שנק' קו המדה להאיר ביתר מכפי המדה באו\"כ מקיפים ופנימים וזהו שבתפילין דמארי עלמא כתיב ומי כעמך ישראל גוי אחד בארץ כו' וכה\"ג כל מצות עליונות הכל בישראל תלוים באתדל\"ת אתדל\"ע ונמצא שניהם אמת דמ\"ש אשר קדשנו במצותיו ממש דהיינו מצות עליונות שנעשים ברמ\"ח אברים דמלכא זהו בחי' יח\"ע שנעשים באו\"כ שנק' רמ\"ח אברים הוא אשר נעשה ע\"י אתדל\"ת דרמ\"ח מ\"ע הגשמיי' דוקא והיינו הך ואשר נמשך במדה וקצבה ביח\"ע באו\"כ ה\"ז רק בחי' רמ\"ח אברי' דמלכא מצד עצמן לבד כמו עד\"מ אברי האדם למטה מצד עצמן שיש בהן יחוד והתכללות מראש לסוף ואין לזה ערך לגבי יח\"ע שנעשים ע\"י המצות שעושה באבריו כמו במצות הצדקה וחסד שעושה בידו או שמניח תפילין בראש שהוא למעלה הרבה מא\"מ ופנימים שלהם וד\"ל:\n(טז) <b>ובזה</b> יתורץ כמה ענינים הנראים כסותרים במאמרי הזהר וגם בדברי רז\"ל כמו במ\"ש רז\"ל ע\"פ ועשיתם אותם כאלו עשאוני ברמ\"ח אברים והן רמ\"ח פקודין שנק' רמ\"ח אברי' דמלכא הרי יש בזה ב' אופנים הא' בחי' הכלים לאורות עליונים דע\"ס שנק' אברים כמו חסד דרועא ימינא וכה\"ג והב' רמ\"ח מ\"ע גשמיים שנעשים על האברי' כמו תפילין בראש גשמי שהוא ע\"ג המוחין שבראש בבליטה וכמ\"ש כי שם הוי\"ה נקרא עליך ולמעלה היינו הקב\"ה מניח תפילין ממש כמו שמניח אדם תפילין ע\"ג ראשו וכך ציצית בבגדו שנא' עוטה אור כשלמה כו' והן הנקרא מצותיו שהוא ית' מקיים בעצמו אין זה רק ע\"י אתדל\"ת שישראל עושין וכמו בעסק ת\"ת למטה הקב\"ה יושב ושונה כו' וכן בצדקה וחסד שעושין למטה אתדל\"ע שנעשה מזה הוא מה שנמשך מעצמות אור המאציל אור ח\"ע במל' דאצילות שנק' דל שזהו חס\"ד ח\"ס דלי\"ת וכן צדקה צדק ה\"א כידוע שאין לח\"ע שכבר נמשך במל' כמ\"ש והוכן בחסד כסא וכן מ\"ש כי אמרתי עולם חסד יבנה וכה\"ג אין ערוך כלל וכלל לחסד זה שנמשך על ידי אתדל\"ת במצות הצדקה וחסד בפועל ממש כמו שהיא עפ\"י התורה הנגלית לנו דוקא וזהו שאמר ושמי הוי\"ה לא נודעתי להם דזה פלא גדול לכאורה איך ע\"י חסד דאברהם דעביד טיבו יתיר עם הבריות ועי\"ז נתעורר בחי' רב חסד עליון בשרש אור וחיות נשמתו שהוא בחסד דז\"א דאצילות בפנימיות שנקרא אברהם אוהבי רחימא דמלכא עכ\"ז שמי הוי\"ה לא נודעתי אליו רק באל שדי ולישראל בעשותן המצות צדק' וחסד כפי המצו' עליהם לבד עפ\"י תורה הנגלית לנו בהלכות צדקה יומשך שמי הוי\"ה העצמי כו' וכידוע שמקור חיי העוה\"ב הוא רק ע\"י מצות מעשיו' בגשמיות דוקא דמצוה הוא בחילוף אתב\"ש דשם הוי\"ה והמ\"ץ עתה בחילוף י\"ה בכיסוי והעלם ולע\"ל יתגלה אז הוא עצם ופנימיות אור העצמות ממש שמזה דוקא יהי' חיי העוה\"ב שנא' בו להנחיל אוהבי יש כו' וכמארז\"ל כ\"י יש להם חלק לעוה\"ב אפי' פ\"י שמלאים מצות בפ\"מ כרמון שנא' ועמך כולם צדיקים צדיקים במצות גשמיות בפ\"מ שזהו למעלה הרבה ממצות"],[2201340102,"הרוחניות דאבות כו' אך הטעם לכל זה אינו רק מפני שנעוץ פנימית ועצמות אא\"ס תחלת כל התחלות בסוף הכל שהוא בסוף מעשה בפ\"מ דוקא וכמ\"ש סוף דבר כו' את האלקים ירא ואת מצותיו שמור בפ\"מ דוקא כי זה כל האדם העליון דאצילות שלמעלה הרבה מבחי' קו המדה שמודד כל או\"כ מקיפי' ופנימי' הוא ענין אשר קדשנו במצותיו שהוא ע\"י אתדל\"ת דישראל למטה דוקא כמ\"ש ישראל אשר בך אתפאר וד\"ל):\n(יז) <b>וזהו</b> המשפילי לראות בשמים ע\"י שמים כפי' הב' דלעיל דהנה התורה מן השמים ניתנה כמ\"ש מן השמים השמיעך את קולו כו' והמצות ניתנו בארץ דוקא כמ\"ש אל יתהלל חכם כו' כ\"א לעשות חסד ומשפט וצדקה בארץ דוקא שכל התורה כולה לא ניתנה רק להמשיך אור אלקי שבאצילות בג' הקוין חח\"נ מימין כו' כ\"א שיומשך הכל בארץ דוקא וזהו חסד קו ימין ומשפט דאיהו דין וצדקה רחמים כלול משניהם כמו ודוד עושה משפט וצדקה וכן באברהם או' כי ידעתיו אשר יצוה כו' לעשות צדקה ומשפט כו' וכן הרבה בכתובים נכלל כל התו\"מ בצדקה ומשפט והכל בארץ דוקא לפי שסוף מעשה בארץ הוא שעלה בראשית ותחלת המחשבה והרצון הפנימי' והעצמות שזהו כל בחי' אור מהות ועצמות שלו שלמעלה הרבה גם מכל אשר צמצם אור העצמות בצמצום הראשון הנק' מק\"פ וחלל ריקן הנז' בע\"ח להיותו חפץ חסד להטיב מרב טובו וחסדו העצמי שבבחי' א\"ס שכל זה אין ערוך כלל וכלל לגבי עצם פנימיותו ומהותו שחפץ במצותיו הבאים בגלוי בפועל המעשה ע\"פ התורה הנגלית לנו דוקא כנ\"ל וד\"ל וכמארז\"ל במדרש במי נמלך בנשמתן של צדיקים פי' במי נמלך בעצמותו ממש אם יצמצם אורו העצמי במק\"פ וכו' להיות מקור חיים כללי בקו\"ח כו' בנשמות הצדיקים שיהיו בגופים גשמיי' ויקיימו פנימית ועצם רצונו הפשוט שבעצמותו ממש בתו\"מ בפ\"מ דוקא שזהו שמי הוי\"ה ממש בהן נמלך דוקא א\"כ מזה ראי' ברורה לכל הנ\"ל שמצות בפ\"מ הוא נוגע במוה\"ע ממש שלמעלה הרבה ממדרגות האבות כנ\"ל וד\"ל ועוד ראי' ממארז\"ל תנאי הי' להקב\"ה בו' ימ\"ב אם יקיימו ישראל תו\"מ כו' וא\"ל אחזיר אתכם לתהו כו' ולא אמר תנאי הי' על האבות כי קיום התו\"מ בפ\"מ הוא תחלת פנימית המחשבה ורצון העצמות שלא נשלם זה גם במצות ברוחניות שעשו האבות למעלה ביח\"ע שבע\"ס דאצילות באו\"כ מטעם הנ\"ל וד\"ל:\n(יח) <b>וזהו</b> המשפילי לראות בשמים וארץ שהן התו\"מ בפ\"מ דוקא כנ\"ל ופי' לראות היינו להתראות ולהתגלות כל בחי' פנימיותו ועצמותו ממש כמו שהוא שלמעלה מבחי' צמצום הראשון בקו\"ח שנקרא קו המדה כו' אין זה כ\"א ע\"י השמים שהוא התורה שניתנה לנו בפ\"מ בשעת מ\"ת דוקא דכתיב וירד ה' על הר סיני כו' ותורה זו נקרא שמים בחי' מים עליונים דפנימית ח\"ע שבעצמותו ממש וג' גוונין דשי\"ן היינו ג' מדות טמא טהור כו' שכלולים בי' הדברות במ\"ע ול\"ת באנכי ולא יהי' לך כו' שבא בפ\"מ בלא תרצח וכבוד אב ומצות שבת וכה\"ג שזה כל בחי' פנימי' ומוה\"ע ממש שיורד ומלובש בזה ולע\"ל יתגלה בעוה\"ב דכתיב בי' עין לא ראתה אלקים זולתך יעשה למחכה לו כו' וגם במצות שיהיו בימות המשיח לאחר בירור עה\"ד טו\"ר דרוח הטומאה יעביר מן הארץ ויהי' מעשה המצוה בשלימות העליון הרבה יותר עכ\"ז עיקר המכוון במצות בפ\"מ דעכשיו דוקא לברר לעה\"ד טו\"ר דוקא וד\"ל והיינו דוקא כאשר מגביהי לשבת בבחי' העילוי אחר עילוי בפנימי' עצמותו דוקא שאין לו שיעור למעלה מעלה אז הוא משפילי לראות כל בחי' פנימית מוה\"ע ממש בתו\"מ בפ\"מ שהוא בשמים וארץ דוקא כנ\"ל והשפלות והירידה עם ההגבהה בעצמותו הכל"],[2201340103,"ענין א' והא בהא תליא וזהו שאמר מגביהי ביו\"ד דחכמה בראש בחש\"מ ומשפילי ביו\"ד דח\"ת בסוף מעשה דתו\"מ דנעוץ תחלתן בסופן וסופן בתחלתן וז\"ש אם לא בריתי יומם ולילה ב' מדרגות דח\"ע וח\"ת חוקות דתשב\"כ ושבע\"פ שמים וארץ בשרשן בטה\"ע לא שמתי כו' מטעם כל הנ\"ל וד\"ל וזהו כי עמך מקור חיים היינו בבחי' צמצום הראשון דישת חשך סתרו שלפני הארת אור הקו\"ח שנק' קו המדה כנ\"ל שבטל ונכלל בו כל מקור חיים העליונים דאבי\"ע כנ\"ל אך מ\"מ באורך נראה אור ויש בזה ב' פירושים כנ\"ל הא' לגריעותא שמ\"ש נראה לשון הסתר והעלם עצם האור כמו אור הנראה ע\"י מסך שנשתנה מהות עצם האור ונק' אספקלריא דלא נהרא וכמו מראה הנבואה ע\"י צמצום דכברייתו ש\"ע ברישא חשוכא כו' וכמו אור הנכפל (שנקרא ווידער שיין) או כמו מראה שאינו רואה בה רק דמות ולא עצם וכל זה משלים להבין בכל עיקר ושרש הצמצום הראשון הנקרא מק\"פ שאז האור הנראה בא בשנוי המהות וכ\"ש במסך שבין עצמות המאציל לנאצלים בכל פרצוף עד מל' דאצילות בבריאה שנקרא מסך ומבדיל כו' שהכל בא במדה ושיעור עפ\"י מאמר קו המדה כנ\"ל במצות הרוחניות דאבות וכה\"ג אבל מדרגה הב' הוא למעלה מעלה הרבה מצמצום דקו\"ח הנ\"ל והוא בבחי' פנימיות מוה\"ע ממש שמלובש בתו\"מ בפ\"מ דוק' כנ\"ל באריכות וזהו פי' הב' במ\"ש נראה אור דהיינו שאנחנו בנ\"י דוקא נראה אור בתוך אורך העצמי שלפני הצמצום הראשון שלא ע\"י העלם ומסך כלל ולבד זה נראה אורך העצמי בתוס' גלוי אור בהבהקה ויתרון האור הרבה שלא הי' נראה כזה כלל בלתי התלבשותו בשמים דוקא וזהו באורך העצמי שבתו\"מ במוה\"ע ממש נראה אורו ביתרון ע\"י שמים שמשפילי לראות שם דוקא שמהתלבשות עצמות אורך בשמים במ\"ת ובמצות בארץ בפ\"מ דוקא שם דוקא נראה אור העצמי והפנימי ביתרון גדול הרבה וכמו הרואה ע\"י זכוכית בהירה שמבהיק האור ביותר הבהק' וביותר התרחבות לאין שיעור כמ\"ש בחיי העוה\"ב עין לא ראתה כמו שהעין לא תראה באו' בהיר ביותר כ\"א ע\"י לבוש זך ביותר וזהו שאמר בתורתו של ר\"מ הי' כתוב כתנות אור באלף דהיינו בחינת ברורים דעה\"ד טו\"ר דשרשו בחשמל דק\"נ שהן כתנות עור בעין בשביר' הכלים דז\"מ דתהו ולאחר הבירור יהיו בבחי' לבוש זך כאור הנראה מחמת הזדככות הכלי ביותר כו' משא\"כ עתה נהפוך הוא שבחי' חשמל דנוגה הוא בחי' המסך שמפסיק ונקרא אספקלריא דלא נהרא וזהו פי' השני דנראה אור וע\"י מסך דוקא דהיינו כשאין תו\"מ בפ\"מ בישראל שאז מקבלים יניקתם מע' שרים דנוגה ששם הוא הסתר הפנימי' כמ\"ש אסתיר פני ע\"י דאסתלק לעילא ונמשל לשינה כו' כנ\"ל שאז א' אין כמוך באלמים כו' ואז נאמר מציץ מן החרכי' שבמסך והיינו פי' הב' דנראה אור ע\"י הסתר וצמצום גדול בשמים וארץ היפך פי' הב' דלעיל וד\"ל:\n(יט) <b>ואחר</b> כל הנ\"ל יש להבין בענין מנורת זכרי' ענין וגולה על ראשה ושנים זתים עליה כו'. דהנה מובן מכל הנ\"ל בענין מגביהי לשבת משפילי לראות לפי פי' הב' דלעיל בלראות בשמים כו' דדוקא ממקום שעלה לשם כשמגביהי לשבת בעילוי אחר עילוי בעצמותו ממש לאין קץ ושיעור כלל משם דוקא הוא משפילי לראות ולהתגלות בבחי' שפלות וירידה ע\"י תו\"מ שישראל עושין למטה דוקא להיות מאיר גם בע\"ס דאצילות בתוס' אור מרובה על העיקר הרבה יותר מכפי המדה דקו המדה עד שבכלל מאתים מנה לפי שירידה זו מן פנימית העצמות ממש שלגדולתו העצמי' אין חקר כלל כו' וזהו ענין המנורה שראה זכרי' שנים זתים עליה שמאליו נמשך ויוצא השמן מן הזתים שמימין הגולה ומשמאלה אל הגולה ומן הגולה אל הז' וז' מוצקות ומן המוצקות לנרות"],[2201340104,"המנורה כי הנה במנורה שבבהמ\"ק היה השמן זית זך מובא מלמטה וכמ\"ש ויקחו אליך שמן זית זך כתית למאור והיינו בחי' החכמה שנק' שמן שהוא בחי' כח מ\"ה שבנש\"י שעל ידו יאיר אור האלקי בכל נשמות ע\"י אהרן כה\"ג שושבינא דמטרוניתא כמ\"ש בהעלותך את הנרות והיינו באתדל\"ת דוקא בכל נשמה לפ\"ע דכתיב ושמן על ראשך אל יחסר כו' וזהו למאור להמשיך אור בנש\"י באתדל\"ע ע\"י משה שושבינא דמלכא כמ\"ש במ\"א (ועכשיו הוא בחי' רצוא ושוב שבתפלה ותורה כו') וכמו שאם אין יראה אין חכמה ואם אין חכמה אין יראה דאין האור דחכמה מאיר רק לפי ערך היראה באתדל\"ת ואם אין חכמה בבחי' כח מ\"ה שנק' שמן על ראשו אין יראה בחי' יראה עילאה דהא בהא תליא כו' (אבל בזמן הגלות דכנ\"י בחשך ולא אור כלל עד שאין אור דחכמה ביכולתו להאירם כלל מצד עוצם ירידתם למטה מטה כ\"כ ומצד עוצם בחי' הסתר האור דאלקי למעלה מעלה דכתיב ביום ההוא הסתר אסתיר פני כו' דקוב\"ה בגלות' אסתלק לעילא לעילא היינו כמו המגביהי לשבת בעילוי העצמות ביותר ולזאת אין בחי' האור דחכמה יכול להאיר אור נשמתם כלל (גם לא ע\"י משה באור דתורה וראי' לזה ממה שאנו רואים שבימי התנאים מיד אחר החורבן עדיין אור דתורה הי' מאיר בנש\"י ולא היה בנמצא כלל שמי שבתורת ה' חפצו ובתורתו יהגה יומם ולילה שלא יהיה צדיק גמור באוי\"ר ודביקות האמתי בתפלה וכל מע\"ט ועתה בנפילת מדרגות דנש\"י דור אחר דור יחשך אור נשמתם כ\"כ עד שגם לומדי תורה כאחד העם ממש יחשבו לבלתי יועיל להם אור דתורה כלל וכלל להחזירם למוטב היפך מה שא' אם אין יראה אין חכמה עד שיכול להיות מופלג בתורה ואין בו י\"ש כלל וכן להיפך יש יראי אלקים ואין בו תורה כלל כי האתתא שהיא כנ\"י שנק' יראה תתאה אתתרכא מבעלה שהוא החכמה דתורה שם מ\"ה בחי' וי\"ו כו' משא\"כ בזמן בהמ\"ק ואחריו לא היה יראה בלא חכמה ולא חכמה בלא יראה יחדיו ידובקו וישכנו ולא ישכנו זה בלא זה כלל וד\"ל) וכן בענין התפלה שנק' יראה גם היא ירדה ונפלה למטה מטה בסוף הדורות שנק' עקבות משיחא עד שאין איש מתעורר באוי\"ר ותשובה אמיתית גם מאתדל\"ע מאהרן כה\"ר שמעלה את הנרות כי לא יגיע אליהם גם אה\"ר העליונה למושכם בהתעוררות אהבה או תשובה כו' מצד עוצם הירידה כמשל הנופל בבור עמוק עמוק שלא יגיע לו האור כלל או שלא יגיע אליו קול התעוררות או חבלים למושכו כו' ומכל זה בא סיבת העדר האור אלקי בנש\"י לגמרי רק מה שמאיר בהם מצד מעשיהם רק בחצוניות בעול תו\"מ בקיומם בפ\"מ לבד בלי שום התעוררות פנימית הלב והרצון כלל וכלל וד\"ל אך הנה ע\"ז א' המשפילי לראות בשמים וארץ גם בשעה שמגביהי לשבת והוא בזמן הגלות דוקא שמגביהי לשבת בעילוי העצמות לעילא לעילא והיינו יו\"ד דמגביהי בח\"ע כו' אז דוקא משפילי ביוד דח\"ת בכנ\"י בהיותם רק בעול תו\"מ בפ\"מ לבד שזהו סוף מעשה מצד עצם עול המעשה לבדה שעולה על הכל גם למעלה מתחלת המחשבה והרצון וכו' וזהו ענין ביאת משיח ב\"ד שאינו בא רק מכח של המעשה בעול תו\"מ בפ\"מ לבד כמ\"ש ויהי נועם ה' עלינו ע\"י שמעשה ידינו כוננהו והיינו נועם ה' עלינו בימי משיח (שע\"ז א' תפלה למשה כו' מעון הייתה כו' אותיות נועם כו') והוא הנק' כתר שם טוב שעולה ע\"ג ג' הכתרים דכתר תורה וכתר כהונה וכתר מל' וכמ\"ש במשיח ישכיל עבדי כו' וגבה מאד למעלה מאדם והוא הנק' כתר שבכתר בחי' עטרת תפארת וכמ\"ש אבן מאסו הבונים א' ב\"ן דמל' שבמל' דבריאה שמברר עה\"ד טו\"ר בפ\"מ היתה לראש פינה בעטרת לתפארת שבראש וזהו ואלה דברי דוד האחרונים שלמעלה מראשונים דחכמה שבראש והוא במה שהקים עול דוקא כו' וזהו עיקר ענין הגולה שעל"],[2201340105,"ראשה שראה זכרי' שזהו למעלה מבחי' פני המנורה שבזמן בהמ\"ק שהיה צריך להדלקת כה\"ג אבל הגולה הרי היא נובעת מאליה מהשני זתים שעלי' שנובעים תמיד מאליהם (ולא כמו שמן כתית למאור למנורה שבבהמ\"ק שהשמן המובא צריך דריכה בבית הבד שנק' כתית עד שיהיה זך למאור אבל שמן זה שבשני זתים א\"צ דריכה כלל ונובע מן הזתים מעצמו ובלי הפסק כלל עד שגם הנביעה מן המוצקות לנרות ג\"כ בלי הפסק מפני שהנביע' מן הזתים לגולה תמידי' ומן הגולה למוצקות:\n(כ) <b>והענין</b> הוא כמ\"ש במ\"א בענין ב' כתרים דנעשה ונשמע שכתר דנעשה הוא הנק' כתר ש\"ט שעולה ע\"ג כו' שזהו בחי' ביטול הרצון שבמעשה לבד רק מצד עול מ\"ש הוא למעלה גם מכתר מל' וכתר תורה והוא המעורר למעל' בחי' גלוי עצמות אא\"ס שיאיר בפנימיות הכתר מאליו ומעצמו בלי הפסק כלל שאין כל העלאת מ\"ן באתדל\"ת מגיע לשם כלל ע\"י שום כונה ורעותא דלבא רק בבחי' ביטול רצון לעשות המצוה בפ\"מ לבד וכמו שא' כל אשר דבר ה' נעשה בפ\"מ אע\"פ שלא שמעו עדיין מה רצונו והיינו כמא' בטל רצונך מפני רצונו כו' בלי התעוררות פנימית ברצון ומדות שבלב כלל כנ\"ל וביאור טעם הדברים הנה ידוע שיש ב' מיני רצון א' רצון המורכב הנק' בחירה שיש בו חילוף ושינוי ותמורה כמו שא' ובחרת בחיים כו' שזהו כל יסוד התו\"מ שילך האדם בדרכי ה' ע\"פ הבחירה שבלבבו דוקא דהיינו כאשר יתעורר בלבו והכין רצונו ודעתו ולבבו להתקר' לה' ותורתו ועבודתו בסור מרע ועשה טוב כל היום לפ\"ע הכנת לבבו ורצונו הוא בוחר בטוב וסר מרע כל היום בפ\"מ היינו לפ\"ע התעוררו' לבבו יעשה טוב וישמור מעשות כל רע אבל כאשר אין התעוררו' בלבבו כלל וכלל לילך בדרכי ה' כו' לא יתקרב לה' במעשה הטוב ולא יסור מעשו' כל רע בעיני ה' והרי אין ערך הילוכו ודרכו בדרכי ה' רק לפי ערך התעוררו' לבבו אם מעט אם רב כידוע וזהו הנק' בעל בחירה שלפעמי' בוחר בטוב ומואס ברע ולפעמי' להיפוך יבחור ברע וימאס בטוב שזהו שינוי וחילוף ברצון שלפעמי' יתעורר רצונו ולבו לילך בדרכי הטוב ולסור מרע ולפעמי' יתעורר בהיפוך וכו' וא\"כ אין זה דבר אמת המתקיים בתמידות בלי שינוי כלל אלא לפעמי' רוצה בטוב ולפעמי' רוצה ברע והוא מפני שרצון זה נק' מורכב בבחירה שבלב ועכ\"ז בשעה שרצונו מתעורר בטוב מעורר למעלה לבחי' הטוב העליון הגנוז במעשה הטוב במ\"ע דרוח אייתי רוח ואמשיך באתדל\"ת אתדל\"ע כמ\"ש אם ישים אליו לבו כו' כידוע ולהיפך בשעה שמתעורר רצונו ולבו לרע מעורר מדת הדין והרע וז\"ש ראה נתתי לפניך החיים והטוב והמות והרע כו' וכן נק' ברכה וקללה כו' כמ\"ש את הברכה אשר תשמעון כו' כידוע וזה נמשך מצד שהאדם הוא בעל בחירה והוא בא בבחי' עה\"ד טו\"ר כו' וע\"ז הוסד כל התו\"מ לברר ולהבדיל בין טו\"ר בדרך בחירת הרצון דוקא וכמ\"ש ובחרת בחיים כו' בבחירה שברצון אמנם יהי' באופן שלא ישונה מטוב לרע אלא תמיד יבחר בטוב ויסור מרע ולכאורה איך יהי' נצחי ותמידי אם הבחירה הוא דבר שמתחלף משעה לשע' כנ\"ל שלפעמי' יתעורר להיפך וזה א\"א לומר שהציווי על הבחירה הזאת היינו שיתעורר תמיד לטוב כי איך יגזור הציווי על ההתעוררו' מאחר שההתעוררות תבא בלב האדם בשינויים וחילופים כו' אלא צריך לומר שהציווי הזה דובחרת בחיים בא בשני אופנים הא' שיבחור ברצון בלב ומוח עפ\"י התעוררות דוק' שתמיד יכין לבו לדרוש הדרך החיים הטוב מצד נשמתו שקרבת אלקי' יחפץ בחפץ ורצון שבלב ומוח דוקא והיינו מצד האהבה שבלב כמ\"ש ואהבת את ה' כו' והאהבה היא שרש לרמ\"ח מ\"ע וכן היראה ופחד אלקי' בלב ומוח שרש לשס\"ה ל\"ת כידוע ונמצ'"],[2201340106,"ע\"י מצות האוי\"ר הם העושי' הבחירה תמידי' שיבחור תמיד בטוב ולא ברע בלי שינוי כלל וכלל רק שאוי\"ר זו שמעוררי' הבחירה צריך להיות ע\"י יגיעת הנפש ולא ממיל' נעשית כו' וכאשר יגזור או' ובחרת היינו שישים לבו ודעתו להתיגע בהתעוררות האהבה אלקי' לחפוץ בקרבת אלקי' ע\"י רוב יגיעת הנפש וכן ביראה כמ\"ש ז\"ל אוי לבשר שלא נתייגע ביראה כו' ואז יהי רצון לבו לטוב ממילא וע\"ז הוסד ציוי זה דווקא ואם לפרקי' ישתנה מצד מיעוט חפצו בקרבת אלקי' וכו' יתחזק תמיד בלבו ודעתו עד שיהי' באופן שאין בבחירה הזאת שום שינוי כלל כל ימי חייו כו':\n(כא) <b>אך</b> האופן השני בציווי זה דובחרת לא מצד בחירה שבלב ע\"פ התעוררות בלב באוי\"ר כנ\"ל אלא רק ע\"פ קבלת עול לבד שבזה לא יפול שינוי וחילוף לעולם גם שלא יש בלבו שום התעוררות כלל וכלל כי הנה אנו רואים בענין העול שעל העבד במלאכתו ודאי אין בו רצון הבא עפ\"י בחירה כלל כי ודאי אין בעבודתו שום חפץ ורצון שבלב כלל כי בע\"כ עובד רק מצד העול של המלך בלבד הוא שמכריחו לעבודה זו שמוכר' תמיד לעבוד גם שהוא בלתי בוחר בזה כלל ואמנם היא הנותנת שלא יפול בזה שום שינוי וחילוף מעת לעת כלל וכלל כי אם הי' העבד עובד מצד הרצון והבחירה כאיש העובד במלאכתו בשדהו לפרנסתו שאז הי' בו שינוי רצון שפעמי' אינו חפץ ובוחר כו' אבל מאחר שאין בו רצון ובחירה מעולם רק מצד העול לבדו ע\"כ ודאי לא יש בלבו שינוי באופן שכל יום ויום עבודתו בשוה בלי הפסק וביטול ולא בשינוי אופני' כלל ולזאת עבודתו נצחי' בלי הפסק כלל וכלל כי אין בעבד רק ביטול רצון שלו לבד מה שמבטל עצמו נגד רצון המלך להיות עושה דבר המלך מצד העול מלכות שעליו הרי ביטול רצון זה תמידי ונצחי בלי שינוי וגרעון כלל שאין בטול רצון זה בא מצד איזה התעוררות בלב ומוח כלל עד שיפול שינוי לפעמי' במיעוט התעוררו' כו' אלא הוא בטול עצמי וטבעי בתמידות לא יופסק לעולם כל זמן חיותו שעול המלך עליו ונמצא מובן מזה שגם מ\"ש ובחרת בחיים אם הוא ע\"פ קבלת עול מ\"ש לבד ולא מצד ההתעוררות בלב בבחירת הרצון וחפץ הוא נצחי ותמידי בלי שינוי כלל הרבה יותר מע\"י הבחירה ברצון כו' ואע\"פ שבאוי\"ר בהתעוררות בלב יש בחי' פנימיות האור וחיות רב יותר מ\"מ הרי יפול בו מיעוט אחר מיעוט עד שצריך להתייגע ולחדש התעוררות לבו כנ\"ל אבל בעול מ\"ש אין בו מיעוט וגרעון לעולם שלא יפול מעבודתו בעול מ\"ש אפי' כמלא נימא כאילו הוא טבעית ועצמית בעצם מהות נפשו ממש שכל עצם בלתי משתנה לעולם כידוע וד\"ל:\n(כב) <b>וזהו</b> מ\"ש כי לי בנ\"י עבדים עבדי הם כו' דהנה בנ\"י הם בב' מדריגות בנים ועבדים כידוע בענין אבינו מלכנו כו' שמצד הנשמות נק' בנים כמ\"ש כי אתה אבינו ומצד הגוף נק' עבדים כו' וכמ\"ש במ\"א ע\"פ כי הוא עשנו ולא אנחנו בא' ובוי\"ו כו' וכל עיקר ירידת הנשמה בגוף להיות בבחי' עבד דוקא בקבלת עומ\"ש שזהו עולה למעלה מבחי' בן מטעם הנ\"ל בענין העול שלא יפול בו שינוי כלל כאילו הוא מהות ועצם נקודת הרצון שנק' רצון הפשוט שלמעלה הרבה מבחי' רצון המורכב המתלבש בבחירה שמשתנה ומתחלף כו' כי הנה האיש מישראל אשר יטה שכמו בעול מ\"ש לעבוד עבודת ה' בסור מרע ועשה טוב בכפי' והכרח לעשות הכל נגד רצונו הטבעי דהיינו שיעשה הטוב במ\"ע גם בעת שאין בלבו שום התעוררות כלל לחפוץ קרבת אלקים רק שמכריח א\"ע לבטל רצונו מפני רצון ה' לעשות צדקה וכה\"ג אעפ\"י שאינו חפץ בלב כלל וכלל אך מפני עול מל' מוטל עליו לעשות רצונו כו' וכן בשאר המצות וכמ\"כ בסור מרע אעפ\"י שאין התעוררות פחד ה' ויראת אלקים בלבו כלל וכלל מ\"מ הוא כובש לבו"],[2201340107,"בע\"כ ומושל ברוחו ויצרו לבלתי עשות הרע בעיני ה' מצד שירא למרוד בקונו לעשות הרע בעיניו ולעבור על רצונו כו' הנה זהו העול' על כל מדרגות העבוד' שבלב באוי\"ר פנימית וזהו שא' נאם דוד בן ישי הקים על הקים עולה של תורה כו' שהוא בחי' כתר ש\"ט הנ\"ל שעולה ע\"ג ג' הכתרי' כנ\"ל שמזה נעשה בחי' כתר שבכתר שנק' עטרת תפארת כו' וכמ\"ש אבן מאסו וכו' א' ב\"ן שבעול מ\"ש בחי' מל' דמל' שהוא בלתי בחירה שרשו ברצון העצמי שלמעלה מן הבחירה שהוא למעלה מטעם לרצון אף טעם כמוס כי התחלקות הרצון מהיפוך להיפוך זהו בא מצד הטעם שהוא תענוג שברצון ע\"כ ישונה הבחירה כו' אבל למעלה מן התענוג שברצון הוא עצם נקודת מקור התפעלות הרצון שאינו בשם התפעלות רצון כלל ולא בשם בחירה כלל ע\"כ איננו משתנ' לעולם והוא הנקרא כתר ש\"ט כמ\"ש ויעש דוד שם שהוא שם ב\"ן דעול מ\"ש כמ\"ש הקים על כו' והוא מ\"ש טוב שם משמן טוב דהיינו למעלה גם מענג הנעלם שבחכמ' הנק' שמן הטוב על הראש דכה\"ג והוא מקור זה התענוג הנעלם שנמצא בסוף מעשה בעול דוקא שמזה דוקא נשלם התענוג שברצון וכמ\"ש במ\"א במשל הבונה בנין שכאשר נשלם המעשה בפ\"מ אז נשלם התענוג ורצון שהי' לו לבנין זה וכמ\"ש וירא אלקים את כל אשר עשה בפ\"מ והנה טוב מאד למעלה מטוב ותענוג כשעלה ברצונו כו' כי התענוג ורצון הקדום הי' רק בשביל המעשה ולזאת אין שלימות לרצון הקדום רק מגמר המעשה וא\"כ הרצון הקדום מקבל מן השלמת המעשה וזהו שרש ענין מצוה בפ\"מ דוקא שלמעלה מן הרצון ותענוג שבמצוה עצמה עד שמחמת הפ\"מ יבא הענג שברצון המצו' לשלימותו והן טעמי מצות שיתגלו בימות המשיח רק מגופה של מעשה דעכשיו דוקא והן שמחה ש\"מ השמחה היא רק מצד המעשה של המצוה שקיים רצון העליון בפ\"מ ולא מצד השמחה בכוונות המצוה וראי' מג\"א ורוה\"ק שזכה האריז\"ל רק משמחה ש\"מ בלא כוונה וסוד כלל ונמצא דור האחרון הזה הגם שחסר להם כל בחי' אור וחיות האלקי באוי\"ר עד שלא נשאר רק עצם המעשה וגם השמחה ש\"מ רק מן הפ\"מ לבד אדרבה היא הנותנת שיהי' מזה דוקא בחי' כתר ש\"ט דמשיח שע\"ז א' טוב שם משמן טוב כו' וכמ\"ש אבן כו' היתה לראש פינה עטרת תפארת כנ\"ל והיינו ענין הגולה ושני' זתים עלי' שראה זכריה שהוא בחי' כתר ש\"ט דמשיח שלמעלה משמן הטוב שבראש כו' וכמשי\"ת ב\"ה וד\"ל (שהוא רק ביטול הרצון ע\"י עול העבודה בלא טעם ששרשו למעלה מן הטעם ותענוג שברצון וחכמה הנק' שמן הטוב או שמן למאור כו'):\n(כג) <b>והנה</b> במנורה דזכרי' הי' שני דברים הא' המקור הראשון שהוא הזתים שמימין ושמאל המנורה שמריקים השמן לגולה והב' המקור השני שנמשך השמן מן הגולה אל המוצקות ומן המוצקות לנרות המנורה כו' וכללות הענין דמנורה זו שראה זכרי' הוא בזמן הגלות דוקא שמגביהי לשבת כו' וכנ\"י בתכלית הירידה למטה עד שאין אור דתורה ואור אהבה רבה דכה\"ג העליון מגיע להם לעוררם בהתעוררות אוי\"ר ותשובה כו' כנ\"ל אך עכ\"ז נמשך אתדל\"ע מצד עצמות אא\"ס שלמעלה מבחי' אור דחכמה (והיינו כתר ש\"ט שלמעלה מכתר תורה וכ\"כ וכמ\"ל) שאין שום העלאת מ\"ן מעורר שם כלל מאחר שהוא מוגבה ומרומם בבחי' עילוי העצמות ממש רק ע\"י ביטול רצון בע\"כ דוקא (שלמעלה מן הבחירה ורצון כנ\"ל וזהו ההפרש בין כתר מל' שמלכותו ברצון קבלו במ\"ת שהוא כתר מל' וכתר תורה בין עול מלכות כעבד לאדון שעולה ע\"ג מטעם הנ\"ל) והוא ענין הזתים שעל הגולה שהוא בחי' התעוררות המשכה עצמי' ומקורי' מצד עצמיותו לכנ\"י כמו שמלמטה למעלה מבטלים רצונם בתמידות גם בלי התעוררו'"],[2201340108,"רצון כך מלמעלה למטה מצד עצמותו נמשך לנש\"י להיות ממילא עי\"ז גלוי התעוררו' רצון ובחירה כו' שזהו למעלה מבחי' התעוררות הרצון והחכמה וטעם לרצון והיינו למעלה מבחי' אור אה\"ר ואור החכמה דתורה שאעפ\"י שלא יוכל אור דחכמה דתורה ואור הרצון דכתר עליון להאיר בנש\"י בזמן הגלות אבל מלמעלה מבחי' האור וגילוי דכו\"ח כו' משם דוקא יכול להמשך ולהגיע לנש\"י גם בהיותם בחשך ולא אור כלל דכל הגבוה גבוה יותר יותר יוכל לירד מטה מטה ביותר וכנ\"ל בענין המגביהי לשבת ע\"כ משפילי לראות כו' ונמצא שבחי' המשכה זו דזתים בגולה שעל ראשה למעלה מאור פני המנורה שבזמן בהמ\"ק שע\"י הדלקת כה\"ג וד\"ל:\n(כד) <b>אך</b> הנה פרטי ענין המנורה דזכרי' בשני זתים מימין ומשמאל הגולה הענין הוא מה שאנו רואים שימצא כח ועוז לנש\"י להתעורר בתשוב' גם מבלתי בחירה ורצון מצד עצמם כלל ולא מצד הארת אור אה\"ר עליונה כלל כו' רק שבא ונמשך מעצמו בהעלם בכח נשמתם כו' להיות סו\"מ ועשה טוב בפ\"מ זהו ענין ההתחלקות דימין ושמאל מהשני זתים על הגולה וכדוגמא שהי' במ\"ת התחלקות זו בבחי' אור המאיר בגילוי אור פני מלך כו' באמרו אנכי ולא יהי' לך שמפי הגבורה שמענו כו' שהוא שרש למ\"ע ול\"ת כידוע בענין קבלת התורה כך הוא בזמן הגלות בהסתר פנים בא בחי' ההמשכ' העצמי' ומקורי' בהעלם ובכח לכל נש\"י מלמעלה מבחי' אור כנ\"ל בהתחלקות ג\"כ לחו\"ג שהוא לימין הגולה ושמאלה להיות כח ועוז בנש\"י למעלה מן הבחירה כו' להיות סור מרע בל\"ת ועשה טוב בפ\"מ ומן הגולה נמשך למוצקות שהן מקוריות הז' המדות אוי\"ר כו' כמו שהן בעצמיות הנק' יחידה ומשם נובע בהעלם לז' נרות שהן ז' מדות בגילוי שנמשכי' מחו\"ב ובכללות הן כללות נש\"י שנק' ז' נרות המנורה רק שבזמן בהמ\"ק הי' אהרן כה\"ר העליון מעל' אותם להאירם מלמעלה למטה בגילוי אור כמ\"ש בהעלותך את הנרות שהן כללות נש\"י אל מול פני המנורה יאירו בבחי' שמן ואור שנק' שמן למאור כו' ובזמן הגלות שאין בחי' אור אה\"ר דכה\"ג מאירם אז נמשך בהן מעצמות העלם ומקור האור דכו\"ח שגם בחשך יאיר כו' וע\"כ נק' מוצקות שממילא מוצקים מן הגולה והוא מקור השני שנמשך מחו\"ב שבכתר שנק' גולה והכל בבחי' העלם העצמות אבל מקור הראשון הוא מה שנמשך מן הזתים לגולה בהתחלקות לימינה ושמאלה שאין אתדל\"ת שע\"י הבחירה ורצון יוכל להגיע שם כלל להיותו למעלה מבחי' גלוי רצון וטעם כנ\"ל באורך וד\"ל ונמצא יש ב' מדרגות הא' ע\"י בחירה ורצון כנ\"ל באופן הא' דובחרת בחיים ע\"י אוי\"ר באור דכו\"ח שנמשך עי\"ז אור פנים העליונים להאיר את הנרות דכנ\"י כענין משכני אחריך נרוצה וזה הי' במ\"ת וגם בכל דור שגם בזמן הגלות יש עתים מיוחדים שמאיר אור פני מלך לנש\"י כמו בג' רגלים וביו\"כ בי\"ג מדה\"ר שיאר ה' פניו כו' וע\"ז אמר בהעלותך שהוא אהרן כה\"ר כו' והב' אופן הב' בביטול רצון בעול מל' שנמשך מן העצמות ממש למעלה מבחי' גלוי אור דכו\"ח כו' שמזה יהי' ענין כתר ש\"ט דמשיח דכתיב בי' ישכיל עבדי בחי' עבד שלמעלה מבחי' בן וכמ\"ש הקים עול עול' של תורה דוקא וכמאמר אשרי מי שעמלו בתורה כו' וכמ\"ש כי לי בנ\"י עבדים כו' כנ\"ל וע\"ז א' שמח נפש עבדך שצריך להמשיך לעבד שמחה מאחר שאינו עושה רק בעול מל' לבד ואמנם השמחה שנמשך לו מלמעלה כמו בשמחה ש\"מ שמצד שקיים רצון המלך שרשו בעצמיות הנפש ממש שלמעלה מן התעוררות הבחירה ורצון כנ\"ל וזהו שמח נפש עבדך כי אליך ה' נפשי אשא פי' נפשי כל נפשי היינו כל עצם נקודת הרצון שלמעלה מן הבחירה כו' והוא ע\"י בטול רצון בעול מ\"ש בחי' עבד דוקא ע\"כ א' שמח נפש עבדך כי אליך כו' וד\"ל"],[2201340109,"ובזה יובן פי' ברכות המצות בא\"י אמ\"ה פי' תחלה צריך להיות בחי' המשכה משם הוי\"ה להיות אלקינו מלך כו' שהוא ע\"י בחירה ורצון דוקא כמו שום תשים עליך מלך שנק' כתר מל' ואח\"כ א' אשר קדשנו במצותיו וציונו שהוא בחי' עול מ\"ש שלמעלה מן הבחירה כנ\"ל שנק' כתר ש\"ט שעולה ע\"ג כו' שמגיע בבחי' העצמות ממש שנק' מצותיו ממש וד\"ל:"],[2201340110,"<h2>שער הפורים</h2>\n(א) <b>יביאו</b> לבוש מלכות אשר לבש בו המלך וסוס אשר רכב עליו המלך ואשר נתן כתר מלכות בראשו. הנה ענין לבוש מלכות למעלה היינו מ\"ש ה' מלך גאות לבש שנתלבש הקב\"ה בלבוש גיאות שהוא בחי' התנשאות שזהו בחי' לבוש מלכות להיות מלך על עם כמ\"ש מלכותך מלכות כל עולמים כו' וענין מ\"ש וסוס אשר רכב עליו המלך היינו מ\"ש במ\"ת כי תרכב על סוסיך מרכבותיך ישועה וזהו אשר רכב עליו המלך בשעת מ\"ת. ואשר נתן כתר מלכות בראשו זהו ענין מ\"ש במ\"ת בעטרה שעטרה לו אמו ביום חתונתו זה מ\"ת כו' כי הנה ארז\"ל וקבל היהודים את אשר החלו לעשות שהחלו בזמן מ\"ת שהיתה רק התחלה כשאמרו נעשה ונשמע ובימי מרדכי היה גמר הקבלה. ונמצא שכל הבחי' ומדריגות שנתגלו במ\"ת נתגלו ג\"כ בימי מרדכי וביתר שאת כי בימי מרדכי היה גמר הקבלה את אשר החלו בשעת מ\"ת. ולהבין זה הנה תחלה יש להקדים ביאור מארז\"ל תכלית חכמה תשובה ומע\"ט שנאמר ראשית חכמה יראת ה' שכל טוב לכל עושיהם ללומדיהם לא נאמר כו' והלומד ואינו עושה מוטב לו שתתהפך לו שלייתו על פניו כו' כי לא המדרש עיקר אלא המעשה אך היינו דוקא במצות שא\"א לו לעשות' ע\"י אחרים אבל במצוה שאפשר לעשות' ע\"י אחרים אמרו בהיפך ע\"פ וכל חפצים לא ישוו בה אפילו חפצי שמים שכל המצות אינן שוין אפילו לדבר א' מד\"ת הרי אנו רואים שיש בחי' ומעלה יתירה בתורה על המצות ויש בחי' ומעלה יתירה בקיום המצות יותר מד\"ת וגם מה שאמרו ות\"ת כנגד כולם ואעפ\"כ מה שנמנו וגמרו דתלמוד גדול אינו אלא מטעם שמביא לידי מעשה וזיל בתר טעמא הרי מזה משמע ג\"כ שיש מעלה בזה מה שאין בזה. ותחלה יש להבין בענין מעלה יתירה שבקיום המצות על ד\"ת והוא במה שא' ג\"כ דתכלית חכמה שבתורה הוא תשובה ומע\"ט דוקא וכן הלומד ואינו עושה כו' הרי בחי' תכלית המכוון הפנימי שבחכמה אינו רק תשובה ומע\"ט והתורה אינו רק כמו דרך ומבוא לבוא אל תכלית הכוונה הפנימי' כו' והענין הוא בהיות ידוע שהחכמה היא בחי' ראשית כל ההשתלשלות וע\"כ נק' החכמה ראשית כמ\"ש בראשית ברא ות\"י בחוכמתא כו' וכמ\"ש כולם בחכמה עשית כו' אך אמרו בראשית נמי מאמר הוא שגם בחי' החכמה בבחי' ההשתלשלות עכ\"פ רק שנק' בשם ראשית לכל ההשתלשלות ונק' ראשית הגלוי וכמו שלכל ראשית יש למנות אחריו שנית ושלישית הרי גם הראשית מן המנין מאחר שמונין אחריו שנית ואם אין הראשית מן המנין לא יתכן לקרות שנית כידוע:\n(ב) <b>והענין</b> הוא כידוע בפי' ענין השתלשלות שזהו כמו שלשלת מהרבה טבעות אחוזים זו בזו שהתחתונה אחוזה בסוף העליונה ועד\"ז הולך ומשתלשל כו' כך ענין השתלשלות למעלה כמו השתלשלות המדות מן השכל"],[2201340111,"שהמדות נולדי' ומתהוין מן השכל הרי מסוף מדרגת השכל משתלשל התהוות המדות והשכל מתלבש בתוך המדות וא\"כ גם החכמה בבחי' השתלשלות זו רק שהיא בחי' ראשית למנות את המדות בבחי' שנית אליה וכן מן המדות נשתלשלה המחשבה והמדות מלובשות במחשבה וכן ממחשבה לדו\"מ ונק' המחשבה בשם שלישית לחכמה ועד\"ז בדרך פרט כמו בחי' קו הימין שהוא חכמה חסד נצח הרי החסד ענף החכמה שנשתלשל הימנה ונק' החכמה ראשית והחסד שניה אליה והנצח ענף החסד כו' וזהו כמו אברהם ששרשו בבחי' החסד נק' אב\"ר מ\"ה שהוא בחי' אבר וכלי לבחי' החכמה שנק' כח מ\"ה הרי בחי' החכמה מלובש בחסד וא\"כ גם החכמה בבחי' השתלשלות רק שהיא בחי' ראשית ומקור ההשתלשלות ואע\"פ שנאמר והחכמה מאין תמצא הרי נמצאת מבחי' אין שלמעלה מן ההשתלשלות. היינו רק שנמצאת מבחי' אין אבל לא שהחכמה עצמה בחי' אין אלא שמאין תמצא והיינו שתמצא מאין ליש בבחי' ראשית הגלוי שבה שורה אור א\"ס כמ\"ש ה' בחכמה כו' אבל לא אין ממש וד\"ל. וזהו שבמשה נאמר שהיה כבד פה וכבד לשון ואמ' בזהר כבד פה תושבע\"פ וכבד לשון תושב\"כ כו' לפי ששרש נשמתו היה בבחי' מקור החכמה שבבחי' אין ממש וכמ\"ש מן המים משיתהו מבחי' מים עליונים שמעל לרקיע כו' וז\"ש ונחנו מה מה ממש וע\"כ ניתנה התורה על ידו כמ\"ש וגם דלה דלה לנו דלה מים דאורייתא ואורייתא מחכמה נפק' מבחי' חכמה שנק' ראשית וכמארז\"ל בראשית בשביל התורה שנק' ראשית כו' שמאין תמצא ולא אין ממש ע\"כ היה כבד פה ולשון בתושב\"כ ושבע\"פ שהיתה בחי' ירידה אצל נשמתו מלבוא בגלוי מן ההעלם דפנימית חכמה בפה ולשון כו' וד\"ל. והנה בזאת יש יתרון מעלה לקיום המצות על ד\"ת להיות ששרש התורה מחכמה נפקת שנק' ראשית הגלוי שבה מתגלה אא\"ס להיות מקור להשתלשלות כל העולמות אבל זהו בחי' ממלא כ\"ע בלבד שמתלבש אור האלקי בתוך כ\"ע בכל עולם לפי מדריגתו במיעוט אחר מיעוט כו' כידוע אבל שרש המצות המלובשים בדברים גשמיים דוקא כמו תרומות ומעשרות כו' וציצית ותפילין בקלף וצמר גשמי וכה\"ג הרי בהן נמשך ומלובש מבחי' הארת סוכ\"ע דוקא שלמעלה מעלה מבחי' ממלא כו' גם מבחי' ראשית דממלא כ\"ע כו' שהוא החכמה שמאין תמצא אבל לא אין ממש כנ\"ל משא\"כ בחי' סובב זה הוא בבחי' אין האמתי דעצמות אא\"ס שנק' מקיף הכללי שמקיף לד' עולמות דאבי\"ע בשוה וע\"כ נק' בשם סובב כו' כי הנה בחי' ההארה והמשכה מבחי' מקיף זה אינו בא בבחי' התלבשות בגלוי גמור בתוך כ\"ע כמו בחי' ממלא הנ\"ל שאין זה כמו התלבשות ראשית הגלוי דחכמה במדות ומדות במחשבה דו\"מ וכה\"ג אלא רק בבחי' הארה בעלמא בבחי' אין בהעלם כו' שאם היה בחי' הארה זו דסובב כו' באה בגלוי בהתלבשות גמור בעולמות כמו בחי' ממלא כו' היו כל העולמות מתבטלין ממציאותם ולא היה באפשרי להיות בחי' השתלשלות עו\"ע כלל ולא היה בא כל מציא' מאין ליש כלל כי היו כולן בטלים ונכללין במקורן ושרשן הראשון מקורא דכולא בחי' עצמות אא\"ס כו' וגם בחי' חכמ' ראשית הגלוי הנ\"ל לא היה באפשר שתמצא מאין ליש בבחי' מציאת דבר שתקרא בשם חכמה כי מאחר שנק' בשם חכמה הרי הוא בבחי' מציא' דבר מה עד שהוא עולה בקריא' שם בפ\"ע כו' אבל היה הכל כלול בבחי' אין האמתי ולא היה דבר חוץ ממנו כלל בבחי' מציא' דבר מה כו' כי כשמו כן הוא שאין לו סוף כו' וד\"ל:\n(ג) <b>וביאור</b> ענין בחי' התכללות זאת של כל ההשתלשלות בשרשן ומקורן יובן ע\"ד בחי' התכללות המדות בשכל כמו עד\"מ שאנו רואים שהגם שהמדות מתהווים מן השכל במציאה בפ\"ע משכל המולידן מ\"מ קודם שנולדו"],[2201340112,"הרי היו כלולים בשכל ומתאחדים בו והיו בטלים שם בתכלית עד שאינן עולות שם בשם בפ\"ע לקרותן בשם מדות כלל ואין נופל עליהם קריאת שם מדות רק לאחר שיצאו מן ההעלם לגילוי מהות בפ\"ע וכמו\"כ גם בחי' החכמה מקור המדות קודם שתמצא מאין ליש במהות חכמה היתה כלולה בבחי' אין ממש בתכלית הביטול וההתכללות ולא היתה עולה בשם חכמה כלל רק אחר יציאתה מן ההעלם לגלוי הוא שנק' בשם חכמה כו' וא\"כ כל מה שמסתעף מעילה לעילה כל עלול היה כלול תחלה בעילתו כך כל העלולים מחכמה ולמטה כולם הם כלולים ובטלים בבחי' אין האמתי מקור החכמה ואם היה גלוי הארה משם בבחי' גלוי גמור לא היה באפשרי להיות בחי' השתלשלות עילה ועלול אלא שהארת הסובב הוא בהעלם בתוך כ\"ע כו' כדי להיות בחי' השתלשלות עו\"ע ממהות למהות כו' וד\"ל. אך הנה יש הפרש בזה דדוקא בבחי' השתלשלות בבחי' אור הרוחנית ופנימית החיות הנמשך מעילה לעילה שם מוסתר הארת הסובב כו' מטעם הנ\"ל אבל בבחי' התהוות כל עלול בבחי' יש חיצוני עד שנראה במציא' יש לדבר ממש בזה דוקא ההארה באה מבחי' סובב ולא מבחי' ממלא ואם לאו לא היה במציא' יש כ\"כ רק שאין האור מבחי' סובב בגלוי גמור אלא בהעלם מטעם הנ\"ל:\n(ד) <b>וזהו</b> הכלל בכל ההשתלשלות מריש כל דרגין שהוא בחי' חכמה ראשית הגלוי הנ\"ל עד סוף כל דרגין שבסוף עולם העשיי' בהתהוות הגשמיות דדצ\"ח מן הרוחניות דהנה ודאי א\"א לומר שהתהוות הגשמיות מן הרוחניות היא באה דרך כל עו\"ע שיש ערך ויחוס לעלול עם העילה שהרי אין ערך כלל לגשמיות העשב לגבי רוחניות דכח הצומח. וכה\"ג בחלק החי בהתהוות מהות חיות גופנית דגוף הבהמה גם ששרשה הוא מבחי' פני שור שבמרכבה היינו בחי' רוחניות האור והחיות שלה אבל גוף הבהמה וגוף כל בע\"ח שהוא גשם יש גמור איך נתהווה מבחי' הרוחנית כו' וכן בכל עו\"ע העליונים גם שנתהווה העלול מן העילה היינו בחי' אור הרוחנית שלו אבל בחי' גשמיות וחיצוניות שלו מה שנראה יש ודבר במציא' הוא מבחי' סובב מלמעלה מכל ההשתלשלות ולא מכח העילה שלו כלל עד גם בראש ומקור כל ההשתלשלות שהוא בחי' החכמה שמאין תמצא כנ\"ל יש הפרש זה דמה שיש שרש ומקור לחכמה בבחי' אור וחיות רוחני מבחי' האין כמ\"ש והחכמה מאין תמצא ה\"ז בא בבחי' השתלשלות דבחי' ממלא רק שנק' ראשית הגלוי כנ\"ל באריכות אבל מה שהחכמה היא בבחי' יש במציא' דבר מה אין זה בא מכח ההשתלשלות דבחי' ממלא כו' אלא מבחי' סובב דוקא ע\"כ נמצאת החכמה מאין ליש במציא' יש עכ\"פ וכן בכל העלולים המסתעפים מחכמה ולמטה עד התהוות דצ\"ח כל מה שבא הדבר במציאות יש הוא נמשך מבחי' סובב שלא בדרך השתלשלות דממלא כלל אלא בדרך דילוג וע\"כ שוה ומשוה ראש וסוף וכמ\"ש בע\"ח שמקיף ד' עולמות בשוה ממש אצי' ועשי' כו' רוחניות וגשמיות שוין קמיה כמ\"ש כחשיכה כאורה כו' כי אין הפרש לגבי בחי' הארת הסובב בין התהוות יש בראשית דחכמה להתהוות יש הגשמי' דדצ\"ח מן הרוחניות שנק' סוף שמקיף לכולם בשוה ממש מפני שההארה וההמשכה מבחי' סובב זה אינה באה בבחי' התלבשות והשתלשלות כהתלבשות השכל במדות וכה\"ג אלא בבחי' סובב ומקיף מלמעלה בבחי' ההעלם והאין כו' וזהו שכל בריאה נקראת בריאה מאין ליש ואין הכוונה על בחי' ממלא אלא על בחי' סובב שנק' אין האמתי והיינו יש מאין ממש שלא בדרך השתלשלות אלא בדרך דילוג כמ\"ש קול דודי כו' מדלג כו' והיינו מה שנתהווה כל בריאה בבחי' יש ממש דוקא שזה נמשך מבחי' אין ממש דבחי' סובב דוקא כנ\"ל וד\"ל:\n(ה) ובכל זה יובן שיש יתרון מעלה בקיום המצות על ד\"ת וזהו שא'"],[2201340113,"תכלית חכמ' תשובה ומעש\"ט וכן הלומד ואינו עושה כנ\"ל להיות שבחי' החכמה הוא רק בבחי' ההשתלשלות דממלא רק שנקראת ראשית כנ\"ל אבל עכ\"פ נמנית ראשונה מפני שהיא ראשית לשני' ושלישית כו' א\"כ גם היא מן המנין כנ\"ל וראוי למנות אחריה שני' ושלישית כו' אבל שרש קיום המצות המלובשות בדברים גשמיים דוקא הרי שם הוא בחי' המשכת גלוי אא\"ס שבבחי' סוכ\"ע הנ\"ל ואע\"פ שאין ההארה משם באה בבחי' גלוי גמור רק בהעלם מטעם הנ\"ל שאינו בגדר עלמין ואינו נמשך ממנו רק בבחי' הארה בעלמא בבחי' אין והעלם ממש מ\"מ מאח' ששרש זה הוא מבחי' הסובב שמקיף לד' עולמות בשוה כנ\"ל ה\"ז למעלה הרבה מבחי' ממכ\"ע הנמשך בבחי' השתלשלות עו\"ע כנ\"ל אך לא מצד בחי' הארת סובב בבחי' היש של כל הנמצאים דוקא כנ\"ל והמצות הן מלובשי' בבחי' יש ודבר כו' שא\"כ גם בלא מצוה הרי בבחי' התהוות כל יש ודבר יש ההארה מבחי' סובב כנ\"ל אלא דוקא מצד בחי' המצות המלובשות בדברים גשמיי' כי המצות הן בחי' רצון העליון שלמעלה ששם גלוי בחי' סובב דוקא בלי הסתר פנים ולבוש מסתיר כלל וכלל כידוע שהוא ופנימית רצונו א' ממש רק בירידת והתלבשות הרצון העליון למטה במצות המלובשים בדברים גשמיי' שם בא האור הזה בלבוש דמעשה המצו' אמנם אע\"פ שהמצוה מלובשת בדבר גשמי כמו בקלף גשמי כו' אין הגשמית מסתיר ממש לגלוי האור דסובב אלא שנעשה בחי' לבוש וכלי כמו עד\"מ הדבר הנגנז באוצר כו' ולע\"ל יתגלה מתוך הלבוש הזה דוקא וכמ\"ש ולא יכנף עוד כו' (וכידוע דמצוה הוא שם הוי' בא\"ת ב\"ש) משא\"כ בשאר כל המעשים אשר לא לה' המה גם שיש בהן בחי' הארה דסובב בהעלם כנ\"ל מ\"מ הרי הוא בבחי' הסתר גמור שם ואין שם בחי' גלוי פנימי' אורו כלל אדרבה נראים ליש ודבר בפ\"ע כו' אבל דברים גשמיים שנעשה בהן המצות הרי הן בחי' כלי ולבוש לבחי' רצון העליון ששורה בהם ממש שבזה יש בחי' סובב הנ\"ל בבחי' פנימית אורו כו' ודוקא מפני שהמצוה מלובשת בגשמית ששם הוא הארת סובב דוקא שהוא בחי' מקיף לד' עולמות בשוה כנ\"ל ובזה יש יתרון מעלה לקיום המצות בדברים גשמיי' על בחי' חכמה דתורה וזהו שא' תכלית חכמ' תשובה ומע\"ט דוקא והלומד ואינו עושה כו' כי המעשה עיקר מטעם הנ\"ל וד\"ל. וזהו ענין יביאו לבוש מלכות שהוא ענין מ\"ש ה' מלך גאות לבש כו' כנ\"ל דהנה בחי' ההארה וההמשכה דבחי' סובב כ\"ע הנ\"ל שהוא בחי' הארה בעלמא בחי' אין ממש ולא מתלבש בתוך כ\"ע הוא מ\"ש ה' מלך גאות וזהו יחיד חי העולמים כו' שזהו בחי' יחיד ומיוחד שלמעלה מבחי' אחד כידוע שפי' יחיד היינו שהוא לבדו ממש כמ\"ש אתה ה' לבדך כו' וגם אחר ברה\"ע הוא כמו קודם בה\"ע כמ\"ש אני ה' לא שניתי כו' ואין דבר חוץ ממנו שיפול בו לשון ביטול ויחוד שמתייחד ומתאחד דבר בעצמות כו' אבל בחי' אחד הוא שמתאחד ה\"ז מורה על בחי' המשכת יחודו בז' רקיעים וארץ או כמאמר רז\"ל תמליכהו בשמים ובארץ וד' רוחות העולם שהוא בחי' ו\"ק מעלה ומטה כו' שנק' מקום שבטל ונכלל למעלה בבחי' יחוד עליון בבחי' ביטול והתכללות ממש כמ\"ש לך ה' הגדולה והגבורה כו' וכידוע. אבל בחי' יחיד היינו יחוד עצמותו האמתי וכמא' אנת הוא חד ולא בחושבן כו' לא בחושבן י\"ס כי עצמות אא\"ס פשוט בתכלית כו' ואין עוד מלבדו וכולא קמי' כלא חשיבי כו' ומה שנמשך להיות חי העולמים עולם הנאצל ועולם הנברא כו' הוא רק בחי' האחרונה שבעצמותו שהוא אשר עלה במחשבה הפשוטה אנא אמלוך כו' והוא הנקרא בחינת מל' דא\"ס וה\"ז עד\"מ בחינת מלוכה למטה שהוא רק בחי' התפשטות חצונית מעצמותו כי אין עיקר המלוכה רק התפשטות שמו שנקרא בשם מלך עליהם והוא אשר מקבלים העם עול"],[2201340114,"מלכותו וממשלתו שאין בזה תפיסה למהותו ועצמותו של מלך כו' כמו\"כ למעלה אין ההארה מעצמות אא\"ס להיות נתפס באבי\"ע אלא רק בחי' שם מלכותו נתפס ומלובש בהם והוא מ\"ש מלכותך מלכות כ\"ע שהוא בחי' מל' דא\"ס וע\"ז אמר המלך המרומם לבדו כו' שהוא בחי' סוכ\"ע הנ\"ל שמרומם ומתנשא מימות עולם אך בבחי' התנשאות זאת שבבחי' מלוכה אנא אמלוך מזה נמשך להיות בחי' מקור כל חי העולמים בבחי' סוכ\"ע עכ\"פ שמזה עיקר קיום היש הגשמי כנ\"ל רק שמאיר מרחוק ובהעלם שזהו ענין יש מאין ממש כנ\"ל דהיינו בבחי' ההתנשאות דבחי' מל' הנ\"ל שהיא הארת אין ממש מבחי' העצמות כנ\"ל כי הוא לבדו מרום וקדוש כו' כנ\"ל וד\"ל וזהו ה' מלך גאות לבש שנתלבש בבחי' גיאות והתנשאות דבחי' המל' להיות בבחי' מלך על עם המאירה ומתפשטת בעולמות מאין ליש ממש שזהו עיקר קיום היש הגשמי כנ\"ל וד\"ל. אך אין זה הגיאות וההתנשאות רק בבחי' לבוש שנתלבש במחשבה זו דאנא אמלוך והיא בחי' אחרונה לגבי מהו\"ע ממש שזהו רק מפני כי חפץ חסד הוא ורוצה בקיום העולמות ממקורן ושרשן וז\"ש אף תכון תבל בל תמוט שכדי להיות תכון תבל בקיום חזק בל תמוט ע\"כ נתלבש בלבוש גיאות דבחי' המל' שמזה דוקא נמשך קיום היש הגשמי כנ\"ל וד\"ל:\n(ו) <b>וזהו</b> יביאו לבוש מלכות אשר לבש בו המלך פי' לבוש מלכות הוא בחינת לבוש מלכות דא\"ס שנתלבש בו בבחי' גיאות והתנשאות להיות מלך כו' וכמ\"ש ה' מלך גיאות לבש כו' אך מ\"ש יביאו יביאו זה היינו שיביאו מלמטה למעלה דוקא משום דבחי' לבוש מלכות זה באתערותא דלתתא תליא דהיינו בחינת מחשבה זו דאנא אמלוך שמתלבש בלבוש גיאות והתנשאות להמשיך בחינת מל' בכל העולמות באתדל\"ת דוקא תליא מלתא כי הרי מאחר שמצד עצמותו ממש גם בחי' מחשבה זו דאנא אמלוך כלא חשיבי כו' דעל מי ימלוך מאחר שאין עוד מלבדו כלל כנ\"ל אלא הענין הוא משום דסוף מעשה עלה במחשבה תחלה דהיינו מה שעלה לו רצון ומחשבה זו דאנא אמלוך היינו מפני סוף מעשה דוקא שנתאוה להיות לו דירה בתחתונים ע\"י המצות המלובשים בדברים גשמיים דוקא כגון ציצית גשמיי' ותפילין גשמיים וכה\"ג שבזה יאיר ויתגלה מבחי' עצמות אא\"ס בגלוי גמור בלי הסתר פנים ולא כשאר המעשים אשר לא לה' כנ\"ל משום דגם שהדברים הגשמיים ההם נתונים תחת ממשלת נוגה דעשי' מ\"מ אינן מסתירים לאור העליון מפני שנעשים בחי' כלי ולבוש להשראת אור העליון וכמו התפילין שנק' תשמישי קדושה וציצית תשמישי מצות שאסור לנהוג בזיון בהם גם בגשם הקלף והצמר כו' מפני שנתקדשו בקדושת אור האלקי השוכן בהן כו' וע\"כ המצות נק' מצות המלך שבחי' מל' דא\"ס מלובש בהן שלזה עלה במחשבה בחי' מלוכה וזהו לבוש מלכות אשר לבש בו המלך בחינת מל' דא\"ס שנק' מלך מלכי כו' וד\"ל אך יביאו לבוש מלכות שיביאו לו מלמטה באתדל\"ת שכדי שיהי' לו רצון ותענוג במחשבה זו דבחי' המל' באתדל\"ת תליא מלתא שמעוררים אותו מלמטה ע\"י קיום מצות המלך שע\"י סוף מעשה זו עולה מחדש בחי' הרצון והתענוג במחשבה שיהיה מלך והוא שמביאים לו לבוש מלכות להיות ה' מלך גאות לבש כו' וד\"ל:\n(ז) <b>אך</b> הנה יש עוד הפרש בענין המצות עצמן בין המצות כמו שהן קודם שנעשים במעשה בגוף האדם כמו התפלין והציצית כמו שהן נעשין מדברים גשמיים דצמר וקלף קודם שנעשה בהן קיום המצוה בפ\"מ שהוא ללבוש התפילין והציצית על גוף האדם וכן האתרוג כמו שהוא כאשר נלקח למצוה קודם שיקיימו בו מצות נטילת לולב וכה\"ג בכל דברים הגשמיי' שמהן נעשין המצות"],[2201340115,"טרם שמקיימין אותן ובין קיום המעשה של כל המצות אשר יעשה אותם בגופו ומאודו כגון בלבישת הטלית והתפילין בגופו ונתינת הצדקה בפ\"מ וכה\"ג בנטילת לולב ואתרוג ותקיעת שופר וכיוצא שבמצות מצד עצם מהותן כמו שהן שמפני שבהן שורה מבחי' רצון העליון והן נעשים מדברים הגשמיים שהוא יש גשמי אשר שרשו מבחי' סובב ע\"כ ודאי שורה בהן מבחי' מקיף העליון שמקיף לד' עולמות בשוה שהוא בחי' מל' דא\"ס שממנו נמשך בחי' ההתנשאות והגיאו' להיו' מלך כו' והתנשאות זו היא מאירה בבחי' מקיף מרחוק ולא בגלוי מקרוב כדי שלא יתבטלו העולמות במציאות כנ\"ל וכידוע שבחי' ההתנשאות הוא מצד עצמו בבחי' הסתלקות וריחוק האור מן המקבלים שלא יאיר בקירוב שלא יתבטלו ממציאות שלהם כמו הושיט אצבעו קטנה ביניהן ושרפן וכיוצא רק באמצעות התנשאות זו שמתנשא ומתרומם מכל עלמין הרי הוא בחי' מלך עליהם וידוע שבבחי' מל' זאת שמאיר עליהם מזה נמשך עיקר מקור החיות שלהם מאין ליש גשמי דוקא והוא ענין ובחי' סובב המקיף לד' עולמות בשוה כנ\"ל וד\"ל אבל בקיום המצות אשר יעשה אותם האדם בגופו כנ\"ל הנה ההארה וההמשכה באה מלמעלה מבחי' מל' דא\"ס שנעש' מקיף כללי כו' דהיינו מבחי' כתר מל' דא\"ס שהוא בחי' התענוג הפשוט לבחי' המל' למה ירצה בבחי' ההתנשאות דמלוכה זאת כו' שהוא ענין סוף מעשה דקיום המצות בפ\"מ דוקא כנ\"ל שעלה בתחלת המחשבה והרצון כנ\"ל שהוא בחי' כתר מל' דוקא כידוע וזאת ההארה הגדולה של בחי' התענוג והרצון הפשוט שבבחי' כתר מל' דא\"ס מאיר בכל נפש מישראל בעשותו א' ממצות ה' בגופו ובמאודו בפ\"מ דוקא להיות שהגם שמעשה המצות היא נעשה בעשיה גשמית מ\"מ הרי מבחי' מעשה זו דוקא נעשה בחי' כתר ועטרה לבחי' המל' למעלה בעצמות אא\"ס משום שמזה נתעורר ונעשה בחי' העונג העליון הפשוט שבעצמות שיאיר בבחי' כתר ועטר' על בחי' מל' וכמו שא' נח\"ר לפניו שאמר ונעשה רצונו. שנעשה בחי' עונג ונח\"ר לפני עצמותו ממש על אודות קיום רצונו במצות בפ\"מ שזהו הנק' כתר מל' (כידוע דהרצון בפרט הוא המורכב בשכל וטעם כו' והן תרי\"ג ארחין כו' שמלובשים בח\"ס חכמה שבכתר אבל בחי' נח\"ר לפניו מאשר עשו רצונו זה מגיע בבחי' רצון ותענוג הפשוט מקור כל הרצונות כו' ע\"כ נח\"ר לפניו על אשר מקיימים רצונו יהיה מה שיהיה כו' הרי אין זה רצון פרטי מורכב כו' וכמ\"ש בסמוך בענין נעשה ונשמע כו' והוא בחי' כתר שבכתר שזהו בחי' כתר מל' דהיינו שנמשך מזה בחי' התענוג והרצון למלוכה כו' ונמצא מאחר שקיום הרצון בכלל במצות בפ\"מ הוא שעושין נח\"ר לפניו כו' הרי מזה מוכרח שלזה היה כל עיקר הרצון במחשבה דאנא אמלוך שהוא סוף מעשה שעלה במחשבה תחלה כו' כנ\"ל וד\"ל) ובחי' נח\"ר ועונג העליון הזה שנק' כתר מל' למעלה הוא המאיר על כל נפש מישראל ומתגלה בה בעשותו אחת מכל מצות ה' וזהו ישראל אשר בך אתפאר בעצמי בבחי' פאר ותפארת הכתר והעטרה שנעשה ע\"י קיום המצות כנ\"ל וד\"ל:\n(ח) <b>וזהו</b> ואשר נתן כתר מל' בראשו שזהו ענין מ\"ש במ\"ת בעטרה שעטרה לו אמו כו' כנ\"ל דהנה בשעת מ\"ת אמרו נעשה ונשמע כו' ופי' נעשה הוא קיום הרצון בפ\"מ בלא טעם ושכל מאחר שלא שמע עדיין כו' אשר מזה נעשה למעלה בחי' נח\"ר ועונג לפניו ממש שא' ונעשה רצונו כנ\"ל שזהו בחי' עטרה וכתר ע\"ג הראש ועד\"מ הכתר והעטרה גשמי' שעושין למלך מאבנים טובות שהאבני' הגם שהם בחי' דומם גשמי מ\"מ כשמאירין ומבהיקים נעשין לפאר והוד גדול בראש המלך עד שמתפאר ומתענג בעטרה זו והיא עיקר המלוכה שלו שהרי המלך בלא עטרה הנק' כתר מל' אינו מלך וכשירצה לשפוט"],[2201340116,"את העם בבחי' מלוכה אז יתן כתר מל' בראשו וישב על כסא ממלכתו כו' וכן יובן למעלה שבשעת מ\"ת כשאמרו ישראל נעשה כו' עשו לו בחי' עטרה וכתר מל' מבחי' קיום המצות אשר יעשה האדם בגופו דוקא כנ\"ל הגם שהן מלובשות בגשמיות ה\"ז כמו בחי' אבנים טובות שהן בחי' דומם ומ\"מ נעשים עטרה ביופי גדול של הוד מלכות כן מקיום המצות בפ\"מ דוקא נעשה בחי' עטרה וכתר בראשו של הקב\"ה דהיינו בחי' העונג ונח\"ר לפניו שאמ' ונעשה רצונו ומפני שנח\"ר זה מלובש בקיום המצוה שבדברים גשמיי' ע\"כ נמשל לבחי' עטרה גשמי' הנעשה מאבנים גשמיי' כו' וזהו בעטרה שעטרה לו אמו בשעת מ\"ת דוקא ונמשך עי\"ז ב' כתרים לכ\"א מישראל א' כנגד נעשה כו' וגם עכשיו בעשות אדם א' מכל המצות בגופו ומאודו נמשך ומתגלה על נפש האדם ממש בחי' עטרה וכתר עליון כמ\"ש כצנה רצון תעטרנו כו' וזהו ואשר נתן כתר מל' בראשו ע\"י קיום המצות בפ\"מ שהוא בחי' מקור לבחי' לבוש מל' אשר לבש בו המלך שזהו ענין המצות עצמן כמו שהן טרם שמקיימין אותן בפ\"מ כנ\"ל ותחלה יביאו לו לבוש מל' כנ\"ל ואח\"כ ניתן כתר מל' בראשו ע\"י קיום המצות בפ\"מ (ומ\"ש למעלה בפי' יביאו לבוש מל' מלמטה שהוא ג\"כ לעשות ענין התעוררות הרצון והתענוג במלוכה ע\"י קיום מצות המלך שנקרא סוף מעשה כו' היינו שיומשך בחי' רצון ותענוג גם בלבוש מל' שהוא בחי' ההתנשאות דאין מלך בלא עם כו' אך זהו כמו טפל לגבי העיקר של הכתר מל' שהוא מה שנח\"ר הוא לפניו שא' ונעשה רצונו ע\"י קיום המצות שמזה נמשך ג\"כ הארה פרטי' להתלבש בלבוש מל' כו' שהן המצות עצמן שנק' רצונו כו' וד\"ל):\n(ט) <b>ובכל</b> זה יובן מארז\"ל כל הנביאים עתידים להבטל חוץ ממגלת אסתר שנאמ' וימי הפורים האלה לא יעברו כו' וכן ההלכות אינן בטילין לעתיד ולהבין ענין ביטול הנביאים אין הכוונה על ביטול הנבואה מישראל ח\"ו דאדרב' יתוסף רוח נבואה בישראל שישפוך את רוחו על כל בשר ונבאו בניכם ובנותיכם כו' כי כולם ידעו אותי כו' אלא ר\"ל שבחי' גילוי אור האלקי שבנביאים יהיה קטן בערך מאד לגבי עוצם גילוי אור רב שיהיה לעתיד עד שיהיה בטל כמו ביטול והתכללות זיו השמש בשמש עצמו שעם היות שזיו השמש אורו גדול ורב במקורו ביתר שאת מן האור המאיר לארץ ולדרים עליה מ\"מ במקורו ממש בשמש עצמה הרי הוא בטל מחמת אור עצמי שבגוף השמש מפני שאור עצם השמש רב ונעלה בערך הימנו ולהיותו מקורו ושרשו של אור וזיו השמש כו' וכן כל בחי' גילוי אור הנבואה שבנביאי' עתידים להבטל ולהכלל באור העצמי שהוא בחי' עצמו' אא\"ס ממש שיתגלה לעתיד שממנו נמצא מקור האור האלקי המתגלה בנביאים וכמ\"ש כי עמך מקור חיים כו' וזהו כל הנביאים עתידים להבטל חוץ ממגלת אסתר כו' והענין הוא כי אמרז\"ל אסתר מן התורה מנין שנאמר ואנכי הסתר אסתיר פני ביום ההוא לשון נסתר כידוע שכל הוא ל' נסתר וביום ההוא שהן בחי' עלמין סתימין דלא אתגליין לפי שהשכינה כשהיא בגלות בע' שרים נק' אסתר שמסתתרת ומתעלמת בלבוש שק דע' שרים ואז עולה להסתר בעלמין סתימין דלא אתגליין (כמ\"ש יונתי בחגוי הסלע בבחי' הסתר וכמ\"ש בע\"ח דמל' דאצי' בבריאה נק' אסתר שמסתתרת בראש הבריאה כו' ודוקא בהיותה בגלות בע' שרים דנוגה שאז בהכרח שלא תשפיע להם רק מבחי' החיצוניות והאחוריים בלבד ובחי' הפנימי' שבה נאמר וכבודי לאחר לא אתן אלא עולה למעלה מעלה להסתר בעלמין סתימין דוקא שנקרא ביום ההוא דלא ידיע בשם כלל והוא למעלה משם הוי' דחכמה דהיינו בשם אהיה דכתר שהוא גי' סלע במילוי כו' כמ\"ש במ\"א בענין ושים בסלע קנך כו') וזהו אסתיר פני בחי' הפנימי' ביום ההוא בעלמין"],[2201340117,"סתימין דבחי' ע\"י וא\"א כו' וד\"ל) והנה לעתיד כתיב ואמר ביום ההוא הנה אלהינו זה קוינו לו כו' פי' לעתיד יהי' בחי' התגלו' ההעלם דיום ההוא כמ\"ש יחיינו מיומים ביום השלישי יקימנו ונחיה לפניו בבחי' גלוי (כי יהי' בחי' גילוי אור א\"ס שבכתר שנק' יום ההוא ונק' יום השלישי שלמעלה מחו\"ב שנק' יומים כו' כמ\"ש במ\"א) וזהו ואמר ביום ההוא הנה אלקינו זה לנוכח שמבחי' הוא הנעלם וסתום יבא לידי גלוי עד שיאמרו לו הנה אלקינו זה לנוכח לפי שמאיר אא\"ס שהיה מסתתר ונעלם בבחי' עלמין סתימין כנ\"ל בפי' אסתיר פני ביום ההוא לבא לידי גלוי למטה בבחי' עלמין דאתגליין דוקא ולכאורה ב' הפסוקים הללו סותרים זא\"ז דביום ההוא ודאי לעתיד הוא וכאן אמר שיסתיר פניו ביום ההוא בבחי' עלמין סתימין וכאן אמר ואמר ביום ההוא הנה אלקינו זה בעלמין דאתגליין כנ\"ל אך הענין הוא שיש עוד מדריגה שלישית מלבד עלמין סתימין ועלמין דאתגליין והוא ענין סתימ' דכל סתימין שגם בעלמין הסתימין הוא סתום ונעלם ממש כערך הסתימין לגבי דאתגליין כו' (וזהו יחיינו מיומים עלמין סתימין בחי' ע\"י וא\"א וביום הג' הוא בחי' רדל\"א כידוע בכוונת דב\"ש כו' בחי' רדל\"א ברוך הוא בחי' ח\"ס כו' והוא ענין תלת רישין כו' כמ\"ש במ\"א):\n(י) <b>והנה</b> יש הפרש בין זמן הגלות לעתיד לבא שבזמן הגלות כתיב אסתיר פני ביום ההוא שגם בבחי' יום ההוא הסתום ונעלם שנק' עלמין סתימין יהי' מוסתר ונעלם והוא הנק' בחי' סדכ\"ס (או רדל\"א כו') ולעתיד נא' הנה אלקינו זה שמבחי' יום ההוא בלבד יבא לידי גלוי שמבחי' הוא נעשה זה לנוכח אבל אין כל זה רק בבחי' עלמין סתימין שיבאו לידי גלוי ולא למעלה מהם שסתום גם מהם משא\"כ בזמן הגלות שמסתיר פניו גם ביום ההוא כלומר שנסתר ונעלם גם בהיותו מלובש בעלמין סתימין שנק' ביום ההוא וזהו שאמרז\"ל כל שאינו בהסתר פנים אינו מהם כו' שמבחינת הסתר פנים זה שמוסתר גם ביום ההוא כשבא לידי גלוי ה\"ז ממקום גבוה ונעלה הרבה יותר מבחינת הגלוי דלעתיד כמ\"ש הנה אלקינו זה כו' וזהו ענין מגילת אסתר שלא תבטל גם לעתיד וזהו מ\"ש אסתיר פני גם ביום ההוא שיובן גם כפי פשוטו דביום ההוא הזה לעתיד שאז ג\"כ יהיה מוסתר אע\"פ שאז יהי' גלוי דיום ההוא להיות בבחי' זה להיות מגלת אסתר שרשו למעלה גם מבחי' עלמין סתימין עד שגם שם הוא מוסתר ונעלם וד\"ל. וכן ההלכות לא יבוטלו לעתיד דהיינו ג\"כ ע\"ד הנ\"ל שגם לעתיד שיהיה בחי' גלוי הנעלם דיום ההוא אבל ההלכות יהיה בבחינת ההסתר גם לעתיד ביום ההוא לפי ששרשן למעלה מבחי' עלמין סתימין שהוא בבחי' סדכ\"ס כנ\"ל וד\"ל. וזהו כל הנביאים עתידים להבטל כמו ביטול זיו השמש בשמש כנ\"ל דאע\"פ ששרש כל הנבואה נמשך מבחי' עלמין סתימין שבא לידי גלוי במראה הנבואה כמ\"ש ה' במראה אליו אתודע כו' אבל מ\"מ אינו רק בחי' זיו והארת עצמו' המאציל בלבד שבטל ונכלל בעצמות שנקרא מאור כו' אבל מגילת אסתר וההלכות שרשן למעלה מבחי' זיו ואור אלא בבחי' המאור עצמו שהוא בבחי' עצמו' המאציל שנמשל לגוף השמש שנקרא סדכ\"ס (או רדל\"א) שאין לו ביטול והפסק כי הוא נצחי בבחי' נצחיות דעצמיות אא\"ס ואדרבה כל נהורין מתחשכאן קמיה וכמ\"ש דאפי' אור צח (בחי' ח\"ס דא\"א) (אור מצוחצח (בחינת מו\"ס דע\"י) אוכם הוא לגבי עה\"ע (בחי' רדל\"א) ולמעלה יותר גם בחי' מחשבה וחכמה דא\"ק לית מח' ת\"ב מפני שנקרא קדמון לכל הקדומים והוא ענין סדכ\"ס שכולל הכל כו' וד\"ל):\n(יא) <b>וזהו</b> שאמרז\"ל מרדכי מן התורה מנין דכתיב מר דרור ומתרגמינן מרי דכיא פי' מרי דכיא בחי' מרירות שממקום טהור. דהיינו בחי'"],[2201340118,"ההלכות שנאמר בהן הליכות אלי הליכות עולם לו כו' להיותן בחי' דבר ה' ששרשו אחוז וקשור בבחי' עצמות המאציל ממש ע\"כ בהן דוקא בחי' הילוך עצמותו ממש ולכן נק' הלכות עד\"מ המלך כשהולך הרי כל מהו\"ע בהליכה זו וכן הוא מ\"ש הליכות אלי כו' אף בחי' התלבשות הליכות הללו הוא בדברים גשמיים שהן בבחי' פסולת הגסות דעוה\"ז שנק' מר בחי' גבורות קשות דנוגה שנאמר בהן אשכלות מרורות כו' וכל התורה הוא לאהפכא מרירו למיתקא שהיא לטהר ולטמא כו' כמו כל הלכות טומאה וטהרה וז\"ש להבדיל בין הטמא ובין הטהור הרי גם בשקצים טמאים נתלבשו ההלכות שהן בבחי' הבירורים דבחי' מרירו דנוגה ע\"כ נקרא מרי דכיא בחי' מרירות שבא' ממקום טהור שהוא הכח מה שבחכמה אתברירו כל בחי' מרירות קשות רע דנוגה שזהו נק' דכיא כי אין טהרה רק לעולה מן הטומאה וז\"ש מי יתן טהור מטמא לא אחד בחי' ח\"ע דאחד היורדת למטה לברר כו' לרחק את הרחוק כמו לטמא את הטמא וטמא טמא יקרא ולטהר את הטהור כו' ע\"כ נק' מרי דכיא וד\"ל. וזהו ששה חדשים בשמן המור וקאי על הנשמה האלקית בבואה לג\"ע כמ\"ש ז\"ל שמכריזין בג\"ע אשרי מי שבא לכאן ותלמודו בידו שלא תוכל לבא כ\"א ע\"י ששה חדשים בשמן המור שזהו בחי' עסק ההלכות שמלובשות בענין גשמי בבחי' מור ומרירות דגסות וחומריות עוה\"ז להבדיל בין הטמא כו' ולפי שבח\"ע דוקא בא בחי' בירור זה ע\"כ נקרא שמן המור פי' שמן שרשו בח\"ע במקור החכמה וכמו שמן המעורב במור שנקלט השמן במור ומריח ריח טוב כו' כן הוא אחר הבירור דח\"ע במור דנוגה שעולה בבחי' ריח טוב כו' ע\"כ ששה חדשים תעסוק הנשמה בשמן המור הזה וששה חדשים בבשמים כו' בהשגות פנימית התורה כו' ובחי' שמן המור הזה הוא ענין מרי דכיא שהן ההלכות וע\"כ לא יבוטלו לעתיד וזהו שא' מגלת אסתר שכולל בזה גם מרדכי שנאמר וימי הפורים לא יעברו כו' וד\"ל אך לכאורה אין זה מובן כלל שהרי לעתיד יהיה לאחר תשלום כל הברורים דרפ\"ח כו' א\"כ למה צריך לשמן המור שהוא בחי' הבירורים שבח\"ע ולמה אמר גם בהלכות שהוא בחי' מרדכי שלא יבוטלו לעתיד ויהיו מוסתרים גם ביום ההוא דלעתיד גם שיבא אז לידי גלוי כנ\"ל:\n(יב) <b>אך</b> הנה יש להקדים לזה שלשה משלים הא' כמשל האבוק' הגדולה שמאירה למרחוק שכל שהאבוקה גדולה יותר תאיר למרחוק יותר ואע\"פ שאם היה מדליק נר להאיר במקום זה הרחוק היה מאיר שם יותר מהארה זו שמגיעה לשם מן האבוקה מ\"מ הרי כדי שיאיר למרחוק עושין אבוקה גדולה מפני שמעוצם גודל שלהבת האבוקה יגיע אור גם במקום זה הרחוק ואף שהאר' מועטת שם אבל מכח גדול הוא בא שהוא שלהבת גדולה המאירה ביותר כו' ועוד משל שני והוא כמו חבית המלאה ביותר שיוצא המים על כל גדותיה לחוץ לאבוד ובודאי זה שיוצא לחוץ לאבוד הוא כהפקר וגם מעט הם לגבי כל המים שבחבית מ\"מ הרי הן באין לחוץ מצד עוצם מלוי החבית שנתמלאה ביותר וכן ברב לתלמידו שכאשר נתמלא הרב בעצמו חכמה ודעת במילוי גדול עד שיוצא לחוץ לאבוד נובלות מחכמתו לתלמידיו והגם שנובלות הן וכלא חשיבא לגבי עצם חכמתו מ\"מ מכח גדול שבעצם חכמתו הן באין כאשר נתמלא כחו ביותר מכפי שיוכל שאת בכלי מוחו אשר ע\"כ יצא לחוץ כו'. והמשל השלישי מן כח המוליד שבטפה. שבקטן כמו פחות מן ט' שנים אין בו כח ההולדה להוליד ולד והטעם הוא לפי שאין בו כניסת כל המוחין שלו בשלימות עד שהוא בן ט' ויותר שאז נכנסו בו המוחין בשלימות שנקראו בחי' מוחין דגדלות כידוע אז יוכל להוליד מהמוחין שלו ולד בדומה לו כו'. והגם שהולד הוא נמשך ומתהווה ממותרי המוחין שמזה נעשה טפה כידוע וכלא חשיב לגבי עצם המוחין מ\"מ אין בכח"],[2201340119,"הטפה להוליד ולד כ\"א כאשר תצא בבחי' מותרות מצד שנתמלאו כלי המוחין בשלימות' שאז מכח גדול שבעצם המוחין היא באה ע\"כ יש בכחה להוליד עוד בדומה לו משא\"כ קודם כניסת המוחין בשלימות שאין בטפה היוצאת כח להוליד כו' וד\"ל ועכ\"פ המכוון בכל ג' משלים אלה עולה לסגנון אחד שכאשר הדבר בעצם במילוי כח עצמותו ביותר אזי יומשך ממנו נובלות למטה מטה יותר ואע\"פ שלמטה נראה הדבר קטן בערך אבל שרשו יוצא ממקום גבוה ביותר דהיינו מבחי' עצם כחו של אותו הדבר כמו שהוא במילואו ביותר ודוקא ממה שבא הדבר בירידת המדריגה למטה מטה ביותר כמו במשל של האבוקה הנה עיקר הוראת גודל השלהבת דאבוקה נראה דוקא מתוך אורה המאיר למרחוק ביותר וגם שכל שרחוק יותר יותר ימעט האור שם מ\"מ מזה מובן יותר כח גדול של התפשטות אור האבוקה וכן במשל הב' דחבית המלאה דוקא במעט מים שנופלים לאבוד בהם דוקא ניכר מילוי החבית ביותר וגם הרי במשל זה כל שתתמלא חבית זו יותר יותר ילך לאיבוד מכל מקום זהו ההוראה יותר על גודל המילוי ביותר וכן בירידות נובלות יותר מן המשפיע זהו מורה גודל מילוי כח חכמתו בעצמו ביותר אשר ע\"כ נופל ממנו נובלות יותר כו' וכן במשל הג' דכח ההולדה שלהוליד ולד שהוא יציא' ממהות למהות אחר הנה זה בא דוקא מבחינת המותרות הנדחקים מן המוח רק מצד בחינת עוצם המילוי של כח עצם המוחין (והוא ע\"י כח התענוג שנתמלא במוח ביותר מכפי מדתו אשר ע\"כ יוצא ממנו מותרות שהוא הטפה כו') ואע\"פ שהולד גשמי הוא הנעשה מהטפה הגשמי' כו' אדרבה זהו דוקא מורה על עצם כח מילוי דמוחין שהוא ביותר כו' שהרי קודם לכן אינו מוליד שלא יוכל להיות עדיין התהוות גשמי' ממש מזה כו' וד\"ל וא\"כ כל מה שבא הדבר למטה בהגשמ' למטה יותר מזה הורא' על היותו בא משרשו ומקורו כמו שהוא במילוי כחו ביותר מכפי המדה כו' וד\"ל:\n(יג) <b>והנמשל</b> מכל ג' משלים האלה יובן ג\"כ בענין ההלכות שבחי' ח\"ע שבהן מלובשת בהגשמת הענינים של ההלכות כמו בטומא' וטהרה וכה\"ג הנה מבחי' הארה זאת שירד' למרחוק כ\"כ להתלבש ולהאיר גם בענינים גשמיים כמו בעניני טומא' וטהרה כו' מזה ניכר ומובן שבא שורש ומקור הארה זו מבחי' אור גדול ביותר שהוא כדמיון האבוקה הגדולה שמגיע התפשטות אורה למרחוק ביותר ואע\"פ שבריחוק זה הארה מועטת מגיע שם מ\"מ מאור גדול היא באה כנ\"ל וכמ\"כ בהיות שבצמצום ח\"ע המצומצם ביותר כהתלבשות דברים גשמיים היא הארה מועטת ביותר מ\"מ הרי מכח עצם ח\"ע שבעצמות שנקרא מאור ולא אור משם היא זורחת שאל\"כ לא היה מתפשט ונמשך מגבוה לנמוך כ\"כ ולכן בחי' גלוי אור זה המצומצם בהלכות אין לו ביטול כזיו השמש בשמש מאחר ששרשו הוא במאור עצמו כו' כנ\"ל ואע\"פ שאם היה אור עליון מאיר בהלכו' בגילוי רב יותר אין זה ערך כלל לגבי מיעוט האור המוסתר בהלכות שבא מעצמות המאור גם שהוא מרחוק ביותר כנ\"ל לפי שגם בחי' היותר אחרונה ומצומצמת שמתפשט מן גופו של מאור יותר גדול הרבה באין ערך גם מגופו של אור הנר שמאיר בקירוב בגילוי רב כו' לפי שזה מאיר ונמשך ממקור האור שנקרא מאור עכ\"פ וזה מאיר מבחי' אור וזיו המאור בלבד (וכנ\"ל דאפי' אור צח כו' ומזה יובן דגם סודות הקבלה הנק' רזין דאורייתא ששרשן בבחי' ח\"ס שנקרא אור צח כו' וכה\"ג אע\"פ שמאירים באור גדול ורב לנשמות אין לו ערך לבחינת אור וגלוי המצומצם ביותר בגוף ההלכות להיותו נמשך ממקום גבוה ביותר שהוא מקור לבחי' האור שמשם נמשך השגות כל רזין דאורייתא כו' והיינו בבחינת עצמות המאור שהוא עה\"ע דאפי' אור צח כו' כביטול זיו השמש כנ\"ל וד\"ל)"],[2201340120,"וכמ\"כ יובן ע\"פ משל הב' דחבית המלאה ביותר הנ\"ל שהתורה הנגלית נקרא נובלות חש\"מ שהגם שהיא נובלות אשר ע\"כ מתלבשת בענינים גשמיים כו' מזה הוראה על היות שרש גילוי אור חכמה זו במקורה בבחי' המילוי שנתמלא עצם כח ח\"ע ביותר עד שנשפך על כל גדותיה לחוץ וכמ\"ש חכמות בחוץ תרונה שהיא חכמה שבתורה הנגלית לברר בירורי נוגה להבדיל בין טמא כו' וכידוע שזהו סימן ברכה בבית כאשר יין נשפך כמים דוקא כידוע וכן בחי' סימן ברכה ושפע רב ועצום ביותר למעלה כאשר יין דאורייתא העלם פנימי' שבה נשפך לחוץ בגילוי כמים לברר בירורים כו' וד\"ל וזהו שהתורה נק' משל הקדמוני חכמה דקדמונו של עולם נתלבש וירד למטה במשלים שהוא התלבשות חיצוניות דהלכות מטעם כלל הנ\"ל המכוון מג' משלים הנ\"ל שכל שהדבר בעצם במילוי כחו ביותר יומשך הארתו למטה בענין הגשמה ביותר כו' וכן במשל הנובלות שמרב לתלמידיו כשהוא במילואו ביותר כו' הרי מכח גדול של מילוי עצם חכמתו באין והן כמו משלי שלמה ומשלים דר\"מ שהן יותר גבוהין מבחי' גילוי אור שכל וחכמה של אחר המאיר יותר וכן במים הנופלים מחבית המלאה יותר חשוב ממים שבכוס קטן למטה כי ממקום גבוה באין כו' וד\"ל וכן במשל השלישי מכח ההולד' שכאשר המוחין בשלימות בחי' מותרות שלו מולידי' בהגשמ' ולד כו'. כ\"ה רמ\"ח פקודין רמ\"ח איברי' כו' ושרשם מחכמה עלאה דאורייתא מח\"ע נפקת ואמנם כאשר הוא בכח הח\"ע להמשיך בחי' רמ\"ח פקודין בחי' רמ\"ח איברים כו' הגם שזהו מותרות דח\"ע עצמה ה\"ז מגיע בבחי' עצם כחה כשהיא במילוא' ע\"כ הוליד ולד שהן בחי' המדו' והאברים כו' כמ\"ש מה שמו ומה שם בנו כו' (וכידוע שהתורה נקרא' אדם כמ\"ש זאת התורה אדם ונמשכת מלמעלה מבחי' אדם כמ\"ש במ\"א בענין וממדבר מתנה כו') וזהו יתרון מעלת מ\"ת לישראל במצות גשמיות שנק' רמ\"ח איברים כו' יותר מהשגת התורה שהשיגו האבות ברוחניות הגם שזהו למעלה מעלה בבחי' אור ח\"ע עצמ' אבל אין זה מגיע בעצם המאור מקור אור דח\"ע ואע\"פ שהאור בגלוי רב ועצום במעלה יתירה בנפשם כמו ליעקב במקלות שהאיר אור הרוחני בנפשם מבחי' ח\"ע שבתפילין שלנו כו' אין זה ערך כלל מבחי' עצמות ח\"ע שמלובש בתפילין שלנו מטעם הנ\"ל שכאשר בא הדבר בהגשמ' מזה דוקא הוראה על היות שרשו מעצמות הדבר כשהוא במילואו ביותר וזהו טעם ענין התהוות הולד מן הטפה שאינו רק לאחר כניסת המוחין במילואן ביותר כנ\"ל ואע\"פ שהתהוות הולד גשמי הוא מטפה גשמית אדרבה זה יותר גבוה בשרשו גם ממושכל דק ועמוק ביותר הנמשך מפנימי' כח החכמה כו' (וכמ\"ש במ\"א שמזה הטעם שרש הנשמות שנקרא בנים גבוהים גם ממלאכים העליונים שנמשכים מאורות דאו\"א כו') וד\"ל:\n(יד) <b>ומעתה</b> יובן בתוס' ביאור ענין הנ\"ל דההלכות גם לעתיד יהיו מוסתרים ביום ההוא כו' והוא בחי' סדכ\"ס שהוא בחי' המאור עצמו כו' שמזה נמשך כח הבירור למטה מטה עכשיו בעניינים גשמיים ביותר מטעם כל משלים הנ\"ל וד\"ל:\n<b>ובזה</b> יתורץ גם הקושיא דלעיל למה צריך שמן המור לעתיד כו' דשמן המור הוא רק בחי' כח הבירור דנוגה שבא מצד בחי' המאור דח\"ע שלמעלה מאור דח\"ע כנ\"ל וע\"כ נקרא שמן למאור ולא לאור כו' ושמן המור הוא בחי' עצמות המאור דח\"ע שבא למטה ביותר בבחי' נובלות ומשלים כו' לברר וזהו שמכריזין אשרי מי שבא לכאן ובידו תשלום כח הבירור דח\"ע שזהו ותלמודו בידו דוקא שלמעלה מבחי' רזין דאורייתא מטעם הנ\"ל וע\"כ צריכה הנשמה לו' חדשים בשמן המור קודם בואה לג\"ע כו' וכן לעוה\"ב (וזה שאמרו שההלכות לא יבוטלו אין הכוונה ענין הבירור שבהלכות כמו לטמא ולטהר ממש כו' שהרי"],[2201340121,"א' בר\"מ דאילנא דטו\"ר כשר פסול טמא טהור כו' יתעבר מעלמא כו' והוא לעתיד לאחר תשלום הבירור דקליפת נוגה לגמרי כמ\"ש ואת רוח הטומאה אעביר כו' ולא יהיה עוד טמא ופסול כלל וכלל רק הכוונה על בחי' הח\"ע הגנוזה בהלכות הללו ששרשן בעצמו' המאור דח\"ע דוקא כנ\"ל וכמו ההלכות ששונין עכשיו בג\"ע כמו אם בהרת קדמה לשער לבן כו' אע\"פ שאין בהרת וכל נגע טמאה בג\"ע כלל אבל בחי' ח\"ע שבה יותר גדול גם מבחי' הסוד שע\"פ הקבל' שבה כו' כנ\"ל) וכל הנ\"ל יובן מה שא' דמגלת אסתר לא תבטל לעתיד דהנה הנס של פורים הוא מלובש בדרך הטבע ביותר ע\"פ אחשורוש שאהב את אסתר וכל ענין ספור המעשה כידוע אך הנה אדרבה מזה שהיה מלובש הנס בדרכי הטבע מאד מובן ששרש האור הזה למעלה הרי הוא ממדריגה עליונה ביותר (למעלה משאר הנסים שנקרא נפלאות שאור האלקי מאיר למעלה מן הטבע כתחה\"מ וכה\"ג מפני שאין זה רק מבחי' נפלאות דעלמין סתימין שבא לידי גלוי כנ\"ל אבל כשמוסתר בטבע כמ\"ש אתה אל מסתתר כו' זהו למעלה בשרשו גם מבחי' הנפלאות דהיינו בבחי' סדכ\"ס והוא מ\"ש אסתיר פני גם ביום ההוא כנ\"ל מפני שהוא למעלה גם מנס דתחה\"מ לעתיד מטעם הנ\"ל וד\"ל) וכמשל אור האבוקה שמאירה למרחוק דהיינו גם בהלבשת הטבע כו' וכמו חבית המלאה ביותר שעוברת ממנה על כל גדותיה לחוץ כנ\"ל וזהו וימי הפורים האלה לא יעברו מתוך היהודים גם לעתיד שנאמר כימי צאתך כו' אראנו נפלאו' כו' מ\"מ נס דפורים יגדל על כולם ואין לו ביטול כלל מפני שהוא למעלה מבחי' אור וזיו כו' וכמו המאור עצמו שאין לו ביטול כו' וד\"ל:\n(טו) <b>וזהו</b> וקבל היהודים את אשר החלו לעשות ואמרז\"ל את אשר החלו בזמן מ\"ת ועכשיו בימי מרדכי ואסתר היה גמר הקבלה כנ\"ל דהנה כדי שיומשך בכנ\"י בחי' אור גדול כזה ששרשו בבחי' עצמות המאור שאין לו ביטול כלל כנ\"ל בענין מגלת אסתר וענין ההלכות שהן בחי' מרדכי מרי דכיא כו' הנה לזה הוצרך להיות הכנה בתחלה והוא בשעה שאמרו ישראל בזמן מ\"ת נעשה ונשמע כו' והיינו את אשר החלו לעשות זה האור הגדול בזמן מ\"ת ע\"כ עכשיו בימי מרדכי ואסתר היה גמר הקבלה להיות בחי' גלוי אור זה בא בכנ\"י למטה גם שהיה מוסתר מאד בדרך הטבע כמ\"ש למעלה והענין הוא כמבואר למעלה באריכות דבשעה שישראל אמרו נעשה ונשמע מזה נעשה בחי' העטרה שעטרה לו אמו ביום חתונתו כו' ודוקא במה שהקדימו נעשה לנשמע כו' כי ענין נעשה הוא בחי' ביטול רצון לבעל הרצון דוקא כנ\"ל שהרי אמרו נעשה מה שיגזור רצונו טרם ששמעו הרצון מהו ה\"ז הביטול למעלה מן הטעם לגמרי כי אם היה מורכב בטעם היה צריכי' לשמוע הרצון תחלה שידעו לאיזה דבר מבטלים רצונם א\"כ ה\"ז בחי' הביטול העצמי שלמעלה מן הרצון המורכב בטעם כו' וזהו מפני שבטל לבעל הרצון שממנו מקור כל רצון ולא אל הרצון הבא בגלוי בלבד וזהו נעשה ואח\"כ נשמע בביטול השמיעה אל הרצון בלבד כמו בטל רצונך מפני רצונו דוקא (שזהו רק כל ענין המצות מצד עצמן שנק' תרי\"ג ארחין וז' מצות דרבנן שהן תר\"ך עמודי אור בחי' הכתר בכלל אבל קיום המצות בביטול הרצון שבלא טעם כנ\"ל ה\"ז מגיע למעלה בבחי' כתר שבכתר שנקרא עטרה ע\"ג הראש כנ\"ל שזהו ענין נח\"ר לפני עצמותו ממש שא' ונעשה רצונו בכלל כו' והיינו אשר נתן כתר מל' בראשו בחי' כתר דמל' דא\"ס כנ\"ל באריכות וע\"כ מזה שאמרו נעשה היה הכנה גדולה להיות בחי' גלוי אור העצמות שנקרא סדכ\"ס כנ\"ל למטה בכנ\"י מאחר שעשו לו עטרה בבחי' ומדרגה זו עצמה במ\"ת וזהו את אשר החלו לעשות למעלה במ\"ת בעטר' שעטרה כו' בימי מרדכי היה בחי' גמר הקבלה דאור גדול זה עצמו למטה בכנ\"י וד\"ל:"],[2201340122,"(יו) <b>ומעתה</b> עדיין יש להבין מ\"ש וסוס אשר רכב עליו המלך שזהו ענין מ\"ש כי תרכב על סוסיך כו' שבשעת מ\"ת כנ\"ל דהנה מבואר למעלה ב' מדריגות דלבוש מלכות וכתר מל' שניתן בראשו והנה כפי פשט הענין הגם שהלבישו כבר את האיש לבוש מל' וניתן כתר מל' בראשו עדיין אין זה שלימות הדבר גדולה וכבוד שיחפוץ המלך לעשות באיש זה כ\"א כאשר ירכוב על סוס שרכב עליו המלך בלבוש מל' וכתר מל' זה שאז דוקא נשלם הדבר בתכלית א\"כ כל עיקר שלימות ענין דלבוש מל' וכתר מל' הוא ע\"י בחי' סוס שרכב עליו המלך שעל ידו יושלם ענין מעלת מדריגתם דוקא וכן יובן למעלה בבחי' לבוש מל' וכתר מל' הנ\"ל שצריכים לשלימות מעלתם ע\"י בחי' סוס שרכב עליו המלך דוקא כו' וד\"ל:\n<b>והענין</b> הוא כי הנה במ\"ת נאמר כי תרכב על סוסיך מרכבותיך ישועה והנה בחי' מרכבות הללו יובן בהקדים להבין ביאור מארז\"ל ג' שעות ראשונות יושב הקב\"ה ועוסק בתורה שניות יושב ודן כו' עד בליליא מאי קא עביד רוכב על כרוב קל שלו ושט בח\"י אלף עולמות שנאמר רכב אלקים רבותים אלפי שנאן א\"ת שנאן אלא שאינן כו' כי חסר ב' אלפים מרבותיים כו' וביאור הדברים הנה תקנו רז\"ל בסדר התפלה ח\"י ברכות כנגד ח\"י חוליות השדרה כידוע ולכאורה דבר זה פלא מה שייכות הברכות לח\"י חוליות השדרה אך הנה עד\"מ השדרה באדם הנה מוח החוט שבה נמשך ממוח שבראש כידוע והולך ונמשך בשדרה מן העורף והוא המחבר ומקשר לכל ח\"י חוליות שבשדרה שכל בנין הגוף עומד ע\"ז ומתפשט עד הירכיים ששם גיד הנשה שיש יניק' לחיצוני' כמ\"ש ותקע כף ירך יעקב כו') וכן יובן למעלה בענין ח\"י ברכאן דצלותא דכל ברכה וברכה הוא כמו בחי' חוליא א' שבשדרה וכאשר כורע בברוך שבברכה זו כורע ומשתחוה בחוליא זו השייך לברכה זו וכידוע דכורע בברוך וזוקף בשם והכריעה הרי היא כפיפת הראש והיינו בחי' המשכ' מן מוח שבראש שהוא שרש זה החוט שבח\"י חוליות ונמצא מוח הראש נמשך בחוט השדרה בכל ח\"י חוליות שזהו למעלה בבחי' אדם העליון דאצי' בחי' המשכ' מוחא עלאה דח\"ע שבראש דרך בחי' ח\"י חוליות דשדרה דאדם זה כבי' (כשכורע בברוך כו' שהוא ענין יריד' והמשכה למטה בעולמות דבי\"ע וכמארז\"ל מנין שהקב\"ה מתפלל כו' וד\"ל) עד בחי' הירכיים שהן ג' ברכות האחרונות כמו מודים אנחנו לך כו' בחי' הודאה בלבד כידוע דירכין בבחי' נו\"ה כו' ושם אין הארת המוח שבראש אשר בחוט השדרה מאיר כ\"כ (וע\"כ בהאבק יעקב עמו נגע בכף יריכו להיות יניקת החיצונים ג\"כ מזה ע\"כ לא יאכלו בנ\"י כו' וע\"כ בברכות ראשונות כורע בברוך בבחי' המשכ' מוח שבראש ובברכה אחרונה בבחי' ירכין אין שם רק בחי' הודאה משום דבינה עד הוד אתפשטת כו' וד\"ל. אמנם הנה ידוע דעיקר ח\"י ברכאן דצלותא הוא בבחי' המשכת סובב לממלא שהוא מבחי' ז\"א לנוק' שנק' קודב\"ה ושכינתיה וזהו שג\"פ ביום דוקא ממשיכים נש\"י ח\"י ברכאן דצלותא בוקר וצהרים וערב כו' לפי שנאמר חסד אל כל היום: שביום נמשך בחי' החסדים מדכורא לנוק' והיינו שאמרו י\"ב שעות הוי היום שהן י\"ב צירופי הוי' שבכל יום למעלה כו' שנמשך מאצי' לבי\"ע דרך ח\"י ברכו' כשכורע בברוך כו' אך בליליא מאי קא עביד קודב\"ה שהוא בחי' ז\"א שמדת לילה הוא בחי' הסתר המל' בצמצומי' רבים בנבראים וכמו לילה הגשמי' שהאדם ישן ואינו עוסק בהשפעה והמשכה כלל כן למעלה בבחי' לילה לא יאיר חסד אל דאדם דאצי' לבי\"ע כלל אך אז הוא זמן שירת המלאכים לפי שבי\"ב שעות הלילה הן י\"ב צירופי אדנ\"י שהוא בחי' המל' שיורדת למטה מטה בהיכלות התחתונות ומשפע' טרף ומזון לכל הנבראים וכמ\"ש ותקם בעוד לילה ותתן טרף לביתה כו' טרף רפ\"ח ע\"ה שהוא"],[2201340123,"בחי' הבירורים שמבררת מבחי' נוגה וכידוע ואמנם זהו דוקא ממה שמקבלת מבחי' ח\"י ברכאן דצלותא שביום שחסד אל כל היום נמשך ממוח העליון שבראש כנ\"ל בבחי' ח\"י חוליות ונמשך הארתם למטה מטה ג\"כ דהיינו לעולמות ומלאכים ע\"י בחי' המל' וזהו חי חי הוא יודוך כו' אך שם ה\"ז האור והשפע דח\"י ברכאן מתחלק לח\"י אלף מדריגות כי מבחי' המשכה עליונה א' מתחלק לאלף מדריגות לפי שמתחלק ליו\"ד וי' למאה כו':\n(יז) <b>והיינו</b> שאמרו בליליא מאי קא עביד קב\"ה רוכב על כרוב קל שלו ושט בח\"י אלף עולמות פי' כרוב הוא בחי' מט\"ט שנקרא אנפי זוטרי כרביא בבחי' קטנות המוחין לגבי אדם כו' והוא בחי' צמצום השפע שיורד ע\"י בחי' כרוב קל זה בח\"י אלף עולמות שנקראים רכב אלקים רבותים וחסר ב' אלפים מרבותיים ע\"כ הן ח\"י אלפים כמארז\"ל שאינן כו' והענין הוא דבחינת ההמשכה וההשפע' בצירוף אותיות שיורד בליל' בבחי' הקטנות ה\"ז ע\"י שרוכב על כרוב קל שלו ושט בו בח\"י אלף שהן צירופי אותיות שנקרא בשם כרוב שהוא אותיות ברוך בהיפוך אותיות שבחי' אדם דגדלות כשכורע בברוך הוא בבחינת המשכת מוחין דגדלות ממוחין שבראש דוקא כנ\"ל אך כשמתצמצם אור זה לבא לידי מלאכים בע\"ג אז נקרא כרוב בהיפך אותיות כו' וד\"ל דהנה סיומא דהאי קרא דרכב אלקים רבותיים כו' הוא מ\"ש אדני בם סיני בקדש פי' אד' בם הוא בחי' המל' שמלובש במרכבה זו שנקרא רכב אלהים רכב דשם אלהים דוקא כו' אך הנה כמו שנמשך בחי' שפע האלקים דשם אד' ואלקים ע\"י צירופי אותיות דבחי' כרוב הנ\"ל במלאכים בע\"ג כו' כן נמשך ע\"י בחי' צירופי אותיות והמשכות מא\"ס ב\"ה בתורה שניתנה בהר סיני וזהו סיני בקדש והרי גם אחרי ירידת משה מן הר סיני לבסוף ארבעים יום כתיב ועשו לי מקדש ושכנתי בתוכם להיות בחי' גלוי שכינה בדברים גשמיים שמהן נעשה המשכן בגשמיות כמו זהב וכסף ונחשת ויריעות וקרשים וכו' וזהו כי תרכב על סוסיך:\n<b>שבחי'</b> המשכות הללו נקראו בשם סוסים כי בחי' צירופי אותיות נקראו סוסים כי ענין הסוס הוא בחי' התגלות האור שמתגלה ויורד למטה שזה נמשל לסוס כמו עד\"מ ע\"י הסוס יבוא הרוכב למקום רחוק כך ירידת המשכת האור לבא למטה מטה למרחוק יותר הוא ע\"י צירופי אותיות הרבה שנושאים את האור ומורידין אותו למרחוק כו' וזהו רכב אלהים רבותיים כו' רכב זה הוא בחי' צירופי אותיות כו':\n(יח) <b>והנה</b> יש הרבה מיני אותיות כמו עד\"מ אותיות השכל הן אותיות שנק' סוסים בחי' מרכבה לגבי הארת השכל שיורד ונמשך על ידן למטה כו' ויש אותיות המחשבה והן אותיות אחרים להיות מרכבה לגבי המח' להורידה כו' ובודאי יש הפרש גדול בין אותיות שהשכל מורכב בהן לאותיות שהמח' מורכבת בהן ויש אותיות הדבור שהן אותיות המבטא אחה\"ע מהגרון כו' שהדבור הרוחני דרוח ממללא מורכב בהן ועד שלא נמצאו צירופי האותיות בה' מוצאות הפה אין התינוק יכול לדבר מאומ' הגם שרוחו בחי' רוח ממללא כו' כמו שלא ירכב אדם בלא סוס כו' לכן כתיב כי תרכב על סוסיך מרכבותיך ל' רבים שהן בחי' צירופי אותיות דח\"ע דתורה שבשעת מ\"ת שהן אותיות וסוסים היותר נעלים כי שרשן הוא גם בלמעלה מן החכמה לבא על ידו לבחי' החכמה כמ\"ש והחכמה מאין תמצא פי' מאין מקדמת השכל שנק' מקור החכמה או חכמה הקדומה וכדי שיומשך מאין דקדמות השכל היינו ע\"י בחי' אותיות דחכמה הקדומה שמורכב בהן קדמות החכמה וכן עד\"ז עד רום המעלות גם בבחי' הרצון והתענוג יש בחי' אותיות ששייך אליהם שהן מורכבים בהן ועל ידן יומשכו בגלוי למטה כו' וגם הרצון והתענוג הפשוט שנק' כתר שבכתר שזהו מ\"ש שעטרה לו כו' בחי' כתר"],[2201340124,"מל' ג\"כ יש לו בחי' אותיות שמורכב בהן כו' וד\"ל:\n<b>ובכל</b> זה יובן סדר המדריגות דבחי' אותיות שנק' סוסים לפי הפסוקים הנ\"ל דהנה מדרגה היותר תחתונה שבהם הוא מ\"ש רכב אלקים והיינו ג\"כ אד' בם כו' שהן המלאכים שהן בחי' מרכבה לבחי' הדבור העליון שהוא שם אלקים ושם אדנ\"י ונק' אותיות הדבור שברוח פיו כל צבאם ונק' סוסים היותר תחתונים ולמעלה מהם הוא בחי' הכרוב קל הנ\"ל שהקב\"ה רוכב עליו ושט כו' שהן בחי' אותיות שהן מרכבה להמחשבה (והוא בחי' ו\"ק דבריאה שבחי' ז\"א דאצי' רוכב עליו בלילה בבחי' הקטנות כו') וזהו שהקב\"ה בחי' מדות דאצי' שרוכב על אותיות המחשבה עד\"מ מדות שבלב שמורכבים בצירופי אותיות שבמחשבה כו' למעלה מזה הוא בחי' אותיות המדות והן ענין הו' גוונין דבמשכן שש משזר תכלת כו' זהב וכסף כו' וכמ\"ש ועשו לי מקדש ושכנתי בתוכם ואשכחן מקדש דאקרי משכן דמקדש הוא בבחי' כלים דהיינו אותיות דמדות ומשכן הוא בבחי' הדבור דמל' שמקבלת מז\"א כו' ולמעלה מזה הוא מ\"ש סיני בקדש שהם צירופים דח\"ע שנמשך בסיני להיות גלוי אור דחכמה דתורה על ידן למטה בכנ\"י כנ\"ל ולמעלה מזה הוא בחי' אותיות היותר עליונים שבכתר שבזה נאמר כי תרכב על סוסיך מרכבותיך ישועה. שע\"ה נהורין דכתר בחכמה ועד\"ז עד רום המעלות עד בחי' כתר דמל' דא\"ס שהוא בחי' התענוג בלבוש מל' כו' ג\"כ יורד ע\"י בחי' אותיות השייך לו שיהיה מורכב בהן לבא לידי גילוי למטה כו' וזהו וסוס אשר רכב עליו המלך דוקא סוס א' לבחי' רצון הפשוט ותענוג הפשוט דכתר מל' שבראשו ולבוש מל' שלו שלא נתגלו למטה כ\"א ע\"י בחי' סוס שלו שנק' סוס אשר רכב עליו המלך ומ\"ש כי תרכב על סוסיך רבים מתחלקים מסוס זה וזה היה במ\"ת להיות ח\"ע דתורה מאין תמצא כנ\"ל וד\"ל ונמצא שאין שלימות לבחי' כתר מל' ולבוש מל' כ\"א ע\"י הסוס שרכב עליו המלך שע\"י נשלם עיקר מעלתם שאין הכבוד והגדולה שבכתר מל' ולבוש מל' רק כשנגלין בדרך מרכבה והוא ע\"י הסוס שרוכב עליו המלך וד\"ל:\n(יט) <b>והנה</b> כל בחי' ומדריגות העליונות הנ\"ל בבחי' לבוש מל' וכתר מל' וסוס שרכב עליו המלך שהיה במ\"ת. הכל נתגלו לכנ\"י בימי מרדכי ואסתר באופן שאז היה גמר הקבלה שקבלו בנפשם ממש את אשר החלו לעשות בזמן מ\"ת כנ\"ל שבזמן מ\"ת החלו לעשות במה שאמרו נעשה ונשמע ובימי מרדכי היה גמר הקבלה כו' אך יש להבין לכאורה למה בימי מרדכי היה זכות גדול לכנ\"י יותר מבזמן מ\"ת שאמרו נעשה ונשמע כו' והענין הוא הגם שאמרו נעשה בזמן מ\"ת שהוא בחי' ביטול הרצון למסור נפשו באח\"פ למעלה מן הטעם לגמרי כו' כנ\"ל מ\"מ אין זה רק אמירה בדבור ובקבלה בלב ואף שקבלו בלב באמת לאמתו בכל נקודת לבבם שנק' נקודת הרצון שבלב שלמעלה מן השכל והטעם כו' מ\"מ הרי לא בא דבר זה לידי פ\"מ למסור נפשם בפ\"מ אף שבודאי נכון היה לבבם למסור נפשם בפ\"מ (ומה שא' ה' למשה והעיד על אמיתת הכנת לבבם באמרו מי יתן והיה לבבם זה כו' (בפ' ואתחנן) אע\"פ שזה היה על שבקשו שלא יוסיפו עוד לשמוע קול ה' שלא ימותו אלא ואת תדבר אלינו וכו' וע\"ז אמר ה' הטיבו כל אשר דברו מי יתן כו' היינו לפי שלא בחרו בבחי' רצוא לבד להכלל באור ה' אלא דוקא בבחי' שוב לעשות רצונו כמ\"ש ושמענו ועשינו וזהו שהוטב טוב לבבם שזה יותר מורה על אמתת בחי' ביטול הרצון דנעשה כו' וד\"ל) וע\"ד שאמר ר\"ע לתלמידיו כל ימי הייתי מצטער כו' מתי יבא לידי ואקיימנ' במס\"נ בפ\"מ דוקא אעפ\"י שבודאי היה לו מס\"נ בכח בכל נקודת הרצון שבלב כו' (והיינו כמו שא' בע\"ח בענין י' הרוגי מלוכה שהעלו מ\"ן לאו\"א מפני מס\"נ בפ\"מ כו') אך בימי מרדכי באו כנ\"י לבחי' מס\"נ בפ\"מ שהרי ידוע שהמן לא רצה להרוג את היהודים"],[2201340125,"רק שימירו דתם וכמארז\"ל כל הכופר בע\"ז נק' יהודי ע\"כ זהו שא' שביקש להשמיד להרג ולאבד את כל היהודים כו' ולכך נק' מרדכי איש יהודי הגם שהיה משבט בנימין ואפילו כהנים ולוים שבאותו הדור היו נקראים יהודים ע\"ש בחי' מס\"נ על קדה\"ש שלא המירו דתם להחיות נפשם וע\"כ דוקא מחמת מס\"נ זו שבאה לידי פ\"מ הוא שזכו אותו הדור להיות בנפשם ממש מבחי' גלוי כל הבחי' ומדריגות היותר עליונים הנמשכות מעצמות אא\"ס ב\"ה דוקא שהן בחי' לבוש מל' וכתר מל' וסוס כו' כנ\"ל והיינו וקבל היהודים את אשר החלו לעשות בזמן מ\"ת בבחי' גמר הקבלה דוקא וד\"ל:\n(כ) <b>אך</b> הנה עדיין יש להבין מ\"ש ויקח המן את הלבוש ואת הסוס כו' דלכאורה זה פלא גדול מאחר שבחי' לבוש מל' וכתר מל' כו' הן מדריגות עליונות ביותר כנ\"ל מאין זכה המן שיהיה הוא המלביש את מרדכי שיקח המן את הלבוש ואת הסוס כו' מהיכן יש לו השגה בלבוש מל' העליון ובסוס שרכב עליו המלך עד שא' ויקח המן דוקא את הלבוש כו' אמנם הנה אמרז\"ל המן מן התורה מנין שנאמר המן העץ אשר צויתך כו' והענין הוא דכתיב ראשית גוים עמלק כו' וידוע שהז' אומות הן ז' מדות רעות שהן בבחי' עה\"ד טו\"ר כו' שנפל בשבירה מז' מלכים כו' אך עמלק הוא למעלה מז' אומות ונק' ראשית גוים כו' וזהו המן העץ כו' שהוא למעלה מן העץ דעה\"ד טו\"ר וע\"כ המן העץ הוא לשון בתמיה כו' ואמנם א\"כ למה נק' ראשית גוים מאחר שהוא למעלה מהם לגמרי ואין לו שייכות עמהם כלל איך נק' בשם ראשית להם וגם מאחר שא' המן העץ לשון בתמיה שהגם שהיא לשון בתמיה מ\"מ הרי יש לו עכ\"פ קצת שייכות אל העץ ע\"כ א' המן העץ לשון בתמיה שאם אין לו שייכות כלל עם העץ מה ענין כלל להזכירו אצל העץ אפילו בלשון בתמיה כו' ואעפ\"כ נבדל הוא בערך מן העץ עד שמתמיה ע\"ז וא' המן העץ כו' אך הענין הוא שהוא בחי' מקיף אל עץ הדעת שהוא כמו נוגע ואינו נוגע כו' ע\"כ שניהם אמת. שמתמה המן העץ כו' ומכל מקום יש לו קצת שייכות עד שהוא נופל בגדר תמיה כו'. וזהו שנקרא ראשית גוים עמלק. שנקרא ראשית להם ואף על פי כן אינו נמנה עמהם. ושרש הדברים הוא דאת זלע\"ז עשה האלקים כו'. דכמו שיש ז' מדות בקדושה כך ז' מדות בקליפה. ואמנם שרשם ומקורם וראשיתם הוא בחי' הדעת. שהוא רק הרגשות עצמותו ביותר ע\"כ אוהב כל דבר הטוב אל נפשו ושונא דבר המזיק אל נפשו כו'. וזהו שבאכלו מעה\"ד אמר לו מי הגיד לך כי עירם אתה כו'. שבתחלה לא הרגיש א\"ע כלל ואח\"כ הרגיש את עצמו ביותר שנק' יש מורגש ביותר. שמזה שרש המדות שמסתעף בבחי' רע גמור כתאות וכעס כו'. ומפני שהדעת הוא למול העורף ושם יונק מבחי' אחוריים דדעת דקדושה. בחי' קליפת עמלק שהוא בחי' היש. בחוצפה וגסות הרוח. שלא לבטל א\"ע כלל גם נגד כל אור האלקי המתגלה בנפש כו' (כמ\"ש במ\"א בענין טמטום הלב כו' וד\"ל):\n(כא) <b>אך</b> בודאי גם בקדושה לעומת זה. יש ג\"כ בחי' המן והוא המן דקדושת אלקית. והיינו בחי' המן שלאחר הברור כמו שאמרו מב\"ב של המן למדו תורה ברבים כו'. הרי יצאו ממנו נשמות קדושות שנכללו באור ה' בח\"ע דתורה. הפך היש המורגש בחוצפה כו'. ובחי' המן דקדושה היינו כמו ויגבה לבו בדרכי ה' כו'. וכמאמר רז\"ל שצריך שיהיו עיניו למטה ולבו למעלה פי' עיניו למטה הנה העינים הן בבחי' החכמה. כידוע דעיני העדה הן בבחי' חכמה כח מה כו'. ועיניו למטה הוא בבחי' הבטול האמתי דכחו מה דחכמה לאסתכלא ביקרא דמלכא כו'. אך זהו בחי' חכמה שבמוח שהוא בבחי' מה. כמו"],[2201340126,"בבחי' משה שא' ונחנו מה. וע\"כ היה עניו מכל כו'. כי הנשמה האלקית היא במוח. ואמנם בלב הוא בחי' רוח ואש. שעולה למעלה בבחי' הגבהה והתנשאות הפך הבטול דחכמה שבמוח. וזהו מצד בחי' הצמאון שבלב מבחי' יסוד האש כי בינה לבא כו'. ע\"כ בהתלהבות הלב לה'. יגבה הלב בהרגשת עצמו. בהגבהה והתנשאות למעלה. שזהו הפך הבטול העדר ההרגשה מכל וכל כו'. וכמו מים ואש שהן ב' הפכים. כן המוח והלב הן ב' הפכים:\n<b>שחכמה</b> שבמוח היא בחי' בטול וירידה למטה. ובחי' רוח ואש שבלב הם בבחי' הגבהה כאש כו'. ע\"כ גזרו אומר שיהיה שניהם. עיניו למטה בבחי' בטול. ולבו למעלה בהגבהה. כי אם לא יגבה לבו להיות עולה למעלה כו' לא יוכל לעבוד ה' מצד שפלות עצמותו באומרו מי אנכי כו'. ע\"כ צריך חזוק והגבהת הלב. לעורר בחי' התשוקה והצמאון ומה גם בהיותו בבחי' הצמאון והתשוקה. שיגבה לבו בהרגשת האור והחיות כו':\n<b>אך</b> גם צריך שיהיה הפך זה בבטול עצמותו ע\"י עסק התורה בהמשכ' ח\"ע. דאורייתא מח\"ע נפקת כו' כידוע. לבטל בחי' היש והגבהה דבחי' רצוא שבלב בתפלה כו':\n(כב) <b>וזהו</b> כי טוב טוב לגנוז כו'. טוב לגנוז אור ההתלהבות שבלב בתפלה. בתורה שהיא הפך זה בבחי' בטול עצמותו כו'. כמ\"ש ודברי אשר שמתי כו' כמים שמכבים אש כו'. ולא כבוי לגמרי אלא כמאמר רז\"ל שת\"ח צריך להיות בו חלק שמיני שבשמינית ומעטרא ליה"],[2201340127,"כסאסא' כו'. דהנה ידוע שהחכמה יש בה ל\"ב נתיבות והן המתפשטים בל\"ב חדרים שבמוח. ומן המוח מתפשטים הל\"ב נתיבות בלב. וע\"כ נק' לב לפי שמקבל מל\"ב נתיבות חכמה (וכמ\"ש בע\"ח בענין הלב. לפי שבו מסתיים אורות דאו\"א שהן בבחי' ל\"ב שבילין כו'. שע\"י הדעת נחלק לד' מוחין כידוע ובכל מוח יש ח' אותיות דהוי\"ה אדנ\"י. וכמ\"ש במ\"א בענין האבנט ומצנפת) והנה כללות שניהם ל\"ב נ\"ח שבמוח ול\"ב נ\"ח שבלב. עולה גי' ס\"ד כי ב\"פ ל\"ב הוא ס\"ד. וחלק שמיני שבשמינית הוא חלק א' מס\"ד (כי ח' פעמים ח' הוא ס\"ד. וכאשר ל\"ב נ\"ח באין בלב. הרי יש כאן ח' פעמים ח') שד' מוחין כשכל א' כלול מח' הוא ל\"ב. וכשנכפלין בלב הרי ח' פעמים ח'. וחלק א' שמיני שבשמינית שהוא חלק ס\"ד אין זה רק כאשר יש ח' פעמים ח' דוקא והענין הוא שת\"ח הוא בחי' הארת ח\"ע שבמוח שהוא בחי' בטול דכח מ\"ה כנ\"ל. ול\"ב נתיבות דח\"ע צריכים להיות בלב ג\"כ בבחי' בטול ושוב כנ\"ל. רק חלק א' מס\"ד בלבד. שהוא שמיני שבשמינית שבלב צ\"ל בבחי' הגבהת הלב והתנשאות. כנ\"ל בענין לבו למעלה כו'. שבלתי זה אין חבור ללב אל המוח כי הרי ידוע שהמוח הוא העיקר ששם בחי' חכמה ומן המוח מתפשט אל הלב. ואין הלב מחובר למוח כ\"א בבחי' העלאה תחלה מן הלב. כי אין המשכה בלתי העלאה תחלה. כי רוח אייתי רוח כו'. ומכ\"ש רוח החיים שבחלל הימני שבלב שמקבל ממוח החכמה כו'. רק ע\"י בחי' הגבהת הלב קצת בחלק שמיני שבשמינית בזה עולה הלב ומתחבר במוח. ונמשך אח\"כ המוח דחכמה בלב בבחי' בטול כנ\"ל. וע\"כ דוקא ת\"ח צריך לחלק ס\"ד דגסות כו'. ויותר מזה הוא גסות הרוח שבלב להיות בחי' יש ממש ולא יועיל אח\"כ בחי' בטול דחכמה כו' אבל חלק ס\"ד מעטרא ליה כו' בבחי' מקיף:\n<b>נוגע</b> ואינו נוגע שבקליפה הוא בחי' עמלק המן חוצפה ממש. שרש המדות. ובקדושה הוא בחי' המן דקדושה לאחר הבירור כמו ויגבה לבו בדרכי ה' כנ\"ל. וזהו המנגד לבחי' המן דקליפה. כי בחי' התנשאות דקדושה ג\"כ למעלה מבחי' המדות אוי\"ר דקדושה אלא נוגע ואינו נוגע. כי אע\"פ שההתנשאות של הלב בהתלהבות הוא למעלה מהתפעלות אהבה כו'. מ\"מ ה\"ז בחי' מקורן ושרשן כו'. וכאשר הוא רק חלק ס\"ד בלבד. אזי מעטרא ליה כסאסא' כו' בבחי' עטרת וכתר כו' וד\"ל. וזהו המן מן התורה מנין. פי' המן דקדושה לאחר הברור וכנ\"ל. שנאמר המן העץ כו'. למעלה מעה\"ד טו\"ר במורגש היש כו' ונוגע ואינו נוגע. שהוא בקליפה ראשית גוים כנ\"ל ובקדושה הוא הגבהת הלב בדרכי ה' ברצוא שבתפלה. ורק חלק ס\"ד הוא במורגש התנשאות. שאז יש בחי' ברור להמן דקליפה כו' וד\"ל:\n(כג) <b>וזהו</b> ויקח המן את הלבוש ואת הסוס כו'. המן דוקא. כי הנה בחי' לבוש מלכות הנ\"ל. ה\"ז בחי' גאות והתנשאות דמלוכה שבקדושה. כמ\"ש ה' מלך גאות לבש. וזהו ע\"י בחי' המן דקדושה לאחר הברור. שהיא בחי' הגבהה והתנשאות הלב למעלה כו'. וזהו שאמר המן יביאו לבוש מלכות שבידו להביא בחי' לבוש דהתנשאות זאת. ובחי' סוס הוא ב\"פ ס\"ג שעולה בגי' סוס כי טבע הסוס בגאות וגסות כו'. ולהיות בחי' ס\"ג הוא ענין הגסות וכמ\"ש כלו סג. כשיש יותר משמיני שבשמינית שהוא חלק ס\"ד כנ\"ל. אך לאחר הברור עולה בבחי' ס\"ג דקדושה. היינו ב\"פ ס\"ג שהוא בגימטריא סוס. והוא סוס שרכב עליו המלך. בהתנשאות דמלוכה דוקא (שלמעלה מבחי' סוסים שהן אותיות החכמה כנ\"ל) וזהו ביום ההוא יהיה על מצלות הסוס. כל מה שהסוס רץ ומצל כו' כמ\"ש במ\"א). וזהו ויקח המן את הלבוש ואת הסוס. אבל דוקא לבוש וסוס בלבד. אבל כתר מלכות אינו ע\"י המן. כי מ\"ש ואשר נתן כתר מל' בראשו. ניתן מלמעלה ולא הזכיר מי הוא הנותן. והיינו כמ\"ש במ\"ת בעטרה שעטרה לו אמו דוקא. שאמו היא הנותן עטרה זו על ראשו. והיינו כנ\"י שלא זז מחבבה עד שקראה אמי והיינו ע\"י בחי' בטול רצון דנעשה ונשמע ונעשה קודם לנשמע כנ\"ל. שזה הבטול הוא למעלה מן החכמה כו'. ואין בזלע\"ז לנגד זה בחי' המן כלל. כי המן הוא בחי' התנשאות כו' ע\"כ לא נאמר רק ויקח המן את הלבוש ואת הסוס בלבד. ואשר ניתן כתר מלכות בראשו הוא ע\"י ישראל דוקא מפני שאין בזלע\"ז דוגמתו כלל וכלל וד\"ל:\n(כד) <b>ולהבין</b> כ\"ז בתוס' באור. וגם להבין מ\"ש קח את הלבוש כו' למרדכי היהודי היושב בשער המלך. מהו ענין הלבשה זו למרדכי היהודי דוקא היושב בשער המלך כו'. אך הנה יש להקדים ענין א' על מ\"ש כי אל דעות ה' כו'. שיש ב' דעות. א' דעה עליונה דקמי עצמותו. איך דקמיה כלא חשיב. שזהו מיש לאין כו'. והדעה הב' שלגבי העולמות שהוא מאין ליש כו'. וע\"ז נאמר כי אל דעות. שסובל ב' דעות הפכיים הללו. מפני שהוא למעלה מב' הדעות כו'. ובאור הדברים הנה יובן עד\"מ גשמי מן התהום שהוא למטה מן הארץ וממנו נובע דרך גידי הארץ מעיינות רבות:\n<b>וכמו</b> מעינות תהום רבה כו' משום דהארץ חלחולי מחלחלא בגידין רבים:\n<b>ומתצמצם</b> הילוך מי התהום לעבור דרך צמצום הגידים הקצרים שבארץ. ומן המעינות שנובעים מן הארץ. הן הן הד' נהרות הגדולות שנמשכים ממעינות תהום כידוע. ונמצא יש כאן ג' מדרגות:\n<b>הא'</b> בחי' מי התהום עצמם שהוא עיקר המקור שמשם נובע ונמשך בגידי הארץ מעט מזעיר. דכלא חשיב ממש לגבי מקור התהום עצמו. והב' הוא מעינות תהום הללו שבגידי הארץ בהעלם:\n<b>והג'</b> מה שנובע מן המעיינות שבארץ לחוץ ע\"פ הארץ שהן הנהרות. והנהרות הגם שמתגברים משפע רב. מ\"מ עיקר חוצבם אינו רק טפה א' שנובעת בתמידות מן המעיין שנעלמה בארץ ומן ההעלם בא לידי גלוי להיות נהר שוטף. ונהר יחרב ויבש כאשר יסתם מעיינו כידוע. וה\"ז כמו כל בחי' המשכה שמאין ליש שהמעיין נובע בבחי' ההעלם בבחי' אין והנהר נראה ליש. ואמנם ענין נביעת המעיינות מן התהום ה\"ז מיש לאין. דהיינו שהתהום הוא בחי' יש האמתי. ומה שממנו נמשך בגידי"],[2201340128,"הארץ. כלא וכאין חשיב לגבי התהום עצמו כנ\"ל. וא\"כ ודאי אין ערך לומר בבחי' אין של היש המדוד דנהר שהוא המעיין. שיש לו דמיון לגבי צמצום בחי' האין דיש האמתי שהוא התהום כאשר נמשך ממנו מעט מזעיר. שמזה מקור כל המעיינות שבארץ בלי הפסק. שהגם דכלא חשיב לגבי התהום עצמו. מ\"מ הוא יותר נעלה הרבה מבחי' אין של היש. שהן המעיינות שבארץ שכבר נתצמצמו:\n<b>אע\"פ</b> שהן נקראים מקוריות לגבי הנהרות בבחי' אין והעלם כנ\"ל אבל מ\"מ מבחי' אין דיש האמתי נעשה אין של יש הגבולי דנהרות שהן המעינות ונמצא ג' מדרגות הללו. ד' הן. שהגם שבכלל אין כאן רק ג' מדרגות יש ואין ויש. דהיינו יש האמתי ואין שלו. שהוא אין של היש הגבולי. מ\"מ בפרט ד' הן מפני שב' מדרגות באין. משום דאין דיש האמתי הרי הוא למעלה הרבה מאין דיש הגבולי כו' וד\"ל:\n(כה) <b>ויובן</b> זה יותר בענין משל אחר כמו תלמיד לפני רבו שמקבל הארת שפע שכל וחכמה מרבו. שאצל רבו החכמה והשכל. רב כמו מי התהום. והתלמיד מקבל רק אפס קצהו כטפה מים. ואף גם זאת המעט אצלו בהעלם ואין. להיותו מופלא מכלי שכלו עדיין. ואח\"כ מבינה ומקבלה בשכלו ומתפשטת בהשגה והיה לנהר רחב כו'. ובהיותו טרוד למבלע ולקבל. אז בטל כלי שכלו ונעשה בבחי' אין. משום דכלא וכאין ממש חשיב לגבי עצם החכמה כמו שהיא במוח רבו וע\"כ איידי דטריד למבלע לא פליט. להיות משפיע לתלמידו הקטן הימנו כידוע. אבל אחר שקבל מרבו הגם שהוא אצלו עדיין בבחי' אין. מ\"מ יוכל להשפיע לזולתו בבחי' יש דהשגה הגבולית. או לעצמו להרחיב בה כו'. ונמצא גם כאן ג' מדרגות הנ\"ל. שהן ד' בפרט שהרי מה שהתלמיד מתבטל בעת קבלתו מרבו. יש בו ב' טעמים הא' מצד הפלאת השכל הזה. שהוא אצלו בבחי' אין עדיין. והב' שהוא עיקר הביטול מה שכלא חשיב ממש לגבי עצם החכמה כמו שהיא אצל רבו אשר ע\"כ איידי דטריד למבלע לא פליט כלל. להיות בבחי' אין ויש. ונמצא יש כאן ד' מדרגות בפרט. א' בחי' יש האמתי שהוא עצם החכמה שברבו. והב' מה שהארה בעלמא נשפעת להיות אור שפע לתלמיד. דכלא וכאין חשיב לגבי עצמות חכמתו. והג' מה ששפע זו נעשה בבחי' אין והעלם לגבי שכלו של התלמיד. והד' מה שמתפשט מאין ליש בתלמיד. לעצמו או להבינה לזולתו. ואע\"פ שאין כאן רק יש ואין ויש. שהוא יש האמתי דרב. והארת השפע שלו. שנעשה אין של היש בתלמיד. מ\"מ בבחי' האין יש ב' מדרגות כי מה שהארת המשפיע נק' אין לגבי עצמותו. יותר נעלה הרבה ממה שנק' אח\"כ אין של היש לגבי התלמיד. והכל עולה לסגנון א' עם משל הראשון וד\"ל:\n(כו) <b>ועוד</b> משל שלישי בזה מבחי' כח הצומח שבארץ, שהוא כח עצמי להצמיח בלי שעור. ובזורע חטה בארץ:\nתרקב תחלה. ואז יתלבש בה כח הצומח להצמיחה מאין ליש ממש:\n<b>והרי</b> גם כאן ג' מדרגות הנ\"ל שהן ד' בפרט. כי כח הצומח עצמו הוא נק' יש האמתי שבכחו להצמיח עד אין שעור כו' והצמיח' בפרט שמתפשט הימנו. כלא חשיב לגבי עצם כח הצומח כו'. וכאשר מתלבש הארה פרטית להצמיח את החטה. יש כאן ב' מדרגות. א' מיש לאין. שהוא מיש האמתי דעצם כח הצומח. להצמיח בפרט דכלא חשיב כו'. והב' מה שנעשה בחי' הארה דצמיחה זו בבחי' אין של היש הממשי דחטה זו. אשר לא תוכל להצמיח כ\"א ברקבון תחלה שהוא בטול היש לאין זה כו' וד\"ל:\n(כז) <b>ועוד</b> משל ד' והוא מענין התהוות הטפה רוחניית במוח שנק' אין של היש הולד הנולד ומצטייר ברמ\"ח אברים כו' והוא כלא חשיב לגבי כח העצמי שבנפש. שמשם נמשך טפה זו במוח. שבכח זה להמשיך ולהוליד עד אין"],[2201340129,"שיעור כו' וד\"ל:\n<b>וכן</b> הוא בענין התהוות השכל מלמעלה מן השכל. שנק' נקודה כאין. כמ\"ש והחכמה מאין תמצא כו'. אבל אין זה שממנו נמצא החכמה ליש. שנק' אין של היש. הוא למטה מבחי' אין דיש האמתי. מטעם המובן מכל המשלים הנ\"ל וד\"ל. ובכ\"ז יובן ענין הנ\"ל. במ\"ש כי אל דעות ה' כו'. ב' דעות. א' בחי' דעה עליונה. איך דקמיה כולא כלא וכאין חשוב. שזהו מיש לאין כנ\"ל. דהיינו מבחי' היש האמיתי. שהוא בחי' עצמותו ומהותו ממש. ומה שנמשך הארה בעלמא להיות בבחי' סובב וממלא כלא וכאין כו'. ואמנם הגם שבחי' הארה זו נקר' אין לגבי השתלשלות העולמות דאבי\"ע שנק' יש. ה\"ז הענין דומה לענין נביעת המעיין לגבי הנהר כו'. או לקבלת התלמיד כשטריד למבלע ואח\"כ משפיע לזולתו כנ\"ל. או כמשל הגרעין והטפה כו'. שמבואר למעלה דבבחי' אין זה. יש ב' מדרגות ובחי' אין דכלא חשיב לגבי עצם המשפיע. הרי זה הגבה למעלה הרבה ממה שנעשה אח\"כ אין ליש גבולי כו'. וזהו דמיון להבין למעלה בכללות ההשתלשלות שראשית שלהם הוא בחי' החכמה שמאין תמצא. דהיינו מאין ליש גבולי. שהרי מהחכמה ולמטה נמשך בבחי' השתלשלות בבחי' אורות וכלים המגבילים האור כו' עד שמתהווה בחי' גבול ממש כידוע. וא\"כ הרי בחי' אין זה אין לו ערך כלל לגבי בחי' אין שלפני עצמותו שהוא מיש לאין. איך דקמיה כלא וכאין. לפי שזה הבטול דאין משום דקמיה כלא וכאין ה\"ז מצד עצמות אא\"ס דוקא משא\"כ בחי' אין לגבי היש. מאחר שהוא בצמצום רק לפי ערך התהוות היש בלבד (ומלבד זה המה ב' הפכים:\n<b>דאין</b> דיש הוא בבחי' בטול דכלא כו'. ואין ליש. הרי נמשך להיות בבחי' יש. ולא נק' אין רק להמקבל כו') וזהו ב' דעות הפכיים. דעה שאצל המשפיע שהוא מיש האמתי לאין. ודעה דמקבל. שהוא מאין ליש גבולי. וכתיב כי אל דעות. שסובל ב' דעות. משום דקמיה עצמותו כמו שהוא קודם שיבא לכלל ההשפעה לגמרי גם מיש לאין. מאחר שאין ערך כלל אליו:\n<b>ב'</b> דעות הללו שוין ממש. דהיינו מפני שהמשפיע והמקבל שוין כו' וד\"ל:\n(כח) <b>והנה</b> יש ב' בחי' בטול. הא' בחי' בטול היש לאין. שזהו מצד בחי' הדעה הב' דמאין ליש. לזה שייך ענין בחי' בטול היש שנתהווה מן האין. לחזור לבחי' אין כמקדם וכמשל בטול היש דגרעין וטפה כו' וכן ביטול הנהר לגבי המעיין. שזהו בטול היש ההשגה לנקודת חכמה שנק' אין של היש כו':\n<b>והב'</b> בחי' בטול עצמי ומקורי. דהיינו כמו בטול האין לגבי היש האמתי הנ\"ל. שזה הביטול כלא באמת. מצד בחי' העצמות שאין לפניו בחי' יש כלל לומר בו בטול היש כו' וכמו תלמיד שבטל לפני רבו. מצד שכלא חשיב כל שכלו לגבי עצם חכמת רבו כנ\"ל. או בטול כח הצומח פרטי שבגרעין. או כח המוליד פרטי שבטפ'. לגבי עצם כח הצומח. או לגבי עצם כח המוליד שבנפש וכה\"ג. וכמו\"כ בטול דאין דחכמה לגבי העצמות כו'. ואין זה נקרא בטול היש לאין מאחר שאינו ביטול עצמי אלא נעשה מחדש כי היה יש ונתבטל. אבל בטול זה דמצד העצמות הוא בטול עצמי ומקורי כמו עד\"מ המתבטל בעמדו לפני מלך שמצד המלך בא לו בטול עצמי שאינו בבחי' יש כלל וכלל. משא\"כ המבטל א\"ע מצד החכמה שנק' כח מה עד שבטל מישותו בלבד. שאין זה רק בטול היש בלבד כו' וד\"ל ובכלל הוא ההפרש בין בטול שמצד החכמה כח מה שאינו רק בטול היש בלבד לאין דחכמה. ובין בטול עצמי שלמעלה מן החכמה אלא רק מצד שבטל לפני העצמות. דקמיה עצמותו כלא וכאין. שזהו אין באמת מצד אמתת העצמות כו' וד\"ל:\n(כט) ובכל זה יובן ענין וילבש את מרדכי כו'. דהנה בחי' הנשמות"],[2201340130,"יש בהן ב' מדרגות. הא' מצד שנמשכין מבחי' החכמה שמאין ליש תמצא. וכידוע בענין כי אתה אבינו. כטפה במוח האב כו'. והוא בטול היש לאין כח מה שבכל נשמה לברר ברורים כנ\"ל בענין מיר' דכיא כו'. וזהו בחי' מרדכי. ומה שנקרא מרדכי היהודי היושב בשער המלך כו'. הוא בחי' יחידה שבנשמה ששרשה בבחי' העצמות ע\"כ יש לה בחי' בטול עצמי שלמעלה מן החכמה. וכמו בטול הנעשה בבחי' רצון פשוט כו' כנ\"ל. והנה כדי להמשיך לנשמה שנמשכת מאין ליש שבבחי' החכמה מלמעלה מעל' דהיינו מבחי' העצמות דקמיה כלא כבחי' דעה הא' כו'. אין זה בא רק לבוש מקיף לנשמה. שהוא להמשיך עליה בחי' בטול דלבוש מלכות שזהו איך דקמיה כלא. שז\"ש ה' מלך גאות לבש כו'. וזהו ויקח המן את הלבוש ה\"ז כי בחי' המן בקליפה הוא החוצפה שלמעל' מן החכמה כנ\"ל. ולאחר הברור מגיע בבחי' התנשאות אלקית. שבא מצד העצמות דוקא. שלמעלה מבחי' אין דיש שבא בהשתלשלות כנ\"ל ע\"כ המן לאחר הברור דוקא מלביש למרדכי שהוא בחי' הנשמה שמאין דחכמה כו' מבחי' לבוש מלכות. שנמשך מבחי' הארה דיש האמתי וד\"ל. אבל כתר מלכות הוא בעטרה שעטרה לו אמו דוקא ע\"י ישראל ע\"י בחי' בטול רצון דנעשה כו' ולא ע\"י המן כי אין בחי' המן מגיע לשם כלל כנ\"ל. לפי שבחי' כתר מלכות הוא בבחי' עצם התענוג הפשוט שבעצמותו ממש. ונקרא שעשועי המלך שמצד העצמות דוקא. שזהו למעלה גם מבחי' ההתנשאות דלבוש מלכות שאינו רק הארה בעלמא. מה דכולא קמיה כלא חשיב אבל אין זה בחי' העצמות ממש ע\"כ אין בחי' התנשאות דכלא חשיב מגיע לשם כלל. רק ע\"י בחינת בטול הרצון העצמי שלמעלה מן החכמה. מפני שמגיע בבחי' העצמות ממש. מצד שישראל שרשן בבחי' העצמות ממש. ע\"כ בחי' כתר מלכות זה הוא ע\"י ישראל דוקא (ואע\"פ שהתנשאות האלקית מגיע בבחי' יש האמתי כאשר מבואר במ\"א בדוגמא לזה ממ\"ש רשב\"י אנא סימנא בעלמא כו' וכה\"ג וכמ\"ש המלך המרומם כו' ומתנשא כו'. מ\"מ אין בחי' התנשאות נופל רק על זולתו שהוא כלא חשיב. א\"כ אין זה בחי' היש האמתי כמו שהוא רק שבא מצד שהוא יש האמתי ע\"כ הוא מרומם ומתנשא מימות עולם כו' וד\"ל) לפי שאין ד\"ז בזלע\"ז כלל. כי גם בחי' התנשאות דהמן לאחר הברור אינו מגיע לשם כלל. להיותו למעלה מבחי' לבוש מלכות. וזהו ואשר נתן כתר מלכות. ולא ע\"י המן אלא כמו במ\"ת דכתיב בעטרה שעטרה לו אמו דוקא שהן כנ\"י בשעה שאמרו נעשה כנ\"ל וד\"ל:\n(ל) <b>ולהבין</b> שרשי הדברים בבחי' לבוש מלכות וכתר מל' הנ\"ל גם להבין ההפרש בין שרש התורה ושרש המצות שיש מעלה בזה מה שאין בזה כנ\"ל. הנה יש להקדים תחלה מ\"ש במ\"ח בענין אורות המקיפים ואורות הפנימיים. דבחי' המקיפים הן כגלדי הבצלים זעג\"ז והעליון מכולם משובח מכולם והתחתון גרוע. ובפנימיים הוא להפך. שהעליון גרוע ומלובש זה בזה. עד שהפנימי מכולם משובח מכולם כו'. וזהו עצמו ההפרש שאנו רואים בין כתר לחכמה בכלל. שבחי' גלגלתא הנק' כתר. מקור כל בחי' מקיפין. ובחי' ח\"ס וחכמה שבכתר מקור כל אורות פנימיים. הרי בחינת חצונית הכתר שהוא עצם הגלגלתא הוא בחי' גשמית ובו שורה הרצון שבבחי' חיצונית ג\"כ. כי אין לרצון טעם כלל. אבל בחי' מו\"ס שבתוך הגלגלתא הוא בבחי' פנימית הכתר שהרי יש בה טוב טעם לטועמיה כו' וד\"ל. וזהו ג\"כ שרש ההפרש שבין תורה ומצות דהנה שרש התורה שהוא רק פי' ובאור על המצות. בבחי' ח\"ע. שנק' מו\"ס דא\"א. שהוא פנימי' הכתר דהיינו הטעם לרצון. שהוא בחי' פנימיות. האור והחיות של הרצון. למה ירצה כך וכך דוקא. וע\"כ המו\"ס"],[2201340131,"כמוס ומכוסה בתוך הגלגלת והגלגלת מקיפה כשומר לפרי. שהשומר טפל והפרי עיקר כו'. כן הרצון עצמו שאינו רק בחי' חצונית בלא אור וחיות טעם ושכל. רק שרוצה כך. ה\"ז בבחי' הגלגלת מצד עצמה שאינו רק עצם גשמי. והוא הנק' חצונית הכתר כנ\"ל. אבל מו\"ס שבו שהוא בחי' פנימיות הטעם לרצון הוא כמוס בגלגלת כי הוא בחינת פנימיות שבו. וא\"כ לפ\"ז הרי בחי' רצון העליון שבמצות. הוא בחי' הגלגלתא. חצונית הכתר. למטה במדרגה מבחי' שרש התורה דבבחי' ח\"ס. שהוא פנימיות שברצון זה המלובש בגלגלתא ולפיכך אמרו דת\"ת עדיף ממצות. וכמו דמוכח כמה מאמרים לזה. כמו שהתלמוד גדול. ושת\"ת כנגד כולם. וכל חפצים לא ישוו בה אפי' חפצי שמים:\n<b>כל</b> מצותיה של תורה אינם שוים אפילו לדבר א' מד\"ת וכנ\"ל. אך א\"כ לא יובן מה שאמרו בכמה דוכתי שהמצות עדיף מת\"ת כמו לא המדרש הוא העיקר אלא המעשה. והלומד ואינו עושה כו'. ומה שתלמוד גדול אינו אלא מפני שמביא לידי מעשה. וזיל בתר טעמא כו' כנ\"ל. ובהכרח לומר שיש מעלה יתירה במצות מה שאין בתורה. והענין הוא דבאמת לא ראי זה כראי זה. דודאי יש מעלה יתירה בתורה מה שאין במצות כנ\"ל. לפי שהתורה שרשה בבחי' מו\"ס. משא\"כ במצות ששרשן רק בחצוניות הכתר כנ\"ל. אמנם יש גם מעלה יתירה במצות. שנמשכים מבחינת תרי\"ג ארחין דגלגלתא חצונית הכתר. מה שאין בתורה הנמשכת מבחי' מו\"ס. והיינו משום דאדרבה היא הנותנת. דמשום שבחי' הגלגלתא היא רק בבחינת חצונית בלבד. הנה זה מורה על היות שרשה למעלה בבחי' אא\"ס עצמו. הוא בבחי' ומדרגה גבוה ונעלה יותר משרש המו\"ס:\n<b>דהיינו</b> ששרש ומקור דבחי' מו\"ס דא\"א באא\"ס. הוא בבחי' ומדרגה באא\"ס. למטה מבחי' ומדרגת שרש הגלגלתא. אשר ע\"כ בא הארת אא\"ס בבחי' מו\"ס. בבחי' פנימיות דוקא. והאור הבא משם בבחי' גלגלתא בא בבחי' חצוניות יותר. מפני כלל גדול הידוע. שכל אור היותר עליון למעלה מעלה א\"א לו לבא למטה כ\"א בלבוש חצוני ביות' כי בבחי' פנימית לא יוכל להכיל אותו כל אור רק דוקא בדבר חצוני ביותר וכל שהוא עליון ביותר צריך לבא למטה בלבוש חצוני ביותר וכל שאיננו אור עליון כ\"כ במקומו למעלה אי אפשר לו לבא למטה רק בבחי' פנימיות שיוכל בחי' פנימיות להכילו ולא בחי' חצוניות (וכמשי\"ת בסמוך) וזהו ההפרש בין מו\"ס לגלגלתא:\n<b>דמשום</b> דשרש בחי' מו\"ס באא\"ס איננו אור עליון כ\"כ כמו שרש האור דגלגלתא ע\"כ בא למטה גם בבחי' פנימיות. והוא בחי' מו\"ס שהוא בחי' פנימיות האור. שהרי הוא בחי' טוב טעם לרצון כו' כנ\"ל אבל שרש האור דבחי' גלגלתא. להיותו בבחי' מעלה ומדרגה יתירה במקומו למעלה. ע\"כ בירידת אורו לבא למטה:\n<b>א\"א</b> לו להתלבש כ\"א בבחי' חצונית דוקא. והיינו בחי' עצם הגלגלת המקיף המוחין שבו הרצון שבלא טעם כו' כנ\"ל:\n(לא) <b>ומזה</b> הטעם עצמו יובן סבת ענין ההפרש שבין תורה למצות כנ\"ל לפי שהתורה שרשה בבחי' מו\"ס. שיכול לבא בהמשכת אורו ושפעו למטה ממנו ג\"כ בבחי' פנימית. והוא ענין טעמי המצות שבבחי' חכמה ושכל. שמשתלשל ויורד מבחי' מו\"ס מקור כל חכמה עד תורה הנגלית שלנו שבעשיה. שהיא ג\"כ בבחי' טעם ושכל המושג בעשיה. ולא בא בלבוש חצוני כ\"כ כמעשה המצות. אבל הנה שרש המצות בבחי' גלגלתא. ומפני ששרשה באור עליון ביותר שאינו רק בחצונית ע\"כ גם בחי' ירידת התלבשות רצון העליון שבגלגלתא הוא בא למטה הימנו בעולמות ג\"כ בבחי' חצוניות. עד שמתלבש רצון העליון במצות מעשיות בדברים גשמיים דבחי' נגה דעשייה כו'. ובזה יש יתרון מעלה למצות על התורה. מצד שרש דגלגלתא. אבל מצד בחי' התגלות האור. הרי בבחינת"],[2201340132,"מו\"ס בא הגלוי בבחי' פנימיות. ובבחי' גלגלתא בא האור בבחי' חצוניות. ובזה יש יתרון למעלת התורה על המצות כנ\"ל. ונמצא דכל המאמרים שנאמרו במעל' התורה על המצות ובמעלת המצות על התורה שניהם אמת ולא סתרי אהדדי כלל וד\"ל:\n(לב) <b>אך</b> הנה יש להבין בעיקר ענין כלל גדול הנ\"ל. באור העליון ביותר שאינו בא למטה רק בחצוניות. וכל שאינו עליון כ\"כ אינו בא רק בפנימיות ולא בחצוניות כו'. להיות ידוע בבחי' עצמות אא\"ס ממש. שכשמו כן הוא אין לו סוף כו' ואין לו תחלה. קדמון לכל הקדומים כו'. והוא בבחינת אח\"פ בתכלית. דהיינו שהוא בבחי' יחידות לבדו. מובדל בערך מכל בחי' אור וגם בחי' האור היותר עליון. אין לו שתוף וחבור עמו כלל. גם שיוכל להשיגו אפס קצהו. וכמאמר דאפי' אור צח אור מצוחצח. אוכם הוא לגבי עה\"ע כו' וע\"כ אמרו דלית מחשבה תפיסה ביה כלל וכלל. אפי' מחשבה וחכמה סתימאה כו'. משום שהחכמה מאין תמצא. רק מבחי' היותר אחרונה שבעצמות אא\"ס א\"כ איך יש ביכולת ח\"ס להיות לה בחינ' תפיסא במהותו ועצמותו כו'. מאחר שכל עיקר מציאותה מבחי' האין אינה רק בחי' הארה בעלמא. היותר חצונית שבאא\"ס עצמו כו'. אמנם הנה דוקא לית מחשבה תפיסא ביה. בבחי' מחשבה וחכמה דוקא הוא שאינו נתפס כלל מטעם הנ\"ל. והיינו להיות כי עיקר בחינת ומהות דמחשבה וחכמה הרי הוא עכ\"פ בבחי' השגת דבר מה. שהרי תכלית עיקר ענין החכמה הוא להשיג דבר מה כו'. ובבחי' אח\"פ לא יגיע שום בחינת השגה ותפיסא כלל מטעם הנ\"ל ע\"כ אמרו דלית מחשבה תפיסא ביה. אמנם זהו דוקא בבחי' חכמה ומחשבה. להיותו בבחי' אור פנימי עכ\"פ שהרי הוא בבחי' כח השגה (אע\"פ שגם ההשגה רחוקה מאד בערך מעצמות אא\"ס. כמו עד\"מ שיאמר אדם שא\"א לו לתפוס דבר חכמה בידו. שבודאי א\"א להעריך בחי' המשוש ביד לגבי השכל הרוחני כמ\"ש בלק\"א שיותר מזה א\"א לומר שיהיה תפיסא במחשבה וחכמה סתימאה לאא\"ס הנבדל בערך יותר מהבדלת ערך השכל הרוחני מן המשוש הגשמי כו'. מ\"מ לא נחשב בחי' החכמה בחי' לבוש חצוני כ\"כ כמו לבוש חצוני הבא בהגשמה ממש כמו בחי' הגלגלת כו' כי מפני עוצם רוממות עצמות אא\"ס. גם בחי' החכמה בחי' רוחניות ופנימיות תחשב. עד שלא יוכל להתלבש בה רק בחצוניות ממנה יותר. וכמו ענין משלים שיתבארו בסמוך וד\"ל) כי הנה אע\"פ שעצמות אא\"ס הוא מובדל בערך לגמרי. ולא יוכל להתגלות בכל אור הנמצא מאתו היינו דוקא בבחי' גלוי פנימיות. כמו בחי' מחשבה סתימאה שנאצל מאתו בבחי' פנימית. שנקרא בשם חכמה עכ\"פ. ובבחי' פנימית ודאי אין ערך כלל. שיהא בחי' תפיסא לחכמה הנאצל בעצמות המאציל כו'. אבל בבחינת גלגלתא. מפני היותה בבחי' החצונית ביותר. הנה שם דוקא יוכל לבא בחינת גלוי התלבשות אא\"ס כמו שהוא ממש. מאחר שאין זה בא בבחי' פנימית האור כמו בחי' ההשגה ותפיסא בחכמה עלאה רק בבחי' הלבשה בחצוניות בלבד. הרי שם יוכל להתגלות כמו שהוא דוקא. וע\"כ מזה יש יתרון מעלה בבחי' גלגלתא עם היותה בבחי' חצוניות יותר ממו\"ס. אבל זה מורה על היות שרשה בעצמות אא\"ס באור עליון ביותר. אשר ע\"כ אינו בא למטה רק בבחי' חצונית. שהוא בחי' הגלגלתא כנ\"ל. משא\"כ בחי' מו\"ס. להיותו בבחי' פנימית יותר. ע\"כ מזה יש הוראה בשרשו שהוא אינו אור עליון כ\"כ במקומו ע\"כ לא יוכל לירד רק בבחי' פנימית שהוא בבחי' החכמה. ולא יוכל לבא בבחי' חצונית ביותר כו' וד\"ל. והנה עדיין אין דבר זה מובן על בוריו. דהגם שזה מובן מה שאור עליון ביותר לא יוכל לבא בבחי' פנימית שלא יוכל להכילו כנ\"ל כ\"א בחצונית יותר כו'"],[2201340133,"אבל מה שהאור שאינו עליון כ\"כ אינו בא רק בבחי' פנימי' ולא יוכל לבא בחיצוני' זה אינו מובן לכאור' דלאו ק\"ו הוא אם בפנימית הוא בא ונמשך למה לא בא ויתלבש גם בחצונית כו':\n(לג) <b>אך</b> הנה שרש ענין הכלל הזה יובן ע\"פ שלשה משלים גשמיים. הא' ממשל האבוקה הגדולה ביותר שתאיר למרחוק מאד כפי ערך גודלה כמו האבוקות והמדורות הגדולות שמאירין למרחוק ב' או ג' פרסאות וכה\"ג. והנה אנו רואים שהגם שההארה של האבוקה הגדולה מאירה למרחוק לא תאיר שם בתוקף האור רק הארה מועטת ביותר מפני עוצם הרחוק שרחוק ממקום האבוקה והמדורה כמו לערך פרסה ויותר. ואם היה מדליק אבוקה קטנה באותו מקום הרחוק היה מאיר שם הרבה יותר. אך מ\"מ בזאת יתרון מעלת ההארה הבאה שם מן האבוקה הגדולה להיותה באה מהארת אור גדול במקומו עכ\"פ. שמאחר שכחה של האבוקה גדול כ\"כ להאיר למרחוק. הגם שהארתה שם מעט הוא אבל מזה ניכר ונראה מעלת אור האבוקה במקומו שהוא גדול מאד שאם היה אור אבוקה קטנה במקומה לא היה מגיע במקום הרחוק שום האר' כלל וכלל. רק במקומה תאיר אורה בלבד אבל ברחוק מקום לא ניכר אור' כלל. כי אין התפשטות ההארה מגיע למקום הרחוק רק מן אור האבוקה הגדול' דוקא משא\"כ אבוקה קטנה במקומה כו':\n(לד) <b>והנמשל</b> מזה יובן למעלה בטעם ענין כלל הנ\"ל. שכל אור העליון במקומו ביותר. תתפשט הארתו למטה מטה גם במקום הרחוק ממנו ביותר. שזהו ענין ירידת השראת האור הזה בחצוניות. הגם שהארתו נעלמת שם מאד. מ\"מ זהו הוראה דוקא שמאור גדול במקומו הוא בא. וכמשל לאבוקה הגדולה שמאירה למרחוק ביותר. שגם אם ימצא איזה אור למטה בגלוי יותר. מ\"מ הוא למטה הרבה במדרגה. מבחי' אור הנעלם הזה בחיצוניות (ודוגמא לדבר ענין פנימיות התורה. שנק' טעמי תורה. אע\"פ שמאירין אור בגלוי טעם וחכמה עלאה. מ\"מ הוא למטה מבחי' חצוניות הנגלות לנו. מטעם הנ\"ל וד\"ל) וכל אור שאינו עליון במקומו כ\"כ. אין הארתו מתפשטת למטה מטה כ\"כ. כמשל האבוקה הקטנה שלא תאיר רק במקומה בלבד כו' כמו\"כ אין אור כזה מתפשט למטה מטה בהתלבשות חצוניות. רק בבחי' פנימיות. הקרוב עדיין בערך אל מקום אור העליון הזה. ולא יאיר ברחוק מקום הימנה שהוא בחי' החצוניות כו' וד\"ל:\n(לה) <b>וכמו\"כ</b> יובן הנמשל מזה. בהפרש שבין תורה למצות. להיות שרש התורה רק בבחי' אור החכמה עלאה. שנק' בחי' אור קטן בערך לגבי עצמות אא\"ס. כערך אור אבוקה קטנה מאד לגבי האבוקה הגדולה ביותר. וכמ\"ש יהי אור. שזהו אור דתורה. וכמ\"ש ותורה אור כו' ובהיות כן לא יוכל בחי' אור דתורה. לירד להאיר למטה מטה כ\"כ. אלא עיקר אורה הוא למעלה במקורה ושרשה. שהוא בחי' מו\"ס הנק' פלאות חכמה ותעלומות חכמה. והוא בחי' עדן שנאמר בו עין לא ראתה כו'. כי כמוסה ונעלמה בלתי מתפשטת בגלוי אור למטה להיות בבחי' חצוניות כמו בעשיה גשמית אלא בבחי' רוחניות. כמו טעמי המצות ובאורן בתורה שבע\"פ. מפני שהוא בבחי' פנימיות לרצון העליון בשרשו למעלה בטוב טעם מתוק לחיך. שהוא בחי' עדן. שהנשמות משיגות סוד טעמי המצות. וכמ\"ש ישקני מנשיקות פיהו. אלו טעמי מצות שלא יתגלו רק לעתיד. כי בלתי מתפשט למטה כמו שהן למעל' בבחינת מו\"ס. וה\"ז כמשל האבוקה הקטנה. שלא תאיר רק במקומ' ובקירוב אליה. ולא בריחוק מקום הימנה כנ\"ל. אבל שרש המצוה שהוא בחי' גלגלתא. בחינת"],[2201340134,"כתר. ששם שורה בחי' הארת עצמות אא\"ס. בחי' סובב כו'. להיותו בחי' אור עליון וגדול ביותר במקומו בבחי' א\"ס ממש. ע\"כ יוכל להתפשט. למטה מטה אשר לא יוכל כל אור להגיע כ\"כ למטה. וכמשל האבוקה הגדולה שמתפשטת למרחוק ביותר. הגם שהארתה שם בצמצום כנ\"ל. וזהו ענין המשכת אא\"ס בבחי' גלגלתא. שהוא רק רצון בחצוניות בלא טעם פנימי כו' ונמשך רצון זה עד למטה מטה. בבחי' עשיה גשמית דמעשה המצות. אשר לבחי' מו\"ס אין כח זה כלל. להיותו קטן בערך באור עצמותו כמו שהוא למעלה במקומו כמשל האבוקה הקטנה כנ\"ל וד\"ל:\n(לו) <b>ועוד</b> יובן ע\"פ משל ב'. והוא כמו חקיקות האותיות החקוקים באבן טוב הבהיר וזך ביותר שא\"א להסתכל בעין באותיות הללו החקוקים באבן טוב זה. לעוצם הבהירות שבו שמבהיק לעין. עד שלא ניכר לעין הרואה שום תמונת אותיות כלל. אך כאשר ישימו האבן הטוב הזה בשעוה. ויחתום בו בציור האותיות החקוקים בו. אז נכרים האותיות שבו בשעוה דוקא כי בשעוה שם אין אור האבן מבהיק כ\"כ אדרבה חשך אורו שם ע\"כ שם ניכר האותיות אבל כאשר אין האבן טוב מבהיק יכירו חקיקות אותיות שבו בהסתכלות בעצמו ומהותו בלי הצטרכות לשומו בחותם השעוה (וע\"פ משל זה יובן מ\"ש בריש הורמנא דמלכא גליף גליפו בט\"ע פי' גליף גליפו הוא חקיקה לחקיקה. שזהו כציור אותיות חותם האבן הטוב הבהיר. בשעוה וכה\"ג. והיינו מפני שבחי' אור דבחי' טהירו עלאה הוא אור בהיר ומבהיק ביותר. אשר ע\"כ נק' טהירו עלאה והיינו בחינת גלוי עצמות אא\"ס שקודם הצמצום דמק\"פ וחלל כו'. ובחי' האותיות החקוקים בו. היינו מה ששיער בעצמו בכח. מה שעתיד להיות בפועל. בחי' מקור להשתלשלות בבחי' קו כו' כמ\"ש במ\"א. ומפני שא\"א שיקבלו העולמות מאותיות הללו. ע\"כ גליף גליפו בחקיק' אותיות הללו בהתלבשות חצוניות יותר כמ\"ש באורך נראה אור כו'. מפני ששם דוקא ניכרים. מטעם המשל הנ\"ל וד\"ל) וא\"כ הרי מובן ממשל זה. שכל אור יותר עליון. לא יוכר רק בהתלבשות שלו בחצוניות יותר וכל אור שאינו עליון כ\"כ א\"צ להתלבשות חיצוניות כו' כי כל דבר הגבוה גבוה ביותר לא יוכר אורו רק בריחוק מקום בהלבשה חצוניות דוקא (וכמו אור הנר שאינו מאיר רק במקום חשך ואפלה ביותר. שם יוכר אורו ביותר. אבל שרגא בטהרא מאי מהני. וכמ\"ש במ\"א):\n(לו) <b>ועוד</b> יובן ענין כלל הנ\"ל יותר ע\"פ משל הג'. והוא מענין משלי שלמה כמ\"ש וידבר שלשת אלפים משל כו'. דלכאורה זהו דבר פלא. מה עוצם שבחו של חכמת שלמה במ\"ש ויחכם מכל האדם:\nברוב משלים שדבר והלא המשלים רוב ענינם:\n<b>ענינים</b> זרים ורחוקים יוצאים מגדר השכל. ומהיכן יש להם שייכות עם עמקי החכמה כו':\n<b>וכן</b> אמרו בשבח מעלת חכמתו של ר\"מ שהיה דורש ג' מאות משלי שועלים כו'. אך הענין ידוע שאין המשלים מצד עצם ענינם חכמה גדולה. שהרי הם דברים פשוטים מאד. אלא מפני שהמשלים הן להשיג חכמות עמוקות ביותר שא\"א להשיגם בהבנה כמו שהם. להיותם בתכלית העומק וההפלאה מן השכל ביותר:\n<b>אשר</b> ע\"כ צריך להיות להם בחי' לבוש זר שע\"י יבאו לידי השגה (וכמו משל הנ\"ל בחקיקת אותיות שבאבן טוב הבהיר. שאינם ניכרים רק בשעוה וכה\"ג) וכמו שאנו רואים שכל שהשכל והחכמה עמוקה ונפלאה ביותר. לא יוכלו לעמוד על עמקו. כי עמוק עמוק הוא מי ימצאנו כו':\nכ\"א שימצא לו ענייני משלים:\nהגם שהם דברים זרים:\n<b>אך</b> שהן קרובים לענין הדבר שבו השכל והחכמה שיובן מזה בדרך נמשל עכ\"פ. אז ע\"י המשלים יוכלו לעמוד על כל עומק החכמה הנפלאה. וכל שאור החכמה"],[2201340135,"ההיא עמוקה ונפלאה ביותר:\n<b>יותר</b> צריך לרוב משלים. ושיהיה זה משל לזה וזה לזה. עד שבאמצעות כל המשלים שמלבישים זא\"ז. אז יוכלו לעמוד על עומק הפלאת החכמה להשיגה (כי במשל הראשון עדיין לא יוכלו להבין עומק החכמה. מפני שגם משל זה צריך לבוש ומשל וכן משל הב' צריך גם הוא משל ולבוש שיושג על ידו:\n<b>וכן</b> עד כמה משלים רבים מאד שזה משל לזה כו'. עד המשל היותר אחרון. שהוא בחי' לבוש היותר חצוני. שם דוקא יוכלו לעמוד על עומק החכמה שמלובש במשל הראשון. וכל שהיא עמוקה ביותר:\n<b>צריך</b> לבא בלבושים דמשלים רבים יותר. וכל שאינו עמוק כ\"כ די לו בב' וג' משלים וכיוצא:\nוא\"צ לבא בהתלבשות במשל למשל ברבוי כ\"כ:\n<b>וכאשר</b> אינו עמוק כלל. א\"צ כלל משל להשיגו. כי יושג בלא משל כו') וזהו וידבר שלשת אלפים משל:\n<b>שכ\"כ</b> היתה חכמת שלמה עמוקה בעמקי סודות התורה. עד שהיה צריך אור חכמתו לבא בג' אלפים משלים. זה משל לזה כנ\"ל. עד שבמשל האחרון שבג' אלפים שם הוא מובן ומושג. וגם זה לא כמו שהוא אלא כמו שרואה דרך המסך כו':\nכן כל מי שחכמתו יש בה עומק גדול:\n<b>שלא</b> יוכלו חבריו לעמוד על סוף דעתו וחכמתו כמו ר\"מ בדורו שנק' ר' נהוראי שמנהיר עיני חכמים כו':\n<b>שלא</b> יוכלו חבריו לעמוד על סוף דעתו היה דורש חכמתו בג' מאות משלים כו' (וה\"ז כמו אור מבהיק ביותר. שצריך לבושים עבים להשיגו בעין. ע\"ד דוגמא ממה שאמרו משה ראה באספקלריא א' ושאר הנביאים בז' אספקלריאות דמצד עוצם הפלאת האור מהם. הוצרך לבא אליהם בז' לבושים ומסכים. שכל לבוש ומסך מסתיר את שלפניו בכדי שבאמצעות ההעברה דרך כלם זא\"ז דוקא יתמעט האור כ\"כ עד שיוכל להתגלות במראה הנבואה לפי כלי הגבלת נשמתם משא\"כ למשה שלא היה האור מופלא הימנו כ\"כ מצד עוצם מעל' נשמתו כידוע לא היה צורך האור האלקי לבא ולהתגלות בנשמתו רק ע\"י בחי' לבוש ומסך דאספקלרי' א' לבד וכו' והאספקלריא הוא רק מה שהחכמה הוא מאין ליש בלבד. וז' אספקלריאות הוא בעבור האור מחו\"ב למדות כו' וד\"ל) וכמו חכם גדול שצריך להשפיע איזה שכל עמוק. לתלמידו הקטן בערך ביותר:\n<b>שצריך</b> להלביש השכל הזה במשל. אך גם משל הזה שכל עמוק הוא ועדיין לא יושג גם הוא אז צריך להלביש גם למשל זה במשל גס וקטן השכל יותר:\nעד שלפי ערך קטנות התלמיד. ולפי ערך גדלות עומק שפע השכל:\nצריך להלביש בלבוש תוך לבוש. עד שנעשה בלבוש גס:\nוקצר השכל ביותר:\n<b>כדי</b> שיוכל גם התלמיד קטן השכל. לעמוד על אותו עומק השכל הראשון. כמו שהוא אצל המשפיע ממש. רק שמלובש אצלו בבחי' הקטנות ביותר. דהיינו רק לפי צמצום אופן המובן לפי הגשמת המשל האחרון בלבד. אבל מ\"מ ה\"ז אותו המכוון שבשכל העמוק כמו שהוא בלי לבוש כלל. וה\"ז ממש כמו שתופס אדם בלבוש. שמ\"מ תופסו ממש רק שתופסו ע\"י לבוש:\nוכן כשרואה בשמש דרך מסך. הגם שאורו הוקטן אצלו ע\"י המסך:\n<b>מ\"מ</b> רואה ממש למהות השמש גם בהביט בו ע\"י המסך כו'. אך כל שהוא אור בהיר ביותר צריך להסתכל בו ע\"י מסכים רבים יותר כו' וד\"ל:\n(לח) <b>ועוד</b> זאת מובן שכדי להמציא משלים רבים. צריך זה עצמו להיות ע\"פ חכמה עמוקה ונפלאה. יותר מעצם גוף החכמה שרוצה להביאה במשל. כי הרי צריך לכוין לענין משל. שיהיה קרוב ודומה בנמשל. שישיגו ממנו השגת המכוון הפנימי שבנמשל וכן במשל למשל עד המשל האחרון. הרי באחרון דוקא שם ימצא עיקר המכוון מהמשל הראשון. ולזה צריך שכל עמוק יותר. דהיינו לידע פנימיות המכוון שבאותו שכל. בכדי למצוא לו משל שיהיה מובן ממנו כו'. וזה בהכרח מלמעלה מאותו השכל כמ\"ש במ\"א וד\"ל ונמצא מובן"],[2201340136,"עכ\"פ מכל ענין זה. שכל אור היותר עליון. צריך לבא בלבושים והעלמות רבות זו אחר זו לפי ערך רוממות מעלתו. וכל שאינו אור עליון כ\"כ א\"צ לבא בלבושי' והעלמות רבות כ\"כ. אך אעפ\"כ הרי כשהאור נראה כמו שהוא בלי לבוש והעלם כ\"כ. ודאי הוא יותר עליון מצד זה. מן האור העליון הימנו הרבה. אבל אינו נראה רק ע\"י לבושים רבים ביותר כו'. ולא ראי זה כראי זה כו' וד\"ל:\n(לט) <b>וכמו\"כ</b> יובן הדוגמא מכ\"ז. בטעם ענין ההפרש הנ\"ל בין תורה למצות שהוא ההפרש בין בחי' מו\"ס לבחי' גלגלתא כנ\"ל. להיות שבחי' מו\"ס שרשו אינו אור עליון כ\"כ כמו בשרש האור שבגלגלתא ע\"כ הוא מאיר בבחי' פנימית. דהיינו שמאיר במקומו בלי העלמות ולבושים כ\"כ. מפני שא\"צ בחי' לבושים והעלמות. כמשל חכמה שאינה עמוקה כ\"כ. שא\"צ להלבישה כ\"כ אלא מושגת כמו שהיא במקומה ועד\"מ כאשר אין חכמת המשפיע גדולה כ\"כ. הרי למי שחכם שמבין מדעתו. א\"צ לומר בלבוש משלים כלל. כי יבין השכל כמו שהוא בלי יצטרך להלבישנו כלל. ולקטני הערך שצריך להלביש אותו במשלים הנה אין ביכולתו להביא העמקות של השכל ההוא בלבושים ומשלים כלל. כי לא יוכל לכלכל דבריו באופן שיובן ע\"י עניני משל מפני שאין לו עומק באותו שכל וכידוע שכל מי שהוא חכם גדול ביותר. יודע העומק שבאותה חכמה יותר ע\"כ יוכל להביא החכמה ההיא בלבושים ומשלים רבים עד שיוכל לכלכל הדבר להבינו גם לתינוק קטן. משא\"כ מי שאינו חכם כ\"כ. אינו יודע בחכמה ההיא רק כמות שהיא דברים כהווייתן בלתי עומק המכוון שבה כו'. ע\"כ לא יוכל לידע איך להלבישה בלבושים ומשלים. להבינה גם לקטני ערך ביותר. רק למי שהוא חכם ומבין מדעתו. יוכל להשפיע השכל כמו שהוא בלבד (וכמ\"ש במ\"א) וזהו דמיון לענין הולדת ולד גשמי:\n<b>שהוא</b> בא מצד בחי' גדלות המוחין דוקא כשהוא בן ט' כו' ומזה מובן למעלה בענין אל עליון שהוא הארת הכתר בחכמה דוקא. אזי קונה הכל לבני בניהם כו') ונמצא גם מזה מובן עכ\"פ שכל אור שאינו עליון כ\"כ אינו מאיר רק לזולתו ורק כמו שהוא בלי הלבשה כו' ואינו יכול להשפיל א\"ע למטה מטה לקטנים ממקומו להתלבש בלבושים. אלא למטה מטה הימנו במדרגה הוא סתום ונעלם. כי הגם שירבה דברים. לא יבינו קטני הערך. ולהמציא משלים לא יוכל. מטעם שלא יוכל לכלכל דבריו בהתלבשות כלל. וכמשל האבוקה הקטנה שאינה מאירה למרחוק כלל רק במקומה והמקום הקרוב אליה כו'. וכמו\"כ לא יוכל זה החכם הקטן להאיר דברי חכמתו במקומות הרחוקים מערכו לקטנים וכה\"ג. ונשאר סתום ונעלם אצלם לגמרי. כמו שאין אור האבוקה הקטנה מגיע במקום הרחוק כלל וד\"ל:\n(מ) <b>והנמשל</b> מזה יובן ג\"כ בבחי' מו\"ס הנ\"ל הגם שנק' אור צח ומצוחצח. קטן הערך הוא לגבי עה\"ע. והוא מאיר בתוקף הארתו דוקא. למעלה במקומו כמו שהוא מטעם הנ\"ל. אבל בירידתו למטה במדרגות התחתונות הימנו הרי הוא נק' בשם בחי' מוחא סתימאה. דהיינו שהוא סתום ונעלם לגמרי מן המקבלים ואם היה אורו יורד בבחי' לבושים והעלמות. הרי היה מושג גם למטה מטה ע\"י בחי' הלבושים הללו. עד\"מ הנ\"ל בחכם גדול שיכול להוריד ולהשפיל אור חכמתו בכמה לבושים ומשלים עד שהתנוק יבינו ג\"כ כו'. אלא מזה מורה על היות שרש האור דמו\"ס. בקטנות הערך לגבי עה\"ע. ע\"כ נק' סתימאה לגבי התחתונים. וכמשל החכם הקטן שאור חכמתו נשאר סתום ונעלם לגבי קטני הערך שלמטה הימנו כו' כנ\"ל וד\"ל. אבל בחי' האור המאיר בגלגלתא. ה\"ז בא בבחי' לבוש חצוני. שהוא בחי' עצם הגלגלתא. אבל מזה הוראה גמורה על היות בחי' שרש הארה זו מעצמות אא\"ס. ממקום"],[2201340137,"ומדרגה עליונה ביותר. אשר ע\"כ ירד בלבושים והעלמות עד בחי' לבוש חצוני כזה דוקא לפי שכמו שהוא במקומו למעלה. לא יוכל כל אור להכילו כלל מצד עוצם רוממות ערכו. והוא בחי' עצמות אא\"ס דלית מחשבה תפיסא ביה כלל. דהיינו שלא נתפס בבחי' השגה. כמשל עומק החכמה ביותר. שלא יותפס כלל בהשגה כי אם ע\"י רבוי המשלים דוקא. וכמו\"כ בחי' עה\"ע עצמו לא יתגלה ויתפס למטה כ\"א בלבוש היותר חצוני שלפי ערך עומק רום כן ערך עומק תחת שהוא בחי' הלבושים והעלמות. להסתיר ולהעלים בלבוש חצוני יותר כמובן מענין הנ\"ל במשלי שלמה וד\"ל:\n(מא) <b>וזהו</b> ענין בחי' הגלגלתא. שהוא רק לבוש חצוני ביותר כמו שאנו רואים בחוש. שעצם הגלגלת גשמי הוא ואין לו ערך כלל וכלל לגבי בחי' הרוחניות הדקה שבמוח שמבפנים לגלגלת. שהרי כל החיות של כל הגוף תלוי בו. שהרי בקרום של מוח אם נקב במשהו טרפה. ובגלגלת עד שנחבסה רובה כו' כידוע והיינו לפי שבחי' רצון העליון שרשו בבחי' רעוא דכל רעוין שבעצמו' אא\"ס הפשוט כו'. אשר לעוצם רוממות ערכו למעלה במקומו דוקא. לא יוכל לבא לידי גלוי למטה כ\"א בבחי' החצונית. והוא בחינת עצם הגלגלתא. שבו שורה הרצון החצוני. שבלא טעם שהוא רק חצונית. לפנימיות המוחין הכמוס בו כנ\"ל. אך עם היותו בחי' חצונית. הרי הוא בחי' כלי להשראת אור עליון ביותר. שהוא בחי' רעוא דכ\"ר כו'. כמ\"ש באד\"ר מצחא דע\"י ביה גלי רצון דיליה כו'. וכמ\"ש במ\"א באריכות וד\"ל. (מב) וזהו ג\"כ ענין ההפרש בין מו\"ס לגלגלתא. בענין ירידת' למטה. שאור רצון העליון שבגלגלתא. מאיר ונמשך לבא למטה מטה בחצוניות ביותר. והוא ענין רצון העליון שבמעשה המצות בפ\"מ בדברים גשמיים כו'. משא\"כ בחי' מו\"ס. הגם שהוא בחי' סוד וטעמי המצות בבחי' פנימית לרצון העליון כנ\"ל מ\"מ א\"א שיבא בבחי' עשיה גשמית כרצון העליון החיצוני שבגלגלתא. רק בבחי' ההשגות הרוחניות. כמו אל נשמות הגבוהות. העומדים בסוד ה' כו' כמו רשב\"י וחבריו וכה\"ג וד\"ל. וה\"ז כמשל הנ\"ל בחכם הגדול. שלרוב עמקות חכמתו. לא יוכל זולתו להבין דבריו כ\"א ע\"י משל ומליצה. וגם מה שממציא משל חצוני ביותר. הוא לרוב עמקות חכמתו דוקא כנ\"ל. וזהו כמו האבוקה הגדולה שתאיר למרחוק ביותר כנ\"ל (והיותר רחוק גם מן המשלים. הוא ענין הרמז שמרמז דבר חכמה עמוקה בידו שהיא עשיה גשמית ממש בפועל היד. ובזה עומד ע\"ד עומק המכוון שבחכמה הנפלאה כמו דמחוו ליה במחוג כו'. וע\"כ לפי ערך זה נמשלה התורה למשלים כמ\"ש כאשר יאמר משל הקדמוני. שבמשל יש עכ\"פ איזה ענין שכלי הנדמה לנמשל כנ\"ל והוא ענין הנגלות שבתורה דוקא כנ\"ל והמצות שהן בבחי' עשיה גשמית הרי הן כמו בחי' הרמז. שבו נרמז עיקר פנימית המכוון שבעומקי החכמה עלאה כו' והיינו בחי' הארת הכתר בחכמה כמ\"ש והחכמה מאין כו' וד\"ל):\n(מג) <b>ובכל</b> הנ\"ל ג\"כ יובן ענין כללות ההפרש בין בחי' מקיפין לבחי' פנימיים כמ\"ש במ\"ח דלעיל. דבמקיפין התחתון מכולם גרוע מכולם. והוא בחי' חצונית הכתר שבבחי' גלגלתא הנ\"ל אבל שרשו בעליון מכלם המשובח מכלם והוא בחי' רעוא דכל רעוין כנ\"ל. ובחי' מו\"ס חכמה שבכתר. הוא ראשית ומקור כל הא\"פ והוא בחי' הפנימית מכולם שהוא משובח מכולם כי הרי בבחי' א\"פ דבחי' יושר באין בהתלבשות זה תוך זה כו' עד שהדבור ומעשה חצון מכולם ומקור החכמה שמאין תמצא הוא בחי' מו\"ס זה בחי' פנימית מכולם כו' אבל אינו נמשך למטה בחצונית כמו בחי' גלגלתא שמזה הוראה על שרש"],[2201340138,"שניהם במקומם למעלה ששרש אור הגלגלתא למעלה משרש האור דח\"ס וא\"כ הרי גם בחי' האחרונה שבמקיפים למעלה מבחי' היותר פנימי' שבפנימים כו' וד\"ל:\n(מד) <b>אך</b> עדיין יש להבין איך נק' בחי' מו\"ס בחי' או\"פ מאחר שנק' סתימא ונעלם מן המקבלים וכמ\"ש באד\"ר דבחי' חכמה דאצילות הנק' אבא הוא המתפתח לל\"ב שבילין כו' אבל בחי' מו\"ס זה לא מתפתח לל\"ב שבילין כו' ונק' מוחא דשקיט ושכיך באתריה כו' דהיינו שאינו בא בבחי' התגלות האור באצילות כו' אך זה ידוע שבהיות שמו\"ס זה הוא בחי' מקור לחכמה דאצי'. הגם שנק' אין שלו בבחי' ההעלם וע\"כ נק' מו\"ס. מ\"מ יחשב גם הוא בבחי' מקור לכל או\"פ עכ\"פ מאחר שנמצא מאתו בחי' התהוות חכמה בגלוי מאין ליש כו' רק שהוא מאיר בארח סתים ונעלם משא\"כ בחי' חכמה דאצי' למטה שמאיר בגלוי. בבחי' ל\"ב שבילין הנק' ל\"ב נ\"ח המאירים בבינה בבחי' השגה ממש. כידוע דאו\"א נק' תרין ריעין כו' והוא ענין ממלא כ\"ע בכלל אבל בחי' גלגלתא המקפת על המוחין ה\"ז בבחי' מקיף ממש שבלתי בא ממנו שפע אור בבחי' או\"פ לעולם רק בבחי' ההעלם ומקיף כמו הגלגלת שמקפת על המוחין כו' להיות בחי' כלי להשראת בחי' סובב הכללי שמקיף לד' עולמות כו' ששם הוא בחי' רעוא דכל רעוין כו' מקור כל המקיפין שבחי' גלגלתא זה הוא התחתון מכולם וחצונית מכולם אבל מצד שרשו בבחי' סובב הכללי כו' הוא למעלה גם מבחי' מו\"ס מקור כל או\"פ כנ\"ל ובזה יובן כללות ענין בחי' סובב וממלא שהוא מקיף ופנימי בכללות ההשתלשלות כידוע דהיינו בשרש בחי' מו\"ס וגלגלתא. שמשם מקור כל בחי' ממלא וסובב בכלל וד\"ל:\n(מה) <b>ומעתה</b> הנה יש להבין עוד מ\"ש בכמה דוכתי בע\"ח בענין שרש התהוות הכלים שהוא בא מבחי' הכאת האורות דמקיפים ופנימיים כשפוגע זה בזה כו' וזהו ביאור שרש ענין הנ\"ל בהתהוות יש גשמי שהוא בא מבחי' סובב דוקא כו' והנה תחלה יש להבין בשרש ענין הכלים מה הן בהיות ידוע שהכלים הן המגבילים את האור. פי' כי בחי' ע\"ס עצמן נק' ע\"ס בלי מה בלי מהות יש ודבר מה במציאות כלל רק בחי' אורות היוליים שאינם בבחי' מציאות דבר מה עדיין מפני שנכללין ועולים למעלה במקור חוצבם בבחי' הסתלקות והתכללות להיות נכללים במאצילם כמו שהיו טרם שנאצלו ממש כו' וזהו טבע כל בחי' אור שמסתלק ונכלל באור עצמות המאציל כמו עד\"מ בטול והתכללות אור הנר שעולה למעלה ואינו נאחז למטה להיות בבחי' יש ודבר בפ\"ע כלל לפי שזהו הכלל בכל בחי' עילה ועלול שטבע העלול להכלל ולהדבק בעילתו ולא יוכל להיות בחי' יש נפרד הימנו כלל וכלל וזה ידוע אשר האורות נאצלו מעצמות המאציל בבחי' עילה ועלול והוא ע\"י בחי' הקו והחוט שנמשך מאא\"ס אחר הצמצום דמק\"פ שהוא בחי' מקור הראשון של כל האורות עליונים. וע\"כ בחי' אור עצמות המאציל נק' בשם עילת כל העילות כו' ומאחר שבחי' אור הקו הזה הוא בחי' ההמשכה שבדרך השתלשלות עו\"ע הרי כל אור שנק' עלול נכלל ועולה תמיד להדבק בעילתו שהוא אור עצמות המאציל הנק' עה\"ע כבטול אור הנר בפני האבוקה וכה\"ג אמרו בס\"י שהע\"ס הן כשלהבת הקשורה בגחלת שר\"ל שאינם במציאות יש ודבר נפרד בפ\"ע כלל וכלל אבל המה כלולים וקשורים בעצמות המאציל דוקא וזהו כדמיון שלהבת שהיא קשורה וכלולה בעצמות הגחלת כו' וכמ\"ש בזהר דאיהו וחיוהי חד ממש ר\"ל שאינם בבחי' מציאות ויש בפ\"ע כלל וכלל ושרש הדבר הזה אינו רק משום דבחי' המשכת כל האורות ממקורן ושרשן הוא מבחי' הקו שהוא בא בבחי' עו\"ע וכל עלול נדבק בעילתו ממש בלי ניכר למהות ומציאת יש נפרד בפ\"ע כלל:"],[2201340139,"(מו) <b>ואמנם</b> הנה יש להבין באור ענין זה למעלה בע\"ס שאם אינן בבחינת מציאת יש כלל ונק' ע\"ס בלי מה כנ\"ל א\"כ איך נקרא בשם מציאות דבר מה כמו מהות חכמה ובינה וחסד וכה\"ג. ואע\"פ שאמר חכים ולא בחכמה ידיעא כו' מ\"מ הרי עכ\"פ חכים אתקרי כו' אך הענין הוא דמה שנקרא הע\"ס בשם מציאות דבר מה כמו חכים ומבין כו' זהו ענין ובחי' הכלים המגבילים את האור דהיינו שמגבילים ועושים את האור להיות בבחי' מציאות יש ודבר מה דוקא כמו אור החכמה הרי מצד האור גם שם חכים לא נקרא מאחר שבחי' אור זה כלול ונכלל באור עצמות המאציל כמו שלהבת הקשורה כו' וכה\"ג וא\"כ איך עולה בשם דבר מה להיות נק' חכים כנ\"ל אך מצד בחי' הכלי הוא שמוגבל להיות בתואר מציאת יש ודבר מה והוא מה שנתפס ונק' בשם חכים ומבין וכה\"ג שיש מציאות שנק' חכמה וכן אור החסד כשנתפס בבחי' יש ודבר להקרות בשם חסד היינו בחי' הכלים שמגבילים ומתארים תואר מציאות יש ודבר מה וכמו כלי אור החכמה היינו כשהחכמה נתפסת בבחי' יש ודבר מה במציאות להיות נק' חכמה הוא בחי' הכלי של אור ההיולי דחכמה כמו שנאצל מן המאציל כנ\"ל אבל אור החכמה אינו עולה בשם ותואר מציאות חכמה עדיין כנ\"ל וכן כלי החסד היינו בחי' המגביל ומתאר תואר ומציאת שם חסד. אבל אור החסד כלול באור המאציל בלתי נתפס בתואר ומציאות שם חסד עדיין וכן הוא בכל בחי' הכלים של האורות כמו כלי הנצח וכלי ההוד וכה\"ג וד\"ל:\n(מז) <b>אך</b> מעתה יש להבין מאין נמצא בחי' זו של הכלים להיות האורות נתפסים בבחי' יש ומציאות נפרד בפ\"ע כו'. מאחר שמצד עצמן הרי הן כלולים באור העצמות. כשלהבת הקשורה כו' כטבע כל עלול שנכלל בעילתו ממש. וע\"כ נק' ע\"ס בלי מה. בלי מהות כלל כנ\"ל. וא\"כ איך יהיה נמצא בהן דבר ההפכי מטבע עצמן לגמרי. מן הקצה לקצה. מאחר שמצד עצמותן א\"א להן להיות בבחי' יש ומציאות נפרד לעצמן כלל מטעם הנ\"ל. אמנם הענין הוא שזהו מה שאמר בע\"ח בכמה דוכתי בשרש התהוות בחי' הכלים של האורות. אינו מבחי' שרש ומקור אחד. עם שרש התהוות האורות. דשרש התהוות כל אור הרי הוא מבחי' הקו. אבל שרש התהוות הכלים המגבילים האור הנה הוא מבחי' סובב ומקיף הכללי שלפני בחי' הקו. שמשם דוקא נמצא בחי' השרש של התהוות הכלים. המגבילים ועושין לאורות בבחי' יש ודבר מה במציאות נפרד לעצמו כנ\"ל שאם היה שרש התהוות הכלים דאורות ג\"כ מבחי' הקו. שהוא בא בבחי' השתלשלות עו\"ע כנ\"ל. הרי לא היה יכול להיות בחי' הכלי המגביל לבחי' יש בפ\"ע. אלא גם בחי' הכלי היה בטל ונכלל למעלה כמו האור ממש כו'. אבל לפי ששרש בחי' הכלים בא מבחי' מקיף הכללי שלפני הקו. הנה דוקא משם יוכל להיות בחי' הגבלת הכלי. להיות האורות בבחי' יש ודבר מה כנ\"ל. ודוקא מבחי' הכאת האורות. דהיינו ע\"י שבחי' אור מקיף הכללי הנ\"ל שמכה ומאיר בפנימי שהוא בחי' הקו הנ\"ל מקור כל האור פנימי כו' וד\"ל:\n(מח) <b>ובאור</b> הדבר הנה ידוע בפי' בחי' מקיף וסובב. שהוא אור עליון דעצמות א\"ס. הבלתי בא בבחי' השפעה והמשכה של אור וחיות להתלבש בתוך העלול ממש הנקרא השתלשלות עו\"ע. אלא רק מרחוק הוא מאיר על כל ההשתלשלות דאבי\"ע. בבחי' מקיף וסובב בלבד. ומקיף לכולם בשוה ממש כמ\"ש בע\"ח. משא\"כ בחי' הקו שנמשך אחר הצמצום דמק\"פ. שבא בבחי' השפעת אור וחיות באבי\"ע שזהו בחי' ממלא כ\"ע כידוע משא\"כ בסובב כ\"ע. שאין האור המאיר מבחי' סובב. בא בבחי' התלבשות והשתלשלות עו\"ע. דהיינו שלא ע\"י בחי' השפעת אור ממנו. להתלבש בתוך ופנימית העלול אלא רק"],[2201340140,"מרחוק בהעלם מאיר עליו מלמעלה. דהיינו כמו שאמר כי הוא צוה ונבראו. צוה בצווי מרחוק. ולא שצווי זה נתלבש ובא בתוך דבר המתהווה. אלא ע\"י צווי זה ממילא נתהוו בבחי' יש. וכמ\"ש ונבראו ממילא. ולא אמר ובראם. שפי' בורא הוא הממשיך אור וחיות ממש. כח פועל ידיו בנפעל כו'. אבל אמר ונבראו היינו ממילא שלא ע\"י בחי' המשכת אור וחיות בפנימיות אותו דבר הנברא. ואעפ\"כ יוכל הנברא להיות חי וקים במציאות ישותו זה. ע\"י בחי' צווי זה דוקא. כי כל יכול הוא. ויכול להיות התהוות מציאות יש ודבר נפרד ממנו. שלא ע\"י בחי' השתלשלות עו\"ע ולהיות בבחי' יש ודבר דוקא משא\"כ בחינת ההשתלשלות דעו\"ע. הרי כל עלול נכלל בעילתו ואינו במציאות יש בפ\"ע. מפני שנלקח מעצם העילה. לפי שהעילה משפיע וממשיך בחי' אור וחיות מעצמותו בתוך פנימית העלול. ומפני כן טבע העלול להדבק בעילתו. כי הוא עצם מעצמיותו ואינו בחי' נפרד ממנו כלל כנ\"ל וד\"ל:\n(מט) <b>וזהו</b> ג\"כ הטעם מ\"ש בע\"ח דבחי' התהוות הכלים. נמשך מבחי' מקיף הכללי שהוא בחי' סובב שלפני הקו. מפני שהוא המאיר שלא ע\"י בחי' עו\"ע כנ\"ל. ע\"כ כל יכול הוא. להיות ממנו דוקא בחי' צמצום הגבלת הכלים שהוא לעשות האור בבחי' יש ודבר במציאות נפרד בפ\"ע. הפך טבע עצמותו. וכנ\"ל בענין צוה ונבראו. שזהו בחי' התהוות היש של הנברא. שהוא נמשך מבחי' סובב בבחי' צווי ממילא דוקא. שלא ע\"י בחי' השפעת עו\"ע כנ\"ל וד\"ל (אך עדיין אינו מובן. איך יוכל להיות כח בכלי. לעשות הפך טבע האור מצד עצמו כנ\"ל. אבל הענין הוא משום דשרש הכלים מבחי' מקיף שלפני הקו. הרי הוא למעלה מעלה מבחי' שרש האור. שהוא מבחי' הקו בלבד. ע\"כ יש בכלי כח ותגבורת. להתגבר על בחי' טבע האור שלא יוכלל למעלה. אלא להביאו למטה להיות בבחי' יש ודבר כו'. וזה הכח לבחי' הכלים הוא נמשך מצד שרשם למעלה. בבחי' המקיף שהוא הגובר על בחי' פנימית דקו כו'. והיינו שא' בע\"ח שהמקיפים מכה בא\"פ וע\"י הכאת המקיף בפנימי דוקא נעשה בחי' הכלים למטה כו'. שהוא ענין התגברות אור המקיף בהכאה זו להיות א\"פ נמשך ונתפס בבחי' יש ודבר שזהו בחי' הכלים המגבילים האור כנ\"ל אבל בלא הכאת אור המקיף בפנימיים רק מבחי' אור המקיף לבדו לא היה כל אור נתפס להיות בבחי' יש אלא דוקא מהכאת אור המקיף בפנימי דוקא. והיינו מבחי' הכאת האור דסובב. בקו שהוא בחי' ממלא כו'. וזהו כי הוא צוה כו'. מאחר שהבריאה היא בבחי' השתלשלות דעו\"ע מבחי' הקו א\"כ כדי שיהיה בבחי' יש צריך להיות נמשך מבחי' מקיף המכה ומאיר על הפנימיים דוקא כו' וד\"ל:\n(נ) <b>והנה</b> ראיה ברורה לענין הנ\"ל שכל בחי' התהוות יש ודבר בפ\"ע הוא מבחי' סובב ומקיף הכללי דוקא. הנה יובן ד\"ז יותר ממה שאנו רואים בבחי' התהוות עולם השפל שלנו החומרי והגשמי בכל דצ\"ח גשמיים שבו וגם בכל הברואים שבשמים וארץ וכל אשר בהם כו' בהיות ידוע שבי' מאמרות נבראו כל העולמות כו' וכמו על ידי מאמר יהי אור נברא האור מאין ליש ועל ידי מאמר יהי רקיע נברא הרקיע מאין ליש כידוע אמנם הנה מ\"ש יהי אור ויהי אור יש בזה ב' מדרגות הא' בחי' הארת אור האלקי שמשפיע בחי' רוחניות אור וחיות האלקי והוא בחי' אותיות האלקיים דמאמר זה יהי אור ואותיות הללו דיהי אור הוא בחי' מקור החיות לבריאת האור כידוע אבל כל זה אינו אלא דוקא בחי' ההשפעה הרוחנית האלקית להיות התהוות האור מבחי' אין כו' אך מה שאמר ויהי אור הוא מדרגה שני' בפ\"ע והוא מה שנתהווה האור במציאות יש ממש שזה נמשך מבחי' סובב דוקא"],[2201340141,"שלמעלה מן הי' מאמרות כי התהוות גשמיות היש של כל נברא א\"א שיומשך מבחי' האור וחיות הרוחנית האלקית המלובש במאמרות עצמן שהן בחי' המשכת חיות רוחני של כל הנבראים בבחי' ממלא כ\"ע כנ\"ל מאחר שאין ערוך כלל וכלל בין גשמיות לרוחניות ואין להם ענין שתוף וחבור בסוג כלל וא\"כ איך יתהווה היש החומרי של מציאת האור מבחי' האותיות הרוחניים האלקיים דיהי אור וכה\"ג אלא ע\"ז אמר ויהי אור פי' מהות גשם האור נתהווה ע\"פ צווי ה' הבא מבחי' סובב דוקא כנ\"ל בענין כי הוא צוה ונבראו דצוה ונבראו זה היינו בכל פרטי המשכת אור האלקי שבאמצעות הי' מאמרות הוא צוה ונבראו להיות בחינת היש החומרי שלהם כי מהמאמרות לא נמשך רק בחי' חיות רוחני שלהם כנ\"ל וע\"כ נאמר ויהי כן בכל המאמרות. מפני שהוצרך להתהוות גשמיות היש שלהם להמשיך מבחי' סובב כו' וזהו ויהי כן כמו כי הוא צוה ונבראו לבחי' יש כו' והיינו שתיבת ויהי הוא שם הוי\"ה חסר ה' אחרונה כי יו\"ד במקומה בהיות כי המשכה זו היא מבחי' אין דסובב כו' וד\"ל. וכן הוא בהתהוות כל גשם מן הרוחני למטה שבודאי א\"א שימצא הגשם מן הרוחני מאחר שהרוחני מושלל לגמרי מגדר וסוג הגשם ואין להם חבור ויחוס ערך להיות הסתעפות מזה לזה כשאר עו\"ע וא\"כ מאין יכול להיות התהוות מהות גשם הצומח דעשב ואילן מן בחי' הרוחני דמזלות או כח הצומח שבארץ שמצמיח ע\"י מאמר תדשא הארץ שמלובש בו מאחר שא\"א לומר שהרוחני יוליד ויצמיח גשמי אלא בהכרח לומר שהתהוות גשם הצומח דעשב ואילן הוא בא מלמעלה מבחי' הרוחנית דכח הצומח כו' דהיינו מבחי' המקיף וסובב כו' אבל מבחי' הרוחנית דכח הצומח לא נמשך רק בחי' חיות רוחנית של העשב והאילן בלבד כנ\"ל בענין המאמרות וכה\"ג יובן בכל הנבראים הפרטים בכל פרטי חלקי דצ\"ח וד' יסודות הגשמיים שהתהוות גשם מהותן נמשך מבחי' סובב כו' שהוא למעלה מבחי' מקור האור והחיות רוחנית שלהם שאינו רק מבחי' ממלא שהן בחי' המאמרות בכלל וד\"ל:\n(נא) <b>אך</b> עדיין יש להבין איך יתכן להיות בחי' התהוות כל יש גשמי מבחינת סובב דוקא מאחר שלגבי בחי' סובב שוה רוחנית וגשמית ממש וכמ\"ש בע\"ח דבחי' מקיף הכללי הוא מקיף לד' עולמות דאבי\"ע בשוה ממש וא\"כ בחי' ראשית האצילות שהו' בחי' ח\"ע עם סוף העשי' כמו התהוות גשם הצומח והדומם שוין לפניו ממש כו' ולפ\"ז איך נאמר שבחי' הארת הסובב נמשך בכל פרטי התהוות יש עד התהוות יש דדצ\"ח שבעה\"ז כו' אמנם הנה התירוץ לזה הוא מני' וביה דאדרבא היא הנותנת דמשום שבחי' סובב זה הוא מובדל ומרומם בערך מכל ההשתלשלות עד ששוה לפניו ראש וסוף כנ\"ל ע\"כ כל יכול הוא להיות ממנו בחי' התהוות דבר יש גשמי ג\"כ כי יוכל להיות ממנו התהוות דבר בדלוג הערך ביותר מאחר שנבדל ומרומם מהכל וע\"כ נק' כל יכול כו' וד\"ל. ובאור ד\"ז הנה ידוע בענין אין ערוך לך כו' שזהו במה ששוין לפניו ראש וסוף ממש בהשוואה אחת כמו בחי' ח\"ע שנקרא ראשית כל האצילות וסוף העשיה הגשמית שוין ממש בערך א' לפניו שאם יש לבחי' הח\"ע יותר קרוב הערך קצת לגבי' מסוף העשיה שרחוק בדלוג הערך יותר מצד שח\"ע היא ראש האצילות הרוחני והעשי' היא סוף כל המדרגות כו' א\"כ ה\"ז בבחי' ערך ושייכות עם בחי' ההשתלשלות דממלא בבחי' ראש וסוף אלא בהכרח לומר ששניהם בשוה אין ערוך להם בתכלית הריחוק וא\"כ הרי כמו שהתהוות היש הגשמי הוא בא בדילוג וריחוק הערך מבחי' סובב כמו\"כ ממש בחי' התהוות ח\"ע דאצי' בא בדלוג ורחוק ערך מבחי' סובב שא\"א לומר שבחי' ח\"ע אינו בא בדלוג וריחוק הערך כ\"כ להיותו בבחי' ראש בהשתלשלות שא\"כ יפול בו בחי' ערך לגבי בחי' סובב ואין זה כפי האמת בענין"]]});
